window.CORPUS = {"friuli-pf":{"id":"friuli-pf","file":"tei/friuli-pf.xml","title":"San Pieri nelle Pagine friulane: cinque leggende","lang":"fur","dialect":{"en":"Friulian","it":"friulano"},"places":[{"id":"gorizia","name":"Gorizia","wikidata":["https://www.wikidata.org/wiki/Q6596"],"lat":45.9352,"lon":13.6193},{"id":"cavazzo","name":"Cavazzo Carnico","wikidata":["https://www.wikidata.org/wiki/Q53239","https://www.wikidata.org/wiki/Q1051808"],"lat":46.3667,"lon":13.0333},{"id":"carnia","name":"Carnia (Clavais, Avosacco, Cedarchis, Incaroio, Racolana)","wikidata":["https://www.wikidata.org/wiki/Q369765","https://www.wikidata.org/wiki/Q53217"],"lat":46.4724,"lon":13.0267},{"id":"orgnano","name":"Orgnano (Basiliano)","wikidata":["https://www.wikidata.org/wiki/Q3885756"],"lat":46.0073,"lon":13.1421}],"persons":[{"id":"giobi","name":"Giobi","role":"author of n. I (a pseudonym)","wikidata":null},{"id":"ostermann","name":"Valentino Ostermann","role":"author of n. III, signed “V. O.”","wikidata":"https://www.wikidata.org/wiki/Q15689538"},{"id":"gortani","name":"Luigi Gortani","role":"author of n. IV, signed “L. Gortani”","wikidata":"https://www.wikidata.org/wiki/Q21514145"},{"id":"great","name":"V. Great","role":"author of n. V","wikidata":null}],"sources":[{"type":"source","text":"Pagine friulane. Periodico mensile, Udine, Domenico Del Bianco, 1888–1907; the five legends appeared in 1890, 1892, 1893 and 1894. Transcribed from the page images of the copies digitised by Google, Internet Archive.","links":["https://archive.org/search?query=title%3A%28pagine+friulane%29"]},{"type":"retelling","text":"Italo Calvino, Fiabe italiane, Torino, Einaudi, 1956: “Gesù e San Pietro in Friuli”, whose fourth tale, “Il grano saraceno”, is on the origin of buckwheat told in n. I.","links":["https://www.wikidata.org/wiki/Q154756","https://www.wikidata.org/wiki/Q3744324"]}],"heads":{},"editorial":null,"units":[{"id":"pf-sarasin","kind":"tale","n":"I","heads":{"orig":"L’orìgin de ’l sarasìn","it":"L’origine del grano saraceno","en":"The origin of buckwheat"},"refs":["giobi","gorizia"],"record":["Pagine friulane, a. III (1890), n. 8, pp. 131–132, Internet Archive; ATU Christ and Peter in the Barn (assigned 2026). Alto Friuli orientale; signed “Gorizia, 24 agosto. Giobi”."],"passages":[{"id":"pf-sarasin-1","n":"I.1","start":true,"orig":["Il Signor, San Pieri e Sant Iacun entràrin une sere in-t’une chase e domandàrin di durmî. Ere ’l timp de ’l bati-forment; e la parone ur rispuindè, che jê ju alozàve par che’ gnott, se lor si obleàvin di bàtigi te ’l doman di matine une ariade di forment. Lor gi imprometèrin di bàtilu, e dopo di vê cenàd fòrin menàds a durmî duch tre t’un jett."],"it":["Il Signore, San Pietro e San Giacomo entrarono una sera in una casa e chiesero di dormire. Era il tempo della trebbiatura del frumento; e la padrona rispose che li avrebbe alloggiati per quella notte, se si fossero impegnati a batterle il mattino dopo un’aia di frumento. Promisero di batterlo, e dopo cena furono condotti a dormire tutti e tre in un letto."],"en":["The Lord, St Peter and St James came into a house one evening and asked for a bed. It was threshing time; and the mistress of the house answered that she would put them up for the night if they undertook to thresh her a floorful of wheat the next morning. They promised to thresh it, and after supper all three were taken to sleep in one bed."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-sarasin-1\" n=\"I.1\" rend=\"p-start\">\n            <p>Il Signor, San Pieri e Sant Iacun entràrin une sere in-t’une chase e domandàrin di durmî. Ere ’l timp de ’l bati-forment; e la parone ur rispuindè, che jê ju alozàve par che’ gnott, se lor si obleàvin di bàtigi te ’l doman di matine une ariade di forment. Lor gi imprometèrin di bàtilu, e dopo di vê cenàd fòrin menàds a durmî duch tre t’un jett.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-1\">\n            <p>Il Signore, San Pietro e San Giacomo entrarono una sera in una casa e chiesero di dormire. Era il tempo della trebbiatura del frumento; e la padrona rispose che li avrebbe alloggiati per quella notte, se si fossero impegnati a batterle il mattino dopo un’aia di frumento. Promisero di batterlo, e dopo cena furono condotti a dormire tutti e tre in un letto.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-1\">\n            <p>The Lord, St Peter and St James came into a house one evening and asked for a bed. It was threshing time; and the mistress of the house answered that she would put them up for the night if they undertook to thresh her a floorful of wheat the next morning. They promised to thresh it, and after supper all three were taken to sleep in one bed.</p>\n          </div>"},{"id":"pf-sarasin-2","n":"I.2","start":false,"orig":["In-t’al doman mai e’ no jevàvin. La parone di chase vedùd, che no capitàvin mai dabass, ju clame. Ma lor anchimò miezz indurmidìds e’ no si mòvin. Po ur torne a sberlâ, che jere ben ore di saltâ fûr da ’l nid, une volte. Ma lor no la abàdin: e’ àn chatàd un jett masse musulitt. Jê spiete un pôc e dopo stufàde chape sù un bastòn, và disore e j’ mole cuatri a San Pieri, che lu chate ’l prin di che’ bande, disind, che cussì si dev tratâ cu-i poltrons; e va jù. Torne a spietâ par vedê, se la vèssin capide. Ma ’l jett l’è une calamite, che ju tire a sè masse fuart, e lor rèstin salds. Alore e’ torne sù cu ’l so len."],"it":["L’indomani non si alzavano mai. La padrona di casa, visto che non scendevano, li chiama. Ma loro, ancora mezzo addormentati, non si muovono. Poi torna a gridare che era ben ora, una buona volta, di saltar fuori dal nido. Ma loro non le badano: hanno trovato un letto troppo morbido. Lei aspetta un poco e poi, stufa, prende un bastone, va di sopra e ne molla quattro a San Pietro, che trova per primo da quella parte, dicendo che così si trattano i poltroni; e torna giù. Aspetta di nuovo per vedere se l’avessero capita. Ma il letto è una calamita che li tira a sé troppo forte, e loro restano fermi. Allora lei torna su col suo legno."],"en":["Next morning they never got up. The mistress of the house, seeing that they never came down, calls them. But they, still half asleep, do not stir. Then she shouts again that it was high time, for once, to jump out of the nest. But they pay her no heed: they have found too soft a bed. She waits a little and then, fed up, picks up a stick, goes upstairs and lets fly four blows at St Peter, whom she finds first on that side, saying that this is how lazybones should be treated; and down she goes. She waits again to see whether they had understood. But the bed is a magnet that pulls them too hard, and they stay put. So up she comes again with her stick."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-sarasin-2\" n=\"I.2\">\n            <p>In-t’al doman mai e’ no jevàvin. La parone di chase vedùd, che no capitàvin mai dabass, ju clame. Ma lor anchimò miezz indurmidìds e’ no si mòvin. Po ur torne a sberlâ, che jere ben ore di saltâ fûr da ’l nid, une volte. Ma lor no la abàdin: e’ àn chatàd un jett masse musulitt. Jê spiete un pôc e dopo stufàde chape sù un bastòn, và disore e j’ mole cuatri a San Pieri, che lu chate ’l prin di che’ bande, disind, che cussì si dev tratâ cu-i poltrons; e va jù. Torne a spietâ par vedê, se la vèssin capide. Ma ’l jett l’è une calamite, che ju tire a sè masse fuart, e lor rèstin salds. Alore e’ torne sù cu ’l so len.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-2\">\n            <p>L’indomani non si alzavano mai. La padrona di casa, visto che non scendevano, li chiama. Ma loro, ancora mezzo addormentati, non si muovono. Poi torna a gridare che era ben ora, una buona volta, di saltar fuori dal nido. Ma loro non le badano: hanno trovato un letto troppo morbido. Lei aspetta un poco e poi, stufa, prende un bastone, va di sopra e ne molla quattro a San Pietro, che trova per primo da quella parte, dicendo che così si trattano i poltroni; e torna giù. Aspetta di nuovo per vedere se l’avessero capita. Ma il letto è una calamita che li tira a sé troppo forte, e loro restano fermi. Allora lei torna su col suo legno.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-2\">\n            <p>Next morning they never got up. The mistress of the house, seeing that they never came down, calls them. But they, still half asleep, do not stir. Then she shouts again that it was high time, for once, to jump out of the nest. But they pay her no heed: they have found too soft a bed. She waits a little and then, fed up, picks up a stick, goes upstairs and lets fly four blows at St Peter, whom she finds first on that side, saying that this is how lazybones should be treated; and down she goes. She waits again to see whether they had understood. But the bed is a magnet that pulls them too hard, and they stay put. So up she comes again with her stick.</p>\n          </div>"},{"id":"pf-sarasin-3","n":"I.3","start":true,"orig":["Apene che ’l Signor la sint vignî pe’ schale, al dis a San Pieri:","— Pieri, ven cà t’al miezz, che no ti torni dâ a ti.","L’è juste comedàd in-t’al miezz San Pieri, che càpite la parone donge ’l jett e ur dis:","— Prime ài petàd j’ al prin; cumò i spacarai el polvar a chell in-te ’l miezz.","E cussì San Pieri lis chapà pe’ seconde volte."],"it":["Appena il Signore la sente venire per le scale, dice a San Pietro:","«Pietro, vieni qui in mezzo, che non tocchi di nuovo a te.»","San Pietro si è appena sistemato in mezzo, che arriva la padrona vicino al letto e dice:","«Prima ho picchiato il primo; adesso spolvero quello in mezzo.»","E così San Pietro le prese per la seconda volta."],"en":["As soon as the Lord hears her on the stairs, he says to St Peter:","“Peter, come here into the middle, so it won’t be your turn again.”","St Peter has only just settled in the middle when the mistress comes up to the bed and tells them:","“First I beat the first one; now I’ll dust down the one in the middle.”","And so St Peter got it a second time."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-sarasin-3\" n=\"I.3\" rend=\"p-start\">\n            <p>Apene che ’l Signor la sint vignî pe’ schale, al dis a San Pieri:</p>\n            <p>— Pieri, ven cà t’al miezz, che no ti torni dâ a ti.</p>\n            <p>L’è juste comedàd in-t’al miezz San Pieri, che càpite la parone donge ’l jett e ur dis:</p>\n            <p>— Prime ài petàd j’ al prin; cumò i spacarai el polvar a chell in-te ’l miezz.</p>\n            <p>E cussì San Pieri lis chapà pe’ seconde volte.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-3\">\n            <p>Appena il Signore la sente venire per le scale, dice a San Pietro:</p>\n            <p>«Pietro, vieni qui in mezzo, che non tocchi di nuovo a te.»</p>\n            <p>San Pietro si è appena sistemato in mezzo, che arriva la padrona vicino al letto e dice:</p>\n            <p>«Prima ho picchiato il primo; adesso spolvero quello in mezzo.»</p>\n            <p>E così San Pietro le prese per la seconda volta.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-3\">\n            <p>As soon as the Lord hears her on the stairs, he says to St Peter:</p>\n            <p>“Peter, come here into the middle, so it won’t be your turn again.”</p>\n            <p>St Peter has only just settled in the middle when the mistress comes up to the bed and tells them:</p>\n            <p>“First I beat the first one; now I’ll dust down the one in the middle.”</p>\n            <p>And so St Peter got it a second time.</p>\n          </div>"},{"id":"pf-sarasin-4","n":"I.4","start":false,"orig":["Tornàde jù la parone di chase, lor no si scomponèvin frègul, come se no foss sucedùd nuie. Ma il Signor, che ’l saveve, che la femine veve di tornâ in chamare, al si rivolzè a San Pieri:","— Sas-tu ce fâ, Pieri, par che no ti torni a cuziâ? Tu dèvis lâ di che’ altre bande; cussì cuand-che jê rivarà sù dute invelegnàde, la rabie no j’ lassarà timp di distiràssi su pa ’l jett, par tochâ il tiarz, ma petarà jù par di-lung e par traviars a cui che j’ càpite, càpite.","Ma lafè sì che San Pieri al fo fortunàd a mètisi di là; parcè-che la parone curìde disore dute imbilàde, ur sberlà:","— Ce us parie’ anchimò, svergonzòs, che no sei ore di finìle? ’O vês ulùd spietâ propri di provâ il baston duch tre! Spietàit, spietàit, us serviss ben jò. La prime volte ai unzùd chell di cà; dopo chell di miezz; e cumò ’o batarài il tiarz.","In cheste maniere chell pùar San Pieri al fo cuinzad pe ’s fiestis tre voltis."],"it":["Tornata giù la padrona di casa, loro non si scomponevano per niente, come se non fosse successo nulla. Ma il Signore, che sapeva che la donna sarebbe tornata in camera, si rivolse a San Pietro:","«Sai che cosa fare, Pietro, perché non tocchi ancora a te? Devi andare dall’altra parte; così, quando lei arriverà su tutta inviperita, la rabbia non le lascerà il tempo di allungarsi sul letto per toccare il terzo, ma picchierà per lungo e per traverso chi le capita, capita.»","Ma, in fede mia, San Pietro fu fortunato a mettersi di là; perché la padrona, corsa di sopra tutta infuriata, gridò loro:","«Che vi pare ancora, svergognati, che non sia ora di finirla? Avete voluto aspettare di provare il bastone tutti e tre! Aspettate, aspettate, vi servo ben io. La prima volta ho unto quello di qua; poi quello di mezzo; e adesso batterò il terzo.»","In questa maniera quel povero San Pietro fu conciato per le feste tre volte."],"en":["Once the mistress had gone back down, they were not a whit put out, as if nothing had happened. But the Lord, who knew the woman would come back to the room, turned to St Peter:","“Do you know what to do, Peter, so it won’t be your turn again? You must go to the other side; then when she comes up in a fury, her rage won’t leave her time to reach across the bed to the third, and she’ll lay about her lengthways and crossways at whoever comes to hand.”","But my word, St Peter was lucky to move over; for the mistress, running upstairs in a rage, yelled at them:","“What do you think now, you shameless lot, isn’t it time to stop? You wanted to wait until all three of you had tasted the stick! Wait, wait, I’ll see to you. The first time I greased the one on this side; then the one in the middle; and now I’ll beat the third.”","And that is how poor St Peter was given a good dressing-down three times over."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-sarasin-4\" n=\"I.4\">\n            <p>Tornàde jù la parone di chase, lor no si scomponèvin frègul, come se no foss sucedùd nuie. Ma il Signor, che ’l saveve, che la femine veve di tornâ in chamare, al si rivolzè a San Pieri:</p>\n            <p>— Sas-tu ce fâ, Pieri, par che no ti torni a cuziâ? Tu dèvis lâ di che’ altre bande; cussì cuand-che jê rivarà sù dute invelegnàde, la rabie no j’ lassarà timp di distiràssi su pa ’l jett, par tochâ il tiarz, ma petarà jù par di-lung e par traviars a cui che j’ càpite, càpite.</p>\n            <p>Ma lafè sì che San Pieri al fo fortunàd a mètisi di là; parcè-che la parone curìde disore dute imbilàde, ur sberlà:</p>\n            <p>— Ce us parie’ anchimò, svergonzòs, che no sei ore di finìle? ’O vês ulùd spietâ propri di provâ il baston duch tre! Spietàit, spietàit, us serviss ben jò. La prime volte ai unzùd chell di cà; dopo chell di miezz; e cumò ’o batarài il tiarz.</p>\n            <p>In cheste maniere chell pùar San Pieri al fo cuinzad pe ’s fiestis tre voltis.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-4\">\n            <p>Tornata giù la padrona di casa, loro non si scomponevano per niente, come se non fosse successo nulla. Ma il Signore, che sapeva che la donna sarebbe tornata in camera, si rivolse a San Pietro:</p>\n            <p>«Sai che cosa fare, Pietro, perché non tocchi ancora a te? Devi andare dall’altra parte; così, quando lei arriverà su tutta inviperita, la rabbia non le lascerà il tempo di allungarsi sul letto per toccare il terzo, ma picchierà per lungo e per traverso chi le capita, capita.»</p>\n            <p>Ma, in fede mia, San Pietro fu fortunato a mettersi di là; perché la padrona, corsa di sopra tutta infuriata, gridò loro:</p>\n            <p>«Che vi pare ancora, svergognati, che non sia ora di finirla? Avete voluto aspettare di provare il bastone tutti e tre! Aspettate, aspettate, vi servo ben io. La prima volta ho unto quello di qua; poi quello di mezzo; e adesso batterò il terzo.»</p>\n            <p>In questa maniera quel povero San Pietro fu conciato per le feste tre volte.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-4\">\n            <p>Once the mistress had gone back down, they were not a whit put out, as if nothing had happened. But the Lord, who knew the woman would come back to the room, turned to St Peter:</p>\n            <p>“Do you know what to do, Peter, so it won’t be your turn again? You must go to the other side; then when she comes up in a fury, her rage won’t leave her time to reach across the bed to the third, and she’ll lay about her lengthways and crossways at whoever comes to hand.”</p>\n            <p>But my word, St Peter was lucky to move over; for the mistress, running upstairs in a rage, yelled at them:</p>\n            <p>“What do you think now, you shameless lot, isn’t it time to stop? You wanted to wait until all three of you had tasted the stick! Wait, wait, I’ll see to you. The first time I greased the one on this side; then the one in the middle; and now I’ll beat the third.”</p>\n            <p>And that is how poor St Peter was given a good dressing-down three times over.</p>\n          </div>"},{"id":"pf-sarasin-5","n":"I.5","start":true,"orig":["Restàds sôi po, lui al scomenzà a lamentàsi cu ’l Signor:","— La veso viodùde, Signor, che’ brute strie, che si è sfogàde indaùr cun me’. Mi pareve, che vevi di jessi simpri jò chell de ’s pàchis. Vo mi mandàvis a pueste di cà par che lis becass jò; cumò po jò mi alzi, e se olès jevâ anche vo’ altris, jevàit, se no, stàit lì, sin cuand che si stufàis, e magari fin che us macoe anche a vo’ altris i uess come a mi.","— No stâ schaldàti tant, Pieri, — lu cholève atòr anchemò ’l Signor — zà no ti à fatt tant mal, che tu fas vedê. Cumò ve’ ti à copàd! Sì, sì: jevarìn anche no’ par contentàti.","San Pieri no ’l rispuindè nuie; ma rugnand in jenfre ai ding al si alzà cun lor e vignìrin jù duch tre."],"it":["Rimasti soli, lui cominciò a lamentarsi col Signore:","«L’avete vista, Signore, quella brutta strega, che si è sfogata di nuovo con me? Mi pareva di dover essere sempre io quello delle botte. Voi mi mandavate apposta di qua perché le prendessi io; adesso io mi alzo, e se volete alzarvi anche voi, alzatevi, se no state lì finché vi stufate, e magari finché vi ammacca le ossa anche a voi come a me.»","«Non scaldarti tanto, Pietro,» lo canzonava ancora il Signore, «non ti ha fatto poi tanto male come vuoi far vedere. Adesso, vedi, ti ha ucciso! Sì, sì: ci alzeremo anche noi per accontentarti.»","San Pietro non rispose nulla; ma brontolando tra i denti si alzò con loro e scesero tutti e tre."],"en":["Left alone at last, he began to complain to the Lord:","“Did you see her, Lord, that ugly witch, taking it out on me again? It seemed I always had to be the one for the blows. You sent me over here on purpose so that I’d be the one to get them; now I’m getting up, and if you want to get up too, get up; if not, stay there until you’re tired of it, and maybe until she bruises your bones too, like mine.”","“Don’t get so heated, Peter,” the Lord teased him still, “she hasn’t hurt you as much as you make out. Look, now she’s killed you! Yes, yes: we’ll get up too, to please you.”","St Peter said nothing; but grumbling under his breath he got up with them, and all three came downstairs."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-sarasin-5\" n=\"I.5\" rend=\"p-start\">\n            <p>Restàds sôi po, lui al scomenzà a lamentàsi cu ’l Signor:</p>\n            <p>— La veso viodùde, Signor, che’ brute strie, che si è sfogàde indaùr cun me’. Mi pareve, che vevi di jessi simpri jò chell de ’s pàchis. Vo mi mandàvis a pueste di cà par che lis becass jò; cumò po jò mi alzi, e se olès jevâ anche vo’ altris, jevàit, se no, stàit lì, sin cuand che si stufàis, e magari fin che us macoe anche a vo’ altris i uess come a mi.</p>\n            <p>— No stâ schaldàti tant, Pieri, — lu cholève atòr anchemò ’l Signor — zà no ti à fatt tant mal, che tu fas vedê. Cumò ve’ ti à copàd! Sì, sì: jevarìn anche no’ par contentàti.</p>\n            <p>San Pieri no ’l rispuindè nuie; ma rugnand in jenfre ai ding al si alzà cun lor e vignìrin jù duch tre.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-5\">\n            <p>Rimasti soli, lui cominciò a lamentarsi col Signore:</p>\n            <p>«L’avete vista, Signore, quella brutta strega, che si è sfogata di nuovo con me? Mi pareva di dover essere sempre io quello delle botte. Voi mi mandavate apposta di qua perché le prendessi io; adesso io mi alzo, e se volete alzarvi anche voi, alzatevi, se no state lì finché vi stufate, e magari finché vi ammacca le ossa anche a voi come a me.»</p>\n            <p>«Non scaldarti tanto, Pietro,» lo canzonava ancora il Signore, «non ti ha fatto poi tanto male come vuoi far vedere. Adesso, vedi, ti ha ucciso! Sì, sì: ci alzeremo anche noi per accontentarti.»</p>\n            <p>San Pietro non rispose nulla; ma brontolando tra i denti si alzò con loro e scesero tutti e tre.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-5\">\n            <p>Left alone at last, he began to complain to the Lord:</p>\n            <p>“Did you see her, Lord, that ugly witch, taking it out on me again? It seemed I always had to be the one for the blows. You sent me over here on purpose so that I’d be the one to get them; now I’m getting up, and if you want to get up too, get up; if not, stay there until you’re tired of it, and maybe until she bruises your bones too, like mine.”</p>\n            <p>“Don’t get so heated, Peter,” the Lord teased him still, “she hasn’t hurt you as much as you make out. Look, now she’s killed you! Yes, yes: we’ll get up too, to please you.”</p>\n            <p>St Peter said nothing; but grumbling under his breath he got up with them, and all three came downstairs.</p>\n          </div>"},{"id":"pf-sarasin-6","n":"I.6","start":true,"orig":["La femine, che ju spietave abass de’ schale, ur mostrà il forment in-t’une chamare e cun male grazie ur disè:","— Là l’è. Paràilu fûr, tindìlu e cà son i batài!","Lor scomencin senze dî nuie a puartàlu tal miezz de ’l bearz e a mètilu t’un grum. Jê ur mostre, che bisugnave slargiàlu par dute l’arie; ma e’ à un biell insegnàur; chei altris tre e’ continuavin a lavorâ a lor mùd, senze contàle come chell de ’s côts."],"it":["La donna, che li aspettava ai piedi della scala, mostrò loro il frumento in una camera e con malagrazia disse:","«Eccolo lì. Portatelo fuori, stendetelo, e qui ci sono i correggiati!»","Senza dire nulla cominciano a portarlo in mezzo al cortile e a metterlo in un mucchio. Lei mostra loro che bisognava allargarlo per tutta l’aia; ma ha un bell’insegnare: quegli altri tre continuavano a lavorare a modo loro, senza darle retta."],"en":["The woman, who was waiting for them at the foot of the stairs, showed them the wheat in a room and said ungraciously:","“There it is. Carry it out, spread it, and here are the flails!”","Without a word they begin to carry it into the middle of the yard and pile it in a heap. She shows them that it had to be spread over the whole threshing floor; but she can teach all she likes: the other three went on working their own way, paying her not the slightest heed."],"note":"“Senze contàle come chell de ’s côts”, literally “counting her like the man of the whetstones”, is an idiom for paying someone no heed.","xml":"<div type=\"passage\" xml:id=\"pf-sarasin-6\" n=\"I.6\" rend=\"p-start\">\n            <p>La femine, che ju spietave abass de’ schale, ur mostrà il forment in-t’une chamare e cun male grazie ur disè:</p>\n            <p>— Là l’è. Paràilu fûr, tindìlu e cà son i batài!</p>\n            <p>Lor scomencin senze dî nuie a puartàlu tal miezz de ’l bearz e a mètilu t’un grum. Jê ur mostre, che bisugnave slargiàlu par dute l’arie; ma e’ à un biell insegnàur; chei altris tre e’ continuavin a lavorâ a lor mùd, senze contàle come chell de ’s côts.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-6\">\n            <p>La donna, che li aspettava ai piedi della scala, mostrò loro il frumento in una camera e con malagrazia disse:</p>\n            <p>«Eccolo lì. Portatelo fuori, stendetelo, e qui ci sono i correggiati!»</p>\n            <p>Senza dire nulla cominciano a portarlo in mezzo al cortile e a metterlo in un mucchio. Lei mostra loro che bisognava allargarlo per tutta l’aia; ma ha un bell’insegnare: quegli altri tre continuavano a lavorare a modo loro, senza darle retta.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-6\">\n            <p>The woman, who was waiting for them at the foot of the stairs, showed them the wheat in a room and said ungraciously:</p>\n            <p>“There it is. Carry it out, spread it, and here are the flails!”</p>\n            <p>Without a word they begin to carry it into the middle of the yard and pile it in a heap. She shows them that it had to be spread over the whole threshing floor; but she can teach all she likes: the other three went on working their own way, paying her not the slightest heed.</p>\n            <note type=\"translation\">“Senze contàle come chell de ’s côts”, literally “counting her like the man of the whetstones”, is an idiom for paying someone no heed.</note>\n          </div>"},{"id":"pf-sarasin-7","n":"I.7","start":true,"orig":["Finìd di puartâ fûr dutt il forment, il Signor al va in cusine e su ’l fogolar al choll un stizz. La parone di chase lu chale cu’ la boche viarte par viodi ce che ’l à di fâ; ma co’ lu viod vicinàsi al forment, e’ ûl fermàlu sberlangi, ce che ’l pensass di fâ cun chell stizz, se ’l foss matt di bacilâ cu ’l fûg. Lui al prove cuietàle: che no stass vê paùre, che lu lassass, che lui zà ’l savève ce che ’l veve di fâ; e po se la ingianass, che ’l saress in-te ’s sos mans e podaress chastiàlu. E tant al fas, che j’ riess di butâ ’l stizz in-te ’l forment.","T’un moment al va dutt in flamis.","Alore po jê nissun la ten e scomence a sberlâ, fûr di sè de’ rabie e da ’l spavent, che son sassins, che òlin brusàigi dutt.... Ma ’l Signor gi mostre ’l grùm de ’l forment.","— Chalàit, mo — j dìs — se no vin fatt ben il nestri lavor!"],"it":["Finito di portar fuori tutto il frumento, il Signore va in cucina e dal focolare prende un tizzone. La padrona di casa lo guarda a bocca aperta per vedere che cosa ha da fare; ma quando lo vede avvicinarsi al frumento vuole fermarlo, gridandogli che cosa pensasse di fare con quel tizzone, se fosse matto a giocare col fuoco. Lui prova a calmarla: che non avesse paura, che lo lasciasse fare, che lui sapeva già quel che doveva fare; e che se la ingannava sarebbe stato nelle sue mani e lei avrebbe potuto castigarlo. E tanto fa, che riesce a buttare il tizzone nel frumento.","In un momento va tutto in fiamme.","Allora nessuno la tiene più, e comincia a gridare, fuori di sé dalla rabbia e dallo spavento, che sono assassini, che vogliono bruciarle tutto... Ma il Signore le mostra il mucchio del frumento.","«Guardate, dunque,» le dice, «se non abbiamo fatto bene il nostro lavoro!»"],"en":["When all the wheat had been carried out, the Lord goes into the kitchen and takes a burning brand from the hearth. The mistress of the house watches him open-mouthed to see what he means to do; but when she sees him go near the wheat she tries to stop him, shouting at him what he thought he was doing with that brand, whether he was mad enough to play with fire. He tries to calm her: she was not to be afraid, she was to let him be, he knew what he had to do; and if he deceived her, he would be in her hands and she could punish him. And he keeps at it until he manages to throw the brand into the wheat.","In a moment it all goes up in flames.","Then there is no holding her, and she starts to scream, beside herself with rage and fright, that they are murderers, that they want to burn her out of everything… But the Lord shows her the heap of wheat.","“Look now,” he tells her, “and see whether we haven’t done our work well!”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-sarasin-7\" n=\"I.7\" rend=\"p-start\">\n            <p>Finìd di puartâ fûr dutt il forment, il Signor al va in cusine e su ’l fogolar al choll un stizz. La parone di chase lu chale cu’ la boche viarte par viodi ce che ’l à di fâ; ma co’ lu viod vicinàsi al forment, e’ ûl fermàlu sberlangi, ce che ’l pensass di fâ cun chell stizz, se ’l foss matt di bacilâ cu ’l fûg. Lui al prove cuietàle: che no stass vê paùre, che lu lassass, che lui zà ’l savève ce che ’l veve di fâ; e po se la ingianass, che ’l saress in-te ’s sos mans e podaress chastiàlu. E tant al fas, che j’ riess di butâ ’l stizz in-te ’l forment.</p>\n            <p>T’un moment al va dutt in flamis.</p>\n            <p>Alore po jê nissun la ten e scomence a sberlâ, fûr di sè de’ rabie e da ’l spavent, che son sassins, che òlin brusàigi dutt.... Ma ’l Signor gi mostre ’l grùm de ’l forment.</p>\n            <p>— Chalàit, mo — j dìs — se no vin fatt ben il nestri lavor!</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-7\">\n            <p>Finito di portar fuori tutto il frumento, il Signore va in cucina e dal focolare prende un tizzone. La padrona di casa lo guarda a bocca aperta per vedere che cosa ha da fare; ma quando lo vede avvicinarsi al frumento vuole fermarlo, gridandogli che cosa pensasse di fare con quel tizzone, se fosse matto a giocare col fuoco. Lui prova a calmarla: che non avesse paura, che lo lasciasse fare, che lui sapeva già quel che doveva fare; e che se la ingannava sarebbe stato nelle sue mani e lei avrebbe potuto castigarlo. E tanto fa, che riesce a buttare il tizzone nel frumento.</p>\n            <p>In un momento va tutto in fiamme.</p>\n            <p>Allora nessuno la tiene più, e comincia a gridare, fuori di sé dalla rabbia e dallo spavento, che sono assassini, che vogliono bruciarle tutto... Ma il Signore le mostra il mucchio del frumento.</p>\n            <p>«Guardate, dunque,» le dice, «se non abbiamo fatto bene il nostro lavoro!»</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-7\">\n            <p>When all the wheat had been carried out, the Lord goes into the kitchen and takes a burning brand from the hearth. The mistress of the house watches him open-mouthed to see what he means to do; but when she sees him go near the wheat she tries to stop him, shouting at him what he thought he was doing with that brand, whether he was mad enough to play with fire. He tries to calm her: she was not to be afraid, she was to let him be, he knew what he had to do; and if he deceived her, he would be in her hands and she could punish him. And he keeps at it until he manages to throw the brand into the wheat.</p>\n            <p>In a moment it all goes up in flames.</p>\n            <p>Then there is no holding her, and she starts to scream, beside herself with rage and fright, that they are murderers, that they want to burn her out of everything… But the Lord shows her the heap of wheat.</p>\n            <p>“Look now,” he tells her, “and see whether we haven’t done our work well!”</p>\n          </div>"},{"id":"pf-sarasin-8","n":"I.8","start":true,"orig":["E infats il forment e’ no ’l si bruse fross; ma la bule e’ svole dute di une bande, il forment nett di che’ altre e ’l stran al reste dutt biell daùr. Alore jê reste cun tant di nas, svergonzàde e spaurìde, di vê tratàd in che’ maniere un om, che l’ere bon di fâ chei miràcui e j’ domande tremand perdòn.","— Va ben, va ben, — j’ rispuind il Signor — nome imparàit par un’altre volte a no jessi cussì svelte di maltratâ un om, che no cognossês, se anche lui al lavore in-t’une maniere che vo no podès capî.","Dopo al si chape su e ’l va vie cu i sièi doi compagns."],"it":["E infatti il frumento non brucia affatto; ma la pula vola tutta da una parte, il frumento pulito dall’altra e la paglia resta tutta bella dietro. Allora lei resta con tanto di naso, svergognata e spaventata di aver trattato in quel modo un uomo capace di fare simili miracoli, e tremando gli chiede perdono.","«Va bene, va bene,» le risponde il Signore, «soltanto imparate per un’altra volta a non essere così svelta a maltrattare un uomo che non conoscete, anche se lavora in una maniera che voi non potete capire.»","Poi si alza e se ne va con i suoi due compagni."],"en":["And indeed the wheat does not burn at all; but the chaff flies off to one side, the clean wheat to the other, and the straw is left all neat behind. Then she is left looking foolish, ashamed and frightened at having treated in that way a man who could work such miracles, and trembling she asks his pardon.","“All right, all right,” the Lord answers her, “only learn for another time not to be so quick to ill-treat a man you don’t know, even if he works in a way you cannot understand.”","Then he gets up and goes off with his two companions."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-sarasin-8\" n=\"I.8\" rend=\"p-start\">\n            <p>E infats il forment e’ no ’l si bruse fross; ma la bule e’ svole dute di une bande, il forment nett di che’ altre e ’l stran al reste dutt biell daùr. Alore jê reste cun tant di nas, svergonzàde e spaurìde, di vê tratàd in che’ maniere un om, che l’ere bon di fâ chei miràcui e j’ domande tremand perdòn.</p>\n            <p>— Va ben, va ben, — j’ rispuind il Signor — nome imparàit par un’altre volte a no jessi cussì svelte di maltratâ un om, che no cognossês, se anche lui al lavore in-t’une maniere che vo no podès capî.</p>\n            <p>Dopo al si chape su e ’l va vie cu i sièi doi compagns.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-8\">\n            <p>E infatti il frumento non brucia affatto; ma la pula vola tutta da una parte, il frumento pulito dall’altra e la paglia resta tutta bella dietro. Allora lei resta con tanto di naso, svergognata e spaventata di aver trattato in quel modo un uomo capace di fare simili miracoli, e tremando gli chiede perdono.</p>\n            <p>«Va bene, va bene,» le risponde il Signore, «soltanto imparate per un’altra volta a non essere così svelta a maltrattare un uomo che non conoscete, anche se lavora in una maniera che voi non potete capire.»</p>\n            <p>Poi si alza e se ne va con i suoi due compagni.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-8\">\n            <p>And indeed the wheat does not burn at all; but the chaff flies off to one side, the clean wheat to the other, and the straw is left all neat behind. Then she is left looking foolish, ashamed and frightened at having treated in that way a man who could work such miracles, and trembling she asks his pardon.</p>\n            <p>“All right, all right,” the Lord answers her, “only learn for another time not to be so quick to ill-treat a man you don’t know, even if he works in a way you cannot understand.”</p>\n            <p>Then he gets up and goes off with his two companions.</p>\n          </div>"},{"id":"pf-sarasin-9","n":"I.9","start":true,"orig":["Un vicin al veve viodùd la maniere smaravèose, che ’l Signor al veve batùd il forment; e svelt lui al côr a chase, al puarte fûr plen di furie dutt il forment in-t’un grum e senze pensâ plui di tant i dâ fûg. Ma lui no l’ere il Signor; il forment al si brusave propri par da bòn. A vedê piàrdisi cussì miseramenti li sos speranzis, chel pùar contadìn al si metè a còri daùr di chei tre oms misteriòs, e chatàds, ur contà la part stupide che ’l veve fatt e ju preà che pa’ l’amor di Dio lu judàssin."],"it":["Un vicino aveva visto la maniera meravigliosa in cui il Signore aveva battuto il frumento; e svelto corre a casa, porta fuori pieno di furia tutto il suo frumento in un mucchio e senza pensarci più di tanto gli dà fuoco. Ma lui non era il Signore: il frumento bruciava proprio per davvero. A vedere perdersi così miseramente le sue speranze, quel povero contadino si mise a correre dietro a quei tre uomini misteriosi e, trovatili, raccontò loro la sciocchezza che aveva fatto e li pregò che per l’amor di Dio lo aiutassero."],"en":["A neighbour had seen the wonderful way in which the Lord had threshed the wheat; and off he runs home in a hurry, carries all his wheat out in a heap in a frenzy, and without a second thought sets fire to it. But he was not the Lord: his wheat burnt for real. Seeing his hopes lost so miserably, the poor farmer ran after those three mysterious men and, when he found them, told them the foolish thing he had done and begged them for the love of God to help him."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-sarasin-9\" n=\"I.9\" rend=\"p-start\">\n            <p>Un vicin al veve viodùd la maniere smaravèose, che ’l Signor al veve batùd il forment; e svelt lui al côr a chase, al puarte fûr plen di furie dutt il forment in-t’un grum e senze pensâ plui di tant i dâ fûg. Ma lui no l’ere il Signor; il forment al si brusave propri par da bòn. A vedê piàrdisi cussì miseramenti li sos speranzis, chel pùar contadìn al si metè a còri daùr di chei tre oms misteriòs, e chatàds, ur contà la part stupide che ’l veve fatt e ju preà che pa’ l’amor di Dio lu judàssin.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-9\">\n            <p>Un vicino aveva visto la maniera meravigliosa in cui il Signore aveva battuto il frumento; e svelto corre a casa, porta fuori pieno di furia tutto il suo frumento in un mucchio e senza pensarci più di tanto gli dà fuoco. Ma lui non era il Signore: il frumento bruciava proprio per davvero. A vedere perdersi così miseramente le sue speranze, quel povero contadino si mise a correre dietro a quei tre uomini misteriosi e, trovatili, raccontò loro la sciocchezza che aveva fatto e li pregò che per l’amor di Dio lo aiutassero.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-9\">\n            <p>A neighbour had seen the wonderful way in which the Lord had threshed the wheat; and off he runs home in a hurry, carries all his wheat out in a heap in a frenzy, and without a second thought sets fire to it. But he was not the Lord: his wheat burnt for real. Seeing his hopes lost so miserably, the poor farmer ran after those three mysterious men and, when he found them, told them the foolish thing he had done and begged them for the love of God to help him.</p>\n          </div>"},{"id":"pf-sarasin-10","n":"I.10","start":true,"orig":["— Va là, — j’ disè il Signor a San Pieri, che ’l veve za sbassàd il nas — e fas deventâ il forment brusàd in sarasìn. E vo, fradi miò, un’altre volte sèit plui furbo, e no olê come une scimie fâ daùr di ches robis, che se anche lis fas un altri, e’ passin lis nestris fuarzis: no dutt ce che ’l fas un, l’è bon di fâ un altri.","San Pieri al lè cun chell om, e da ’l forment, che l’ere làd za miezz in charbon e miezz in cinise, par virtùd de ’l Signor al fasè vignî fûr tant sarasìn.","Cussì al vè orìgin il sarasìn. I oms alore àn scomenzàd a cognòscilu e dopo di che volte àn continuàd a coltivàlu fin cumò."],"it":["«Va’ là,» disse il Signore a San Pietro, che aveva già abbassato il naso, «e fa’ diventare grano saraceno il frumento bruciato. E voi, fratello mio, un’altra volta siate più furbo, e non vogliate fare come una scimmia dietro a cose che, anche se le fa un altro, passano le nostre forze: non tutto quel che fa uno è capace di farlo un altro.»","San Pietro andò con quell’uomo, e dal frumento, che era già andato mezzo in carbone e mezzo in cenere, per virtù del Signore fece venir fuori tanto grano saraceno.","Così ebbe origine il grano saraceno. Gli uomini allora cominciarono a conoscerlo, e da quella volta hanno continuato a coltivarlo fino ad oggi."],"en":["“Go along,” the Lord said to St Peter, who had already hung his head, “and turn the burnt wheat into buckwheat. And you, my brother, be wiser another time, and don’t go aping, like a monkey, things that are beyond our strength even when another man does them: not everything one man does, another can do.”","St Peter went with that man, and out of the wheat, which had already gone half to charcoal and half to ash, by the Lord’s power he brought forth a great deal of buckwheat.","That is how buckwheat came to be. Then people began to know it, and from that time they have gone on growing it to this day."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-sarasin-10\" n=\"I.10\" rend=\"p-start\">\n            <p>— Va là, — j’ disè il Signor a San Pieri, che ’l veve za sbassàd il nas — e fas deventâ il forment brusàd in sarasìn. E vo, fradi miò, un’altre volte sèit plui furbo, e no olê come une scimie fâ daùr di ches robis, che se anche lis fas un altri, e’ passin lis nestris fuarzis: no dutt ce che ’l fas un, l’è bon di fâ un altri.</p>\n            <p>San Pieri al lè cun chell om, e da ’l forment, che l’ere làd za miezz in charbon e miezz in cinise, par virtùd de ’l Signor al fasè vignî fûr tant sarasìn.</p>\n            <p>Cussì al vè orìgin il sarasìn. I oms alore àn scomenzàd a cognòscilu e dopo di che volte àn continuàd a coltivàlu fin cumò.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-10\">\n            <p>«Va’ là,» disse il Signore a San Pietro, che aveva già abbassato il naso, «e fa’ diventare grano saraceno il frumento bruciato. E voi, fratello mio, un’altra volta siate più furbo, e non vogliate fare come una scimmia dietro a cose che, anche se le fa un altro, passano le nostre forze: non tutto quel che fa uno è capace di farlo un altro.»</p>\n            <p>San Pietro andò con quell’uomo, e dal frumento, che era già andato mezzo in carbone e mezzo in cenere, per virtù del Signore fece venir fuori tanto grano saraceno.</p>\n            <p>Così ebbe origine il grano saraceno. Gli uomini allora cominciarono a conoscerlo, e da quella volta hanno continuato a coltivarlo fino ad oggi.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-sarasin-10\">\n            <p>“Go along,” the Lord said to St Peter, who had already hung his head, “and turn the burnt wheat into buckwheat. And you, my brother, be wiser another time, and don’t go aping, like a monkey, things that are beyond our strength even when another man does them: not everything one man does, another can do.”</p>\n            <p>St Peter went with that man, and out of the wheat, which had already gone half to charcoal and half to ash, by the Lord’s power he brought forth a great deal of buckwheat.</p>\n            <p>That is how buckwheat came to be. Then people began to know it, and from that time they have gone on growing it to this day.</p>\n          </div>"}],"gap":null,"atu":{"code":"752A","label":"Christ and Peter in the Barn"},"itResp":"ed2026","gulpease":60.4,"words":{"orig":1194,"it":1072,"en":1187}},{"id":"pf-chavazz","kind":"tale","n":"II","heads":{"orig":"Un’altre leggende sul làd di Chavazz","it":"Un’altra leggenda sul lago di Cavazzo","en":"Another legend of the lake of Cavazzo"},"refs":["cavazzo"],"record":["Pagine friulane, a. III (1890), n. 4, p. 65, Internet Archive; ATU Hospitality Rewarded (assigned 2026). unsigned."],"passages":[{"id":"pf-chavazz-1","n":"II.1","start":true,"orig":["Une volte che il Signor e San Pieri a fòrin chenci vie pal Friul, vignind jù da la Chargne, dopo di jessi stàds a Tulmiezz, passàrin par Chavazz. Anchemò no l’ère il làd, e lor a’ chaminàvin in miezz chês cretàis in-t’une zornàde dal mês di Lui, ch’al fasève un gran schafojazz.","Chamìne e chamìne, traviàrsin par un païs da-bass de montagne di San Simeon, bislung, cun chasis neris e sporcis e la int salvadie. I ùmin a vévin tante di barbe."],"it":["Una volta che il Signore e San Pietro erano in giro per il Friuli, scendendo dalla Carnia dopo essere stati a Tolmezzo, passarono per Cavazzo. Il lago non c’era ancora, e loro camminavano in mezzo a quelle pietraie in una giornata del mese di luglio, con un caldo soffocante.","Cammina e cammina, attraversarono un paese ai piedi del monte San Simeone, lungo e stretto, con case nere e sporche e la gente selvatica. Gli uomini avevano tanto di barba."],"en":["Once, when the Lord and St Peter were travelling about Friuli, coming down from Carnia after being at Tolmezzo, they passed through Cavazzo. The lake was not there yet, and they were walking among those stony wastes on a July day of stifling heat.","On and on they walked, and crossed a village at the foot of Mount San Simeone, long and narrow, with black, dirty houses and wild people. The men had beards down to here."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-chavazz-1\" n=\"II.1\" rend=\"p-start\">\n            <p>Une volte che il Signor e San Pieri a fòrin chenci vie pal Friul, vignind jù da la Chargne, dopo di jessi stàds a Tulmiezz, passàrin par Chavazz. Anchemò no l’ère il làd, e lor a’ chaminàvin in miezz chês cretàis in-t’une zornàde dal mês di Lui, ch’al fasève un gran schafojazz.</p>\n            <p>Chamìne e chamìne, traviàrsin par un païs da-bass de montagne di San Simeon, bislung, cun chasis neris e sporcis e la int salvadie. I ùmin a vévin tante di barbe.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-chavazz-1\">\n            <p>Una volta che il Signore e San Pietro erano in giro per il Friuli, scendendo dalla Carnia dopo essere stati a Tolmezzo, passarono per Cavazzo. Il lago non c’era ancora, e loro camminavano in mezzo a quelle pietraie in una giornata del mese di luglio, con un caldo soffocante.</p>\n            <p>Cammina e cammina, attraversarono un paese ai piedi del monte San Simeone, lungo e stretto, con case nere e sporche e la gente selvatica. Gli uomini avevano tanto di barba.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-chavazz-1\">\n            <p>Once, when the Lord and St Peter were travelling about Friuli, coming down from Carnia after being at Tolmezzo, they passed through Cavazzo. The lake was not there yet, and they were walking among those stony wastes on a July day of stifling heat.</p>\n            <p>On and on they walked, and crossed a village at the foot of Mount San Simeone, long and narrow, with black, dirty houses and wild people. The men had beards down to here.</p>\n          </div>"},{"id":"pf-chavazz-2","n":"II.2","start":true,"orig":["— O hai sèd, vadè Signor — disè San Pieri. — Lassàit ch’ ’o jentri ta cheste chase a domandâ un flàt di aghe.","Al va, e pôc dopo al torne fûr brunduland e invelegnàd.","— Ce astu? — i domande el Signor.","— E han viùd cûr di nèami un flàd di aghe!","— Ben, ben: va là prove ta ches altris chasis.","San Pieri al lè, une par une: ma da-par-dutt a no i volèrin dâ nuje, cun-t’une scuse o cun che altre; e la plui part i rispuindévin che lor a vevin l’aghe masse lontàne di làle a choli, par strassàle cun chei che passavin."],"it":["«Ho sete, vedete, Signore,» disse San Pietro. «Lasciate che entri in questa casa a chiedere un sorso d’acqua.»","Va, e poco dopo torna fuori brontolando e inviperito.","«Che hai?» gli domanda il Signore.","«Hanno avuto il cuore di negarmi un sorso d’acqua!»","«Bene, bene: va’, prova in quelle altre case.»","San Pietro andò, una per una: ma dappertutto non vollero dargli niente, con una scusa o con l’altra; e i più rispondevano che avevano l’acqua troppo lontana da andare a prendere, per sprecarla con chi passava."],"en":["“I’m thirsty, you see, Lord,” said St Peter. “Let me go into this house and ask for a drop of water.”","He goes, and soon after comes out again grumbling and seething.","“What’s the matter?” the Lord asks him.","“They had the heart to refuse me a drop of water!”","“Well, well: go and try those other houses.”","St Peter went, one after another: but everywhere they would give him nothing, with one excuse or another; and most of them answered that their water was too far away to fetch, to waste it on passers-by."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-chavazz-2\" n=\"II.2\" rend=\"p-start\">\n            <p>— O hai sèd, vadè Signor — disè San Pieri. — Lassàit ch’ ’o jentri ta cheste chase a domandâ un flàt di aghe.</p>\n            <p>Al va, e pôc dopo al torne fûr brunduland e invelegnàd.</p>\n            <p>— Ce astu? — i domande el Signor.</p>\n            <p>— E han viùd cûr di nèami un flàd di aghe!</p>\n            <p>— Ben, ben: va là prove ta ches altris chasis.</p>\n            <p>San Pieri al lè, une par une: ma da-par-dutt a no i volèrin dâ nuje, cun-t’une scuse o cun che altre; e la plui part i rispuindévin che lor a vevin l’aghe masse lontàne di làle a choli, par strassàle cun chei che passavin.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-chavazz-2\">\n            <p>«Ho sete, vedete, Signore,» disse San Pietro. «Lasciate che entri in questa casa a chiedere un sorso d’acqua.»</p>\n            <p>Va, e poco dopo torna fuori brontolando e inviperito.</p>\n            <p>«Che hai?» gli domanda il Signore.</p>\n            <p>«Hanno avuto il cuore di negarmi un sorso d’acqua!»</p>\n            <p>«Bene, bene: va’, prova in quelle altre case.»</p>\n            <p>San Pietro andò, una per una: ma dappertutto non vollero dargli niente, con una scusa o con l’altra; e i più rispondevano che avevano l’acqua troppo lontana da andare a prendere, per sprecarla con chi passava.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-chavazz-2\">\n            <p>“I’m thirsty, you see, Lord,” said St Peter. “Let me go into this house and ask for a drop of water.”</p>\n            <p>He goes, and soon after comes out again grumbling and seething.</p>\n            <p>“What’s the matter?” the Lord asks him.</p>\n            <p>“They had the heart to refuse me a drop of water!”</p>\n            <p>“Well, well: go and try those other houses.”</p>\n            <p>St Peter went, one after another: but everywhere they would give him nothing, with one excuse or another; and most of them answered that their water was too far away to fetch, to waste it on passers-by.</p>\n          </div>"},{"id":"pf-chavazz-3","n":"II.3","start":false,"orig":["Restàve nome une chasùte, in fonz de vile. Al batt, San Pieri, anche ta cheste. Ven fûr une pùare vechùte, striscinand lis zavatis.","— Ce olèso, galantom?","— Dàimi di bevi.","— Vulintiròn, po. Jentrait, jentrait.","Ju fasè entrâ duch i doi, e ur dè tante aghe fresche che volèrin."],"it":["Restava soltanto una casetta, in fondo al paese. Bussa, San Pietro, anche a questa. Esce una povera vecchietta, strascicando le ciabatte.","«Che volete, galantuomo?»","«Datemi da bere.»","«Volentieri, via. Entrate, entrate.»","Li fece entrare tutti e due, e diede loro tutta l’acqua fresca che vollero."],"en":["There remained only one little house, at the far end of the village. St Peter knocks at this one too. Out comes a poor little old woman, shuffling in her slippers.","“What would you like, good sir?”","“Give me something to drink.”","“Gladly, of course. Come in, come in.”","She let them both in and gave them all the fresh water they wanted."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-chavazz-3\" n=\"II.3\">\n            <p>Restàve nome une chasùte, in fonz de vile. Al batt, San Pieri, anche ta cheste. Ven fûr une pùare vechùte, striscinand lis zavatis.</p>\n            <p>— Ce olèso, galantom?</p>\n            <p>— Dàimi di bevi.</p>\n            <p>— Vulintiròn, po. Jentrait, jentrait.</p>\n            <p>Ju fasè entrâ duch i doi, e ur dè tante aghe fresche che volèrin.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-chavazz-3\">\n            <p>Restava soltanto una casetta, in fondo al paese. Bussa, San Pietro, anche a questa. Esce una povera vecchietta, strascicando le ciabatte.</p>\n            <p>«Che volete, galantuomo?»</p>\n            <p>«Datemi da bere.»</p>\n            <p>«Volentieri, via. Entrate, entrate.»</p>\n            <p>Li fece entrare tutti e due, e diede loro tutta l’acqua fresca che vollero.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-chavazz-3\">\n            <p>There remained only one little house, at the far end of the village. St Peter knocks at this one too. Out comes a poor little old woman, shuffling in her slippers.</p>\n            <p>“What would you like, good sir?”</p>\n            <p>“Give me something to drink.”</p>\n            <p>“Gladly, of course. Come in, come in.”</p>\n            <p>She let them both in and gave them all the fresh water they wanted.</p>\n          </div>"},{"id":"pf-chavazz-4","n":"II.4","start":true,"orig":["Tornàd ch’al fo il Signor in Cîl, San Pieri lu visà di ce ch’ur jere capitàd in chell païs.","— Brào — i disè il Signor. — Tu has fatt ben a visàmi. Cumò mo lafè olin dàigi aghe avonde, a chei tangàrs.","Al mandà sùbit i siei àgnui par che portassin di gnott la chasùte di che pùare veche su pe’ mont di San Simeon; e cuand-ch’al vedè la chase là sù in-somp, al chapà un gran copp di aghe e lu struchà parsore di chell païs."],"it":["Quando il Signore fu tornato in Cielo, San Pietro gli ricordò ciò che era capitato loro in quel paese.","«Bravo,» gli disse il Signore. «Hai fatto bene a ricordarmelo. Adesso, in fede mia, vogliamo dargliene abbastanza, di acqua, a quei tangheri.»","Mandò subito i suoi angeli a portare di notte la casetta di quella povera vecchia su per il monte San Simeone; e quando vide la casa lassù in cima, prese un gran mestolo d’acqua e lo rovesciò sopra quel paese."],"en":["When the Lord was back in Heaven, St Peter reminded him of what had happened to them in that village.","“Well done,” the Lord told him. “You did well to remind me. Now, upon my word, we’ll give those louts water enough.”","At once he sent his angels to carry the little house of that poor old woman up Mount San Simeone by night; and when he saw the house up there at the top, he took a great dipper of water and emptied it over that village."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-chavazz-4\" n=\"II.4\" rend=\"p-start\">\n            <p>Tornàd ch’al fo il Signor in Cîl, San Pieri lu visà di ce ch’ur jere capitàd in chell païs.</p>\n            <p>— Brào — i disè il Signor. — Tu has fatt ben a visàmi. Cumò mo lafè olin dàigi aghe avonde, a chei tangàrs.</p>\n            <p>Al mandà sùbit i siei àgnui par che portassin di gnott la chasùte di che pùare veche su pe’ mont di San Simeon; e cuand-ch’al vedè la chase là sù in-somp, al chapà un gran copp di aghe e lu struchà parsore di chell païs.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-chavazz-4\">\n            <p>Quando il Signore fu tornato in Cielo, San Pietro gli ricordò ciò che era capitato loro in quel paese.</p>\n            <p>«Bravo,» gli disse il Signore. «Hai fatto bene a ricordarmelo. Adesso, in fede mia, vogliamo dargliene abbastanza, di acqua, a quei tangheri.»</p>\n            <p>Mandò subito i suoi angeli a portare di notte la casetta di quella povera vecchia su per il monte San Simeone; e quando vide la casa lassù in cima, prese un gran mestolo d’acqua e lo rovesciò sopra quel paese.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-chavazz-4\">\n            <p>When the Lord was back in Heaven, St Peter reminded him of what had happened to them in that village.</p>\n            <p>“Well done,” the Lord told him. “You did well to remind me. Now, upon my word, we’ll give those louts water enough.”</p>\n            <p>At once he sent his angels to carry the little house of that poor old woman up Mount San Simeone by night; and when he saw the house up there at the top, he took a great dipper of water and emptied it over that village.</p>\n          </div>"},{"id":"pf-chavazz-5","n":"II.5","start":true,"orig":["Cussì l’è deventàd el làd di Chavazz, e anchemò cualchi volte, se l’aghe e’ jè clare clare, si cìche in-sott in-sott el champanìli di chell païs e lis chasis: ma di omps a no s’in viod nanche un. Par un pôche di aghe, che ur han dite di no al nestri Signor e al so Sant Apuèstul, le han duch finìde cussì malamentri là sott.","Che pùare vechute, invenzit, e ha vivùd anchemò un pôs di agns, in pâs e in caritât su pe’ montagne, dute maravèàde di chatàsi lassù be-sole; e cuand che murì, e plantàrin tal puest de so’ chase une glesiùte che anchimò si la viòd, e dulà che, si conte, la gnott dai muarz a viodin a lâ in procession dutis lis animis puartand une chandelute impiàde su la ponte dal dèd, e cui che no l’è stàd di vîv a visitâ la glesie, al dèvi lâ di muart."],"it":["Così è nato il lago di Cavazzo, e ancora qualche volta, se l’acqua è chiara chiara, si intravedono laggiù in fondo il campanile di quel paese e le case: ma di uomini non se ne vede nemmeno uno. Per un po’ d’acqua, che negarono al nostro Signore e al suo santo Apostolo, l’hanno finita tutti così malamente là sotto.","Quella povera vecchietta, invece, visse ancora qualche anno, in pace e in carità su per la montagna, tutta meravigliata di trovarsi lassù da sola; e quando morì, al posto della sua casa costruirono una chiesetta che si vede ancora, e dove, si racconta, nella notte dei morti si vedono andare in processione tutte le anime, ciascuna con una candelina accesa sulla punta del dito; e chi non è stato a visitare la chiesa da vivo deve andarci da morto."],"en":["That is how the lake of Cavazzo came to be; and still, sometimes, when the water is very clear, you can glimpse far down the bell tower of that village and its houses: but of the people not one is to be seen. For a little water, which they refused our Lord and his holy Apostle, they all came to that bad end down there.","That poor little old woman, on the other hand, lived a few years more, in peace and charity up on the mountain, marvelling to find herself up there all alone; and when she died they built a little church on the spot where her house stood, which can still be seen, and where, so they say, on the night of the dead all the souls are seen going in procession, each with a little lit candle on the tip of a finger; and whoever did not visit the church in life must go there after death."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-chavazz-5\" n=\"II.5\" rend=\"p-start\">\n            <p>Cussì l’è deventàd el làd di Chavazz, e anchemò cualchi volte, se l’aghe e’ jè clare clare, si cìche in-sott in-sott el champanìli di chell païs e lis chasis: ma di omps a no s’in viod nanche un. Par un pôche di aghe, che ur han dite di no al nestri Signor e al so Sant Apuèstul, le han duch finìde cussì malamentri là sott.</p>\n            <p>Che pùare vechute, invenzit, e ha vivùd anchemò un pôs di agns, in pâs e in caritât su pe’ montagne, dute maravèàde di chatàsi lassù be-sole; e cuand che murì, e plantàrin tal puest de so’ chase une glesiùte che anchimò si la viòd, e dulà che, si conte, la gnott dai muarz a viodin a lâ in procession dutis lis animis puartand une chandelute impiàde su la ponte dal dèd, e cui che no l’è stàd di vîv a visitâ la glesie, al dèvi lâ di muart.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-chavazz-5\">\n            <p>Così è nato il lago di Cavazzo, e ancora qualche volta, se l’acqua è chiara chiara, si intravedono laggiù in fondo il campanile di quel paese e le case: ma di uomini non se ne vede nemmeno uno. Per un po’ d’acqua, che negarono al nostro Signore e al suo santo Apostolo, l’hanno finita tutti così malamente là sotto.</p>\n            <p>Quella povera vecchietta, invece, visse ancora qualche anno, in pace e in carità su per la montagna, tutta meravigliata di trovarsi lassù da sola; e quando morì, al posto della sua casa costruirono una chiesetta che si vede ancora, e dove, si racconta, nella notte dei morti si vedono andare in processione tutte le anime, ciascuna con una candelina accesa sulla punta del dito; e chi non è stato a visitare la chiesa da vivo deve andarci da morto.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-chavazz-5\">\n            <p>That is how the lake of Cavazzo came to be; and still, sometimes, when the water is very clear, you can glimpse far down the bell tower of that village and its houses: but of the people not one is to be seen. For a little water, which they refused our Lord and his holy Apostle, they all came to that bad end down there.</p>\n            <p>That poor little old woman, on the other hand, lived a few years more, in peace and charity up on the mountain, marvelling to find herself up there all alone; and when she died they built a little church on the spot where her house stood, which can still be seen, and where, so they say, on the night of the dead all the souls are seen going in procession, each with a little lit candle on the tip of a finger; and whoever did not visit the church in life must go there after death.</p>\n          </div>"}],"gap":null,"atu":{"code":"750B","label":"Hospitality Rewarded"},"itResp":"ed2026","gulpease":63.5,"words":{"orig":481,"it":429,"en":484}},{"id":"pf-mari","kind":"tale","n":"III","heads":{"orig":"Invidiôs tanche la mâri di San Pieri","it":"Invidioso come la madre di San Pietro","en":"Envious as St Peter’s mother"},"refs":["ostermann"],"record":["Pagine friulane, a. VI (1893), n. 1, pp. 9–10, in “Fiabe che illustrano proverbi o modi di dire”, Internet Archive; ATU Peter’s Mother Falls from Heaven (assigned 2026). signed “V. O.”."],"passages":[{"id":"pf-mari-1","n":"III.1","start":true,"orig":["Dopo muàrt, San Pieri al lè in paradìs, e il signôr disìngi: Ego dabo tibi claves regni coelorum, lu creà portîr e uardiàn dal cîl, par cui cence il so permès lassù nissùn po’ entrâ.","Cuànd che il Signôr al s’incontrave nel capo dei siei apuestui, lu viodeve simpri avilìt e une dì i domandà:","— Ma Pieri, ce mai astu ch’ i tu sês simpri di male voe? No ti chàtistu forsi ben, ca sù?","E San Pieri i rispuindè:","— Viòdiso, Signôr, jò soi cà a gioldi lis uestris glòriis, e puare mê mâri inveze jè fra lis plui duris penis a fons di cha-dal-diàul; si uèlis viòdimi lègri, acordàimi la grazie ch’a vegni ca sù anche jê."],"it":["Dopo morto, San Pietro andò in paradiso, e il Signore, dicendogli: Ego dabo tibi claves regni coelorum, lo fece portinaio e guardiano del cielo, per cui senza il suo permesso lassù nessuno può entrare.","Quando il Signore s’incontrava con il capo dei suoi apostoli, lo vedeva sempre avvilito, e un giorno gli domandò:","«Ma Pietro, che cos’hai mai che sei sempre di cattivo umore? Non ti trovi forse bene, quassù?»","E San Pietro gli rispose:","«Vedete, Signore, io sono qui a godere le vostre glorie, e la mia povera madre invece è tra le pene più dure in fondo all’inferno; se volete vedermi allegro, concedetemi la grazia che venga quassù anche lei.»"],"en":["After his death St Peter went to paradise, and the Lord, saying to him Ego dabo tibi claves regni coelorum, made him doorkeeper and warden of heaven, so that without his leave nobody may enter up there.","Whenever the Lord met the chief of his apostles, he always found him downcast, and one day he asked him:","“But Peter, whatever is the matter, that you are always in a bad mood? Are you not happy up here?”","And St Peter answered him:","“You see, Lord, I am here enjoying your glories, and my poor mother instead is among the hardest pains at the bottom of hell; if you want to see me happy, grant me the grace that she may come up here too.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-mari-1\" n=\"III.1\" rend=\"p-start\">\n            <p>Dopo muàrt, San Pieri al lè in paradìs, e il signôr disìngi: Ego dabo tibi claves regni coelorum, lu creà portîr e uardiàn dal cîl, par cui cence il so permès lassù nissùn po’ entrâ.</p>\n            <p>Cuànd che il Signôr al s’incontrave nel capo dei siei apuestui, lu viodeve simpri avilìt e une dì i domandà:</p>\n            <p>— Ma Pieri, ce mai astu ch’ i tu sês simpri di male voe? No ti chàtistu forsi ben, ca sù?</p>\n            <p>E San Pieri i rispuindè:</p>\n            <p>— Viòdiso, Signôr, jò soi cà a gioldi lis uestris glòriis, e puare mê mâri inveze jè fra lis plui duris penis a fons di cha-dal-diàul; si uèlis viòdimi lègri, acordàimi la grazie ch’a vegni ca sù anche jê.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mari-1\">\n            <p>Dopo morto, San Pietro andò in paradiso, e il Signore, dicendogli: Ego dabo tibi claves regni coelorum, lo fece portinaio e guardiano del cielo, per cui senza il suo permesso lassù nessuno può entrare.</p>\n            <p>Quando il Signore s’incontrava con il capo dei suoi apostoli, lo vedeva sempre avvilito, e un giorno gli domandò:</p>\n            <p>«Ma Pietro, che cos’hai mai che sei sempre di cattivo umore? Non ti trovi forse bene, quassù?»</p>\n            <p>E San Pietro gli rispose:</p>\n            <p>«Vedete, Signore, io sono qui a godere le vostre glorie, e la mia povera madre invece è tra le pene più dure in fondo all’inferno; se volete vedermi allegro, concedetemi la grazia che venga quassù anche lei.»</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mari-1\">\n            <p>After his death St Peter went to paradise, and the Lord, saying to him Ego dabo tibi claves regni coelorum, made him doorkeeper and warden of heaven, so that without his leave nobody may enter up there.</p>\n            <p>Whenever the Lord met the chief of his apostles, he always found him downcast, and one day he asked him:</p>\n            <p>“But Peter, whatever is the matter, that you are always in a bad mood? Are you not happy up here?”</p>\n            <p>And St Peter answered him:</p>\n            <p>“You see, Lord, I am here enjoying your glories, and my poor mother instead is among the hardest pains at the bottom of hell; if you want to see me happy, grant me the grace that she may come up here too.”</p>\n          </div>"},{"id":"pf-mari-2","n":"III.2","start":true,"orig":["— Ben — disè il Signor — va sù sul chast dal paradìs, e s’ i tu chatis une sole buine aziòn fate da tô mâri, vàliti di chê par liberâle e tirâle sù.","San Pieri beât e contènt corè sul chast a cirî, e al chatà nome une pizzule rieste di ai che sô mâri une volte veve dade di caritât. Cun chê al lè jù subit tal infièr e je slungià a sô mâri par che si piàs intôr e vegnìs sù in paradìs cun lui. So mâri si tacà a chel debul sostegno, e San Pieri la tirave sù; ma lis altris ànimis ch’a erin intôr di jè comenzàrin a tacâgisi intôr, speràndi di podê saltâ fûr das penis anche lôr. La mâri di San Pieri no oleve che nissùn altri si salvàs cun jè; a dè quindi une gran sgurlade par fâ colâ lis ànimis, ma la pizzule rieste di ai si rompè, e jè cun dutis lis altris ànimis ch’a veve intôr a plombâ a fons di cha-dal-diàul, d’in dulà che so fì nol podè plui tirâle sù."],"it":["«Bene,» disse il Signore, «va’ su nell’archivio del paradiso, e se trovi una sola buona azione fatta da tua madre, servitene per liberarla e tirarla su.»","San Pietro, beato e contento, corse nell’archivio a cercare, e trovò soltanto una piccola treccia d’aglio che sua madre una volta aveva dato in carità. Con quella scese subito all’inferno e la porse a sua madre perché vi si aggrappasse e venisse su in paradiso con lui. Sua madre si attaccò a quel debole sostegno, e San Pietro la tirava su; ma le altre anime che le stavano intorno cominciarono ad attaccarsi a lei, sperando di poter uscire anche loro dalle pene. La madre di San Pietro non voleva che nessun altro si salvasse con lei; diede quindi una gran scrollata per far cadere le anime, ma la piccola treccia d’aglio si ruppe, e lei con tutte le altre anime che aveva intorno piombò in fondo all’inferno, da dove suo figlio non poté più tirarla su."],"en":["“Very well,” said the Lord, “go up to the storehouse of paradise, and if you find a single good deed done by your mother, use it to free her and pull her up.”","St Peter, happy and content, ran to the storehouse to look, and found only a small braid of garlic that his mother had once given in charity. With it he went straight down to hell and held it out to his mother, so that she could catch hold of it and come up to paradise with him. His mother clung to that feeble support, and St Peter was pulling her up; but the other souls around her began to cling to her, hoping they too could get out of their pains. St Peter’s mother did not want anyone else saved with her; so she gave a great shake to make the souls fall, but the little braid of garlic broke, and she, with all the other souls around her, plunged to the bottom of hell, from where her son could never pull her up again."],"note":"In the Sicilian tale (Pitrè, n. CXXVI) the one good deed is a leek leaf; here it is a braid of garlic.","xml":"<div type=\"passage\" xml:id=\"pf-mari-2\" n=\"III.2\" rend=\"p-start\">\n            <p>— Ben — disè il Signor — va sù sul chast dal paradìs, e s’ i tu chatis une sole buine aziòn fate da tô mâri, vàliti di chê par liberâle e tirâle sù.</p>\n            <p>San Pieri beât e contènt corè sul chast a cirî, e al chatà nome une pizzule rieste di ai che sô mâri une volte veve dade di caritât. Cun chê al lè jù subit tal infièr e je slungià a sô mâri par che si piàs intôr e vegnìs sù in paradìs cun lui. So mâri si tacà a chel debul sostegno, e San Pieri la tirave sù; ma lis altris ànimis ch’a erin intôr di jè comenzàrin a tacâgisi intôr, speràndi di podê saltâ fûr das penis anche lôr. La mâri di San Pieri no oleve che nissùn altri si salvàs cun jè; a dè quindi une gran sgurlade par fâ colâ lis ànimis, ma la pizzule rieste di ai si rompè, e jè cun dutis lis altris ànimis ch’a veve intôr a plombâ a fons di cha-dal-diàul, d’in dulà che so fì nol podè plui tirâle sù.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mari-2\">\n            <p>«Bene,» disse il Signore, «va’ su nell’archivio del paradiso, e se trovi una sola buona azione fatta da tua madre, servitene per liberarla e tirarla su.»</p>\n            <p>San Pietro, beato e contento, corse nell’archivio a cercare, e trovò soltanto una piccola treccia d’aglio che sua madre una volta aveva dato in carità. Con quella scese subito all’inferno e la porse a sua madre perché vi si aggrappasse e venisse su in paradiso con lui. Sua madre si attaccò a quel debole sostegno, e San Pietro la tirava su; ma le altre anime che le stavano intorno cominciarono ad attaccarsi a lei, sperando di poter uscire anche loro dalle pene. La madre di San Pietro non voleva che nessun altro si salvasse con lei; diede quindi una gran scrollata per far cadere le anime, ma la piccola treccia d’aglio si ruppe, e lei con tutte le altre anime che aveva intorno piombò in fondo all’inferno, da dove suo figlio non poté più tirarla su.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mari-2\">\n            <p>“Very well,” said the Lord, “go up to the storehouse of paradise, and if you find a single good deed done by your mother, use it to free her and pull her up.”</p>\n            <p>St Peter, happy and content, ran to the storehouse to look, and found only a small braid of garlic that his mother had once given in charity. With it he went straight down to hell and held it out to his mother, so that she could catch hold of it and come up to paradise with him. His mother clung to that feeble support, and St Peter was pulling her up; but the other souls around her began to cling to her, hoping they too could get out of their pains. St Peter’s mother did not want anyone else saved with her; so she gave a great shake to make the souls fall, but the little braid of garlic broke, and she, with all the other souls around her, plunged to the bottom of hell, from where her son could never pull her up again.</p>\n            <note type=\"translation\">In the Sicilian tale (Pitrè, n. CXXVI) the one good deed is a leek leaf; here it is a braid of garlic.</note>\n          </div>"},{"id":"pf-mari-3","n":"III.3","start":true,"orig":["E cuànd che un l’ha invidie dal ben dei altris, cumò i disin: Invidiôs come la mâri di San Pieri.","Come agiunte a la flabe cualchedùn al dìs che l’Apuestul al preà tant il Signôr che chèl i prometè di liberâ das penis la mâri almancul une volte all’àn, tal dì da sô sagre, al 29 di Jugn, ma i disè:","— Tu viodarâs, Pieri, se tô mâri no farà malàns in compèns!","E di fât cuànd che la danade a jès dal infièr o cuànd ch’a torne dentri, cuàsi ogn’àn a fâs sintî il teremòt, parcè che ûl che anche i altris a vêbin di sofrî."],"it":["E quando uno ha invidia del bene degli altri, adesso gli dicono: Invidioso come la madre di San Pietro.","Come aggiunta alla fiaba, qualcuno dice che l’Apostolo pregò tanto il Signore che questi gli promise di liberare dalle pene sua madre almeno una volta all’anno, nel giorno della sua festa, il 29 di giugno; ma gli disse:","«Vedrai, Pietro, se tua madre non combinerà malanni in cambio!»","E difatti, quando la dannata esce dall’inferno o quando vi rientra, quasi ogni anno fa sentire il terremoto, perché vuole che anche gli altri abbiano da soffrire."],"en":["And when someone envies the good of others, people now say: Envious as St Peter’s mother.","As an addition to the tale, some say that the Apostle begged the Lord so hard that he promised to free his mother from her pains at least once a year, on his feast day, the 29th of June; but he told him:","“You’ll see, Peter, whether your mother doesn’t do some mischief in return!”","And indeed, when the damned woman comes out of hell or goes back in, almost every year she sets off an earthquake, because she wants the others to suffer too."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-mari-3\" n=\"III.3\" rend=\"p-start\">\n            <p>E cuànd che un l’ha invidie dal ben dei altris, cumò i disin: Invidiôs come la mâri di San Pieri.</p>\n            <p>Come agiunte a la flabe cualchedùn al dìs che l’Apuestul al preà tant il Signôr che chèl i prometè di liberâ das penis la mâri almancul une volte all’àn, tal dì da sô sagre, al 29 di Jugn, ma i disè:</p>\n            <p>— Tu viodarâs, Pieri, se tô mâri no farà malàns in compèns!</p>\n            <p>E di fât cuànd che la danade a jès dal infièr o cuànd ch’a torne dentri, cuàsi ogn’àn a fâs sintî il teremòt, parcè che ûl che anche i altris a vêbin di sofrî.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mari-3\">\n            <p>E quando uno ha invidia del bene degli altri, adesso gli dicono: Invidioso come la madre di San Pietro.</p>\n            <p>Come aggiunta alla fiaba, qualcuno dice che l’Apostolo pregò tanto il Signore che questi gli promise di liberare dalle pene sua madre almeno una volta all’anno, nel giorno della sua festa, il 29 di giugno; ma gli disse:</p>\n            <p>«Vedrai, Pietro, se tua madre non combinerà malanni in cambio!»</p>\n            <p>E difatti, quando la dannata esce dall’inferno o quando vi rientra, quasi ogni anno fa sentire il terremoto, perché vuole che anche gli altri abbiano da soffrire.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mari-3\">\n            <p>And when someone envies the good of others, people now say: Envious as St Peter’s mother.</p>\n            <p>As an addition to the tale, some say that the Apostle begged the Lord so hard that he promised to free his mother from her pains at least once a year, on his feast day, the 29th of June; but he told him:</p>\n            <p>“You’ll see, Peter, whether your mother doesn’t do some mischief in return!”</p>\n            <p>And indeed, when the damned woman comes out of hell or goes back in, almost every year she sets off an earthquake, because she wants the others to suffer too.</p>\n          </div>"}],"gap":null,"atu":{"code":"804","label":"Peter’s Mother Falls from Heaven"},"itResp":"ed2026","gulpease":53.6,"words":{"orig":410,"it":368,"en":403}},{"id":"pf-mestri","kind":"tale","n":"IV","heads":{"orig":"Il mestri sore duch i mestris","it":"Il maestro sopra tutti i maestri","en":"The master above all masters"},"refs":["gortani","carnia"],"record":["Pagine friulane, a. VII (1894), p. 24, Internet Archive; ATU Christ and the Smith (assigned 2026). “Sintude a contâ a Clavais, ad Avosâs, a Cedarchis, ad Incharoj e a Racolane” (Gortani’s note)."],"passages":[{"id":"pf-mestri-1","n":"IV.1","start":true,"orig":["Al ere une volte un fari brâv del so mistîr, ma cussì plen di pretese, che, a sintîlu lui, al mangiave la fave sul châv a duch i artisch ch’a’ erin sòt la cape dal cîl. Par dâssi ton, al veve scrìt in grand sore la puarte del so’ lavoratori: il mestri sore duch i mestris."],"it":["C’era una volta un fabbro bravo nel suo mestiere, ma così pieno di pretese che, a sentir lui, mangiava la fava in testa a tutti gli artigiani che c’erano sotto la cappa del cielo. Per darsi tono, aveva scritto in grande sopra la porta della sua bottega: il maestro sopra tutti i maestri."],"en":["Once upon a time there was a blacksmith who was good at his trade, but so full of himself that, to hear him talk, he could eat beans off the head of every craftsman under the vault of heaven. To give himself airs, he had written in big letters over the door of his workshop: the master above all masters."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-mestri-1\" n=\"IV.1\" rend=\"p-start\">\n            <p>Al ere une volte un fari brâv del so mistîr, ma cussì plen di pretese, che, a sintîlu lui, al mangiave la fave sul châv a duch i artisch ch’a’ erin sòt la cape dal cîl. Par dâssi ton, al veve scrìt in grand sore la puarte del so’ lavoratori: il mestri sore duch i mestris.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-1\">\n            <p>C’era una volta un fabbro bravo nel suo mestiere, ma così pieno di pretese che, a sentir lui, mangiava la fava in testa a tutti gli artigiani che c’erano sotto la cappa del cielo. Per darsi tono, aveva scritto in grande sopra la porta della sua bottega: il maestro sopra tutti i maestri.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-1\">\n            <p>Once upon a time there was a blacksmith who was good at his trade, but so full of himself that, to hear him talk, he could eat beans off the head of every craftsman under the vault of heaven. To give himself airs, he had written in big letters over the door of his workshop: the master above all masters.</p>\n          </div>"},{"id":"pf-mestri-2","n":"IV.2","start":true,"orig":["Une dì al càpite di che’ bande il Signôr, che in chèl timp al lave atòr pal mond in compagnie di San Pieri, e stànd su la puarte lu salude:","— Bon dì, mestri.","Il fari, ch’al ere daùr a dâ l’ultime man a un fièr di talpe di mùs, no j’ torne nissune rispueste.","— Bon dì mestri — ai repliche il Signôr.","— Se no savês fevelâ, imparait — al rugne il fari cun t’un estro di pofarbìo.","— E parcè mo’?","— Chalàit ce ch’al è scrìt là parsore e lu savarês."],"it":["Un giorno capita da quelle parti il Signore, che a quel tempo andava in giro per il mondo in compagnia di San Pietro, e fermandosi sulla porta lo saluta:","«Buon giorno, maestro.»","Il fabbro, che stava dando l’ultima mano a un ferro da zoccolo d’asino, non gli rende nessuna risposta.","«Buon giorno, maestro,» ripete il Signore.","«Se non sapete parlare, imparate,» brontola il fabbro, stizzito.","«E perché mai?»","«Guardate che cosa è scritto lassù e lo saprete.»"],"en":["One day the Lord happens by that way (in those days he went about the world in the company of St Peter), and standing at the door he greets him:","“Good day, master.”","The smith, who was putting the finishing touches to a donkey’s shoe, gives no answer.","“Good day, master,” the Lord says again.","“If you don’t know how to speak, learn,” the smith growls in a huff.","“And why is that?”","“Look at what’s written up there and you’ll know.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-mestri-2\" n=\"IV.2\" rend=\"p-start\">\n            <p>Une dì al càpite di che’ bande il Signôr, che in chèl timp al lave atòr pal mond in compagnie di San Pieri, e stànd su la puarte lu salude:</p>\n            <p>— Bon dì, mestri.</p>\n            <p>Il fari, ch’al ere daùr a dâ l’ultime man a un fièr di talpe di mùs, no j’ torne nissune rispueste.</p>\n            <p>— Bon dì mestri — ai repliche il Signôr.</p>\n            <p>— Se no savês fevelâ, imparait — al rugne il fari cun t’un estro di pofarbìo.</p>\n            <p>— E parcè mo’?</p>\n            <p>— Chalàit ce ch’al è scrìt là parsore e lu savarês.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-2\">\n            <p>Un giorno capita da quelle parti il Signore, che a quel tempo andava in giro per il mondo in compagnia di San Pietro, e fermandosi sulla porta lo saluta:</p>\n            <p>«Buon giorno, maestro.»</p>\n            <p>Il fabbro, che stava dando l’ultima mano a un ferro da zoccolo d’asino, non gli rende nessuna risposta.</p>\n            <p>«Buon giorno, maestro,» ripete il Signore.</p>\n            <p>«Se non sapete parlare, imparate,» brontola il fabbro, stizzito.</p>\n            <p>«E perché mai?»</p>\n            <p>«Guardate che cosa è scritto lassù e lo saprete.»</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-2\">\n            <p>One day the Lord happens by that way (in those days he went about the world in the company of St Peter), and standing at the door he greets him:</p>\n            <p>“Good day, master.”</p>\n            <p>The smith, who was putting the finishing touches to a donkey’s shoe, gives no answer.</p>\n            <p>“Good day, master,” the Lord says again.</p>\n            <p>“If you don’t know how to speak, learn,” the smith growls in a huff.</p>\n            <p>“And why is that?”</p>\n            <p>“Look at what’s written up there and you’ll know.”</p>\n          </div>"},{"id":"pf-mestri-3","n":"IV.3","start":false,"orig":["Il Signôr al alze il châv, al lèi, e cun dute cerimonie lu torne a saludâ:","— Bon dì, mestri sore duch i mestris.","— Oh cumò si vin capìd! — al rispuìnd il fari. — Ce voleviso?","— Eri vignùd a preàus di lasçâmi lavorâ cualchi minût in ta vuestre farie, che varès voë di dâ une buine soferade a un cert capo vecho e frujàd che hai culì di fûr.","— Po dàimel cà a mi, che se in t’un bati di voli no us el fâs tornâ come un pipìn, uèi disbatiâmi.","— Graziis, — al torne a dî il Signôr, — ma vês di savê ch’al è un lavorùt di un gener gnûv, e no crôd che vô saressis bon di chatâi il drèt tant facilmenti.","— No sarès bon? Par vuestre regule, chest nâs no l’ha bisugne di imparâ il mistîr di nissùn. No sarès bon! Ha, ha! Uèi propri viodi ce che savês vô fâ di bièl; aprofitàisi pur da’ fusine, dai impresch, di dute la farie. Animo: sù, ch’al è dì!"],"it":["Il Signore alza il capo, legge, e con tutte le cerimonie torna a salutarlo:","«Buon giorno, maestro sopra tutti i maestri.»","«Oh, adesso ci siamo capiti!» risponde il fabbro. «Che cosa volevate?»","«Ero venuto a pregarvi di lasciarmi lavorare qualche minuto nella vostra bottega, che vorrei dare una buona bollitura a un certo pezzo vecchio e logoro che ho qui fuori.»","«Ma datelo qua a me, che se in un batter d’occhio non ve lo faccio tornare nuovo come un bambolotto, voglio sbattezzarmi.»","«Grazie,» ripete il Signore, «ma dovete sapere che è un lavoretto di un genere nuovo, e non credo che sareste capace di trovargli il verso tanto facilmente.»","«Non sarei capace? A vostra regola, questo naso non ha bisogno di imparare il mestiere da nessuno. Non sarei capace! Ah, ah! Voglio proprio vedere che cosa sapete fare voi di bello; servitevi pure della fucina, degli attrezzi, di tutta la bottega. Animo: su, che è giorno!»"],"en":["The Lord raises his head, reads, and with all due ceremony greets him again:","“Good day, master above all masters.”","“Oh, now we understand each other!” answers the smith. “What did you want?”","“I had come to ask you to let me work a few minutes in your smithy, for I should like to give a good forge-weld to a certain old, worn-out piece I have outside.”","“Then give it here to me, and if I don’t make it as good as new in the blink of an eye, may I be unbaptised.”","“Thank you,” says the Lord again, “but you must know it is a new kind of job, and I don’t think you would find the knack of it so easily.”","“Wouldn’t I? For your information, this nose needs to learn the trade from nobody. Wouldn’t I! Ha, ha! I really want to see what fine things you can do; help yourself to the forge, the tools, the whole smithy. Come on: up, it’s daylight!”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-mestri-3\" n=\"IV.3\">\n            <p>Il Signôr al alze il châv, al lèi, e cun dute cerimonie lu torne a saludâ:</p>\n            <p>— Bon dì, mestri sore duch i mestris.</p>\n            <p>— Oh cumò si vin capìd! — al rispuìnd il fari. — Ce voleviso?</p>\n            <p>— Eri vignùd a preàus di lasçâmi lavorâ cualchi minût in ta vuestre farie, che varès voë di dâ une buine soferade a un cert capo vecho e frujàd che hai culì di fûr.</p>\n            <p>— Po dàimel cà a mi, che se in t’un bati di voli no us el fâs tornâ come un pipìn, uèi disbatiâmi.</p>\n            <p>— Graziis, — al torne a dî il Signôr, — ma vês di savê ch’al è un lavorùt di un gener gnûv, e no crôd che vô saressis bon di chatâi il drèt tant facilmenti.</p>\n            <p>— No sarès bon? Par vuestre regule, chest nâs no l’ha bisugne di imparâ il mistîr di nissùn. No sarès bon! Ha, ha! Uèi propri viodi ce che savês vô fâ di bièl; aprofitàisi pur da’ fusine, dai impresch, di dute la farie. Animo: sù, ch’al è dì!</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-3\">\n            <p>Il Signore alza il capo, legge, e con tutte le cerimonie torna a salutarlo:</p>\n            <p>«Buon giorno, maestro sopra tutti i maestri.»</p>\n            <p>«Oh, adesso ci siamo capiti!» risponde il fabbro. «Che cosa volevate?»</p>\n            <p>«Ero venuto a pregarvi di lasciarmi lavorare qualche minuto nella vostra bottega, che vorrei dare una buona bollitura a un certo pezzo vecchio e logoro che ho qui fuori.»</p>\n            <p>«Ma datelo qua a me, che se in un batter d’occhio non ve lo faccio tornare nuovo come un bambolotto, voglio sbattezzarmi.»</p>\n            <p>«Grazie,» ripete il Signore, «ma dovete sapere che è un lavoretto di un genere nuovo, e non credo che sareste capace di trovargli il verso tanto facilmente.»</p>\n            <p>«Non sarei capace? A vostra regola, questo naso non ha bisogno di imparare il mestiere da nessuno. Non sarei capace! Ah, ah! Voglio proprio vedere che cosa sapete fare voi di bello; servitevi pure della fucina, degli attrezzi, di tutta la bottega. Animo: su, che è giorno!»</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-3\">\n            <p>The Lord raises his head, reads, and with all due ceremony greets him again:</p>\n            <p>“Good day, master above all masters.”</p>\n            <p>“Oh, now we understand each other!” answers the smith. “What did you want?”</p>\n            <p>“I had come to ask you to let me work a few minutes in your smithy, for I should like to give a good forge-weld to a certain old, worn-out piece I have outside.”</p>\n            <p>“Then give it here to me, and if I don’t make it as good as new in the blink of an eye, may I be unbaptised.”</p>\n            <p>“Thank you,” says the Lord again, “but you must know it is a new kind of job, and I don’t think you would find the knack of it so easily.”</p>\n            <p>“Wouldn’t I? For your information, this nose needs to learn the trade from nobody. Wouldn’t I! Ha, ha! I really want to see what fine things you can do; help yourself to the forge, the tools, the whole smithy. Come on: up, it’s daylight!”</p>\n          </div>"},{"id":"pf-mestri-4","n":"IV.4","start":true,"orig":["Il Signôr al prepare un bièl boreâr in ta fusine e al emple di aghe il làip grand. Dopo al sbrisse fûr un momènt, e al torne a comparî menànd pe’ man San Pieri; ma un San Pieri cussì vechòn e cadènt, ch’al ere nome peleatis di lui. A’ lu chazze tal fûg, lu fâs deventâ ròs menànd il sfuèi a dùt flàd, j’ bute aduès cualchi zumiele di saldàn; e cuan’ che al è ben ben infogâd, cu lis tanàis lu giave fûr, j’ dà cul màj su l’incuin cuatri sunadis di chês del numer un, e par ultim lu sclope dentri ta l’aghe del làip grànd aciò ch’al chapi la tèmpere. E lì, in mièz al fum di chèl bulimènt, ècoti che al salte fûr ridìnd San Pieri benedèt, deventâd zòvin di vinch agn, fresc e bièl come un garoful. Ringraziâd il fari, i doi pelegrins, senze fâ altris peràulis, a’ si chàpin sù e van pe’ lor strade."],"it":["Il Signore prepara un bel letto di brace nella fucina e riempie d’acqua la vasca grande. Poi scivola fuori un momento, e torna tenendo per mano San Pietro; ma un San Pietro così vecchio e cadente che era soltanto pelle. Lo caccia nel fuoco, lo fa diventare rosso tirando il mantice a tutto fiato, gli butta addosso qualche manciata di sabbia da saldatura; e quando è ben bene infuocato, lo tira fuori con le tenaglie, gli dà col martello sull’incudine quattro colpi di quelli del numero uno, e per ultimo lo tuffa nell’acqua della vasca grande perché prenda la tempera. E lì, in mezzo al fumo di quel ribollire, ecco che salta fuori ridendo San Pietro benedetto, diventato un giovane di vent’anni, fresco e bello come un garofano. Ringraziato il fabbro, i due pellegrini, senza aggiungere parola, si avviano per la loro strada."],"en":["The Lord makes a fine bed of embers in the forge and fills the big trough with water. Then he slips out for a moment and comes back leading St Peter by the hand; but a St Peter so old and doddery that he was nothing but skin. He thrusts him into the fire, makes him red-hot working the bellows full blast, throws a few handfuls of welding sand on him; and when he is glowing through and through, he draws him out with the tongs, gives him four first-class blows with the hammer on the anvil, and last of all plunges him into the water of the big trough so that he takes the temper. And there, in the steam of that boiling, out jumps blessed St Peter laughing, turned into a young man of twenty, fresh and handsome as a carnation. Having thanked the smith, the two pilgrims, without another word, set off on their way."],"note":"In the Sicilian tale (Storia II) Peter tries the Lord’s trick of the oven himself and fails; here the smith does.","xml":"<div type=\"passage\" xml:id=\"pf-mestri-4\" n=\"IV.4\" rend=\"p-start\">\n            <p>Il Signôr al prepare un bièl boreâr in ta fusine e al emple di aghe il làip grand. Dopo al sbrisse fûr un momènt, e al torne a comparî menànd pe’ man San Pieri; ma un San Pieri cussì vechòn e cadènt, ch’al ere nome peleatis di lui. A’ lu chazze tal fûg, lu fâs deventâ ròs menànd il sfuèi a dùt flàd, j’ bute aduès cualchi zumiele di saldàn; e cuan’ che al è ben ben infogâd, cu lis tanàis lu giave fûr, j’ dà cul màj su l’incuin cuatri sunadis di chês del numer un, e par ultim lu sclope dentri ta l’aghe del làip grànd aciò ch’al chapi la tèmpere. E lì, in mièz al fum di chèl bulimènt, ècoti che al salte fûr ridìnd San Pieri benedèt, deventâd zòvin di vinch agn, fresc e bièl come un garoful. Ringraziâd il fari, i doi pelegrins, senze fâ altris peràulis, a’ si chàpin sù e van pe’ lor strade.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-4\">\n            <p>Il Signore prepara un bel letto di brace nella fucina e riempie d’acqua la vasca grande. Poi scivola fuori un momento, e torna tenendo per mano San Pietro; ma un San Pietro così vecchio e cadente che era soltanto pelle. Lo caccia nel fuoco, lo fa diventare rosso tirando il mantice a tutto fiato, gli butta addosso qualche manciata di sabbia da saldatura; e quando è ben bene infuocato, lo tira fuori con le tenaglie, gli dà col martello sull’incudine quattro colpi di quelli del numero uno, e per ultimo lo tuffa nell’acqua della vasca grande perché prenda la tempera. E lì, in mezzo al fumo di quel ribollire, ecco che salta fuori ridendo San Pietro benedetto, diventato un giovane di vent’anni, fresco e bello come un garofano. Ringraziato il fabbro, i due pellegrini, senza aggiungere parola, si avviano per la loro strada.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-4\">\n            <p>The Lord makes a fine bed of embers in the forge and fills the big trough with water. Then he slips out for a moment and comes back leading St Peter by the hand; but a St Peter so old and doddery that he was nothing but skin. He thrusts him into the fire, makes him red-hot working the bellows full blast, throws a few handfuls of welding sand on him; and when he is glowing through and through, he draws him out with the tongs, gives him four first-class blows with the hammer on the anvil, and last of all plunges him into the water of the big trough so that he takes the temper. And there, in the steam of that boiling, out jumps blessed St Peter laughing, turned into a young man of twenty, fresh and handsome as a carnation. Having thanked the smith, the two pilgrims, without another word, set off on their way.</p>\n            <note type=\"translation\">In the Sicilian tale (Storia II) Peter tries the Lord’s trick of the oven himself and fails; here the smith does.</note>\n          </div>"},{"id":"pf-mestri-5","n":"IV.5","start":true,"orig":["A viodi che’ sorte di fature, il mestri sore duch i mestris al restà mièz sberlufìd. Ma no stàit mighe a crodi, vede’, che par chest la vei metude vie! Silafè! Cun che’ ambiziòn ch’al veve!","— Ce grandis robis! — al dîs tiransi la barbe, che pareve une code di mùs vèdul. — Cualuncue schapìn al sa fâ chest tant. Anzi, cumò che m’impensi... O’ hai cassù disore gno pari impotènt sul jèt, che nol puès nanche piùlâ, e no sarà màl che senze pierdi tìmp j’ fasi subit la vore.","Dìt e fât. Al va sù ad alt, al chape so’ pari, che l’ere ridòt nome un sàc di uès, lu puarte a bàs e lu fiche in ta fusine. Il pùar vecho, dopo vê dâd dôs, tre tiessudis cu lis giambis, al si cujetà di colp: ma invece di deventâ rôs, al scomençà a cisâ come une bore verde.","— No tu vûs capile? — j’ dîs il fari. — Spiete cumò tu, bambìn!","Ai butà parsore un’altre cosse di charvòn; e po’ jù certis tiradis di fol, ch’a’ emplàrin dute la stanze di lusìgnis. Cuan’ che j’ parè il momènt, lu sborfà di saldàn ben e no mâl e lu giavà fûr cu lis tanàis par bàtilu su l’incùin. Ma ai prins colps di maj, invece di saldàssi, il vecho al cole jù par tiere schavezzâd mièz par bande."],"it":["A vedere quella sorta di lavoro, il maestro sopra tutti i maestri rimase mezzo sbalordito. Ma non crediate, vedete, che per questo abbia lasciato perdere! Figurarsi! Con l’ambizione che aveva!","«Che grandi cose!» dice tirandosi la barba, che pareva la coda di un asino vecchio. «Qualunque ciabattino sa fare altrettanto. Anzi, adesso che ci penso... Ho lassù di sopra mio padre, impotente a letto, che non può nemmeno lamentarsi, e non sarà male fargli subito il lavoro, senza perdere tempo.»","Detto fatto. Va di sopra, prende suo padre, che era ridotto a un sacco d’ossa, lo porta giù e lo ficca nella fucina. Il povero vecchio, dopo due o tre scalciate, si quietò di colpo: ma invece di diventare rosso cominciò a sfrigolare come un ceppo verde.","«Non vuoi capirla?» gli dice il fabbro. «Aspetta adesso, tu, bambino!»","Gli buttò sopra un’altra cesta di carbone; e poi giù certe tirate di mantice che riempirono tutta la stanza di faville. Quando gli parve il momento, lo spruzzò di sabbia ben bene e lo tirò fuori con le tenaglie per batterlo sull’incudine. Ma ai primi colpi di martello, invece di saldarsi, il vecchio cade a terra spezzato, mezzo per parte."],"en":["Seeing that kind of work, the master above all masters was left half dumbfounded. But don’t go thinking, mind you, that he gave up because of it! Not a bit of it! With the pride he had!","“What great things!” he says, tugging at his beard, which looked like the tail of an old donkey. “Any cobbler can do as much. In fact, now that I think of it… I have my father upstairs, helpless in bed, who can’t even whimper, and it won’t be a bad thing to do the job on him straight away, without wasting time.”","No sooner said than done. He goes upstairs, takes his father, who was reduced to a mere sack of bones, carries him down and shoves him into the forge. The poor old man, after two or three kicks of his legs, fell still at once: but instead of turning red he began to hiss like a green log.","“Won’t you get it?” the smith says to him. “Just you wait now, my little one!”","He threw another basket of charcoal on him, and then some great pulls on the bellows that filled the whole room with sparks. When he thought the moment had come, he sprinkled him well with sand and drew him out with the tongs to hammer him on the anvil. But at the first blows of the hammer, instead of welding, the old man falls to the ground broken, half to each side."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-mestri-5\" n=\"IV.5\" rend=\"p-start\">\n            <p>A viodi che’ sorte di fature, il mestri sore duch i mestris al restà mièz sberlufìd. Ma no stàit mighe a crodi, vede’, che par chest la vei metude vie! Silafè! Cun che’ ambiziòn ch’al veve!</p>\n            <p>— Ce grandis robis! — al dîs tiransi la barbe, che pareve une code di mùs vèdul. — Cualuncue schapìn al sa fâ chest tant. Anzi, cumò che m’impensi... O’ hai cassù disore gno pari impotènt sul jèt, che nol puès nanche piùlâ, e no sarà màl che senze pierdi tìmp j’ fasi subit la vore.</p>\n            <p>Dìt e fât. Al va sù ad alt, al chape so’ pari, che l’ere ridòt nome un sàc di uès, lu puarte a bàs e lu fiche in ta fusine. Il pùar vecho, dopo vê dâd dôs, tre tiessudis cu lis giambis, al si cujetà di colp: ma invece di deventâ rôs, al scomençà a cisâ come une bore verde.</p>\n            <p>— No tu vûs capile? — j’ dîs il fari. — Spiete cumò tu, bambìn!</p>\n            <p>Ai butà parsore un’altre cosse di charvòn; e po’ jù certis tiradis di fol, ch’a’ emplàrin dute la stanze di lusìgnis. Cuan’ che j’ parè il momènt, lu sborfà di saldàn ben e no mâl e lu giavà fûr cu lis tanàis par bàtilu su l’incùin. Ma ai prins colps di maj, invece di saldàssi, il vecho al cole jù par tiere schavezzâd mièz par bande.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-5\">\n            <p>A vedere quella sorta di lavoro, il maestro sopra tutti i maestri rimase mezzo sbalordito. Ma non crediate, vedete, che per questo abbia lasciato perdere! Figurarsi! Con l’ambizione che aveva!</p>\n            <p>«Che grandi cose!» dice tirandosi la barba, che pareva la coda di un asino vecchio. «Qualunque ciabattino sa fare altrettanto. Anzi, adesso che ci penso... Ho lassù di sopra mio padre, impotente a letto, che non può nemmeno lamentarsi, e non sarà male fargli subito il lavoro, senza perdere tempo.»</p>\n            <p>Detto fatto. Va di sopra, prende suo padre, che era ridotto a un sacco d’ossa, lo porta giù e lo ficca nella fucina. Il povero vecchio, dopo due o tre scalciate, si quietò di colpo: ma invece di diventare rosso cominciò a sfrigolare come un ceppo verde.</p>\n            <p>«Non vuoi capirla?» gli dice il fabbro. «Aspetta adesso, tu, bambino!»</p>\n            <p>Gli buttò sopra un’altra cesta di carbone; e poi giù certe tirate di mantice che riempirono tutta la stanza di faville. Quando gli parve il momento, lo spruzzò di sabbia ben bene e lo tirò fuori con le tenaglie per batterlo sull’incudine. Ma ai primi colpi di martello, invece di saldarsi, il vecchio cade a terra spezzato, mezzo per parte.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-5\">\n            <p>Seeing that kind of work, the master above all masters was left half dumbfounded. But don’t go thinking, mind you, that he gave up because of it! Not a bit of it! With the pride he had!</p>\n            <p>“What great things!” he says, tugging at his beard, which looked like the tail of an old donkey. “Any cobbler can do as much. In fact, now that I think of it… I have my father upstairs, helpless in bed, who can’t even whimper, and it won’t be a bad thing to do the job on him straight away, without wasting time.”</p>\n            <p>No sooner said than done. He goes upstairs, takes his father, who was reduced to a mere sack of bones, carries him down and shoves him into the forge. The poor old man, after two or three kicks of his legs, fell still at once: but instead of turning red he began to hiss like a green log.</p>\n            <p>“Won’t you get it?” the smith says to him. “Just you wait now, my little one!”</p>\n            <p>He threw another basket of charcoal on him, and then some great pulls on the bellows that filled the whole room with sparks. When he thought the moment had come, he sprinkled him well with sand and drew him out with the tongs to hammer him on the anvil. But at the first blows of the hammer, instead of welding, the old man falls to the ground broken, half to each side.</p>\n          </div>"},{"id":"pf-mestri-6","n":"IV.6","start":true,"orig":["Alore il mestri, che s’inacuarzè di vêlu copâd, al si metè in t’une disperaziòn tâl, ch’al fò su lis tre e tre cuàrz par butàssi vie. Senonchè, visansi di ce ch’al veve viodùd pôc prime, al implantà alì zùs e vergòns, e dùt strassameâd, cui vôi fûr dal châv, al si tacà a cori daur ai doi viandànz. Fât un bocòn di strade ju chapà.","— Ou galantòm! galantòm! — ai vosà al Signôr.","— Ce us ocòriel, mestri sore duch i mestris?","— Ah par l’amôr di Dio — disèl — tornàit là di me, che forsi sarês bon anchemò di comedâ gno pari. Soi lâd par soferâlu, come che vês fât vô, e invece lu hai dùt brusâd e paràd in doi."],"it":["Allora il maestro, accortosi di averlo ucciso, si mise in una tale disperazione che fu lì lì per farla finita. Senonché, ricordandosi di ciò che aveva visto poco prima, piantò lì mazze e verghe e, tutto scarmigliato, con gli occhi fuori dalla testa, si mise a correre dietro ai due viandanti. Fatto un pezzo di strada, li raggiunse.","«Ehi, galantuomo! galantuomo!» gridò al Signore.","«Che cosa vi occorre, maestro sopra tutti i maestri?»","«Ah, per l’amor di Dio,» disse, «tornate da me, che forse sarete ancora capace di aggiustare mio padre. Sono andato a bollirlo, come avete fatto voi, e invece l’ho tutto bruciato e spezzato in due.»"],"en":["Then the master, realising he had killed him, fell into such despair that he was on the very point of doing away with himself. But then, remembering what he had seen a little earlier, he dropped his hammers and rods there and then and, all dishevelled, his eyes popping out of his head, ran off after the two wayfarers. A little way down the road he caught up with them.","“Hey, good sir! good sir!” he shouted to the Lord.","“What do you need, master above all masters?”","“Oh, for the love of God,” he said, “come back to my house, for perhaps you can still mend my father. I went to weld him, as you did, and instead I’ve burnt him all over and broken him in two.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-mestri-6\" n=\"IV.6\" rend=\"p-start\">\n            <p>Alore il mestri, che s’inacuarzè di vêlu copâd, al si metè in t’une disperaziòn tâl, ch’al fò su lis tre e tre cuàrz par butàssi vie. Senonchè, visansi di ce ch’al veve viodùd pôc prime, al implantà alì zùs e vergòns, e dùt strassameâd, cui vôi fûr dal châv, al si tacà a cori daur ai doi viandànz. Fât un bocòn di strade ju chapà.</p>\n            <p>— Ou galantòm! galantòm! — ai vosà al Signôr.</p>\n            <p>— Ce us ocòriel, mestri sore duch i mestris?</p>\n            <p>— Ah par l’amôr di Dio — disèl — tornàit là di me, che forsi sarês bon anchemò di comedâ gno pari. Soi lâd par soferâlu, come che vês fât vô, e invece lu hai dùt brusâd e paràd in doi.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-6\">\n            <p>Allora il maestro, accortosi di averlo ucciso, si mise in una tale disperazione che fu lì lì per farla finita. Senonché, ricordandosi di ciò che aveva visto poco prima, piantò lì mazze e verghe e, tutto scarmigliato, con gli occhi fuori dalla testa, si mise a correre dietro ai due viandanti. Fatto un pezzo di strada, li raggiunse.</p>\n            <p>«Ehi, galantuomo! galantuomo!» gridò al Signore.</p>\n            <p>«Che cosa vi occorre, maestro sopra tutti i maestri?»</p>\n            <p>«Ah, per l’amor di Dio,» disse, «tornate da me, che forse sarete ancora capace di aggiustare mio padre. Sono andato a bollirlo, come avete fatto voi, e invece l’ho tutto bruciato e spezzato in due.»</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-6\">\n            <p>Then the master, realising he had killed him, fell into such despair that he was on the very point of doing away with himself. But then, remembering what he had seen a little earlier, he dropped his hammers and rods there and then and, all dishevelled, his eyes popping out of his head, ran off after the two wayfarers. A little way down the road he caught up with them.</p>\n            <p>“Hey, good sir! good sir!” he shouted to the Lord.</p>\n            <p>“What do you need, master above all masters?”</p>\n            <p>“Oh, for the love of God,” he said, “come back to my house, for perhaps you can still mend my father. I went to weld him, as you did, and instead I’ve burnt him all over and broken him in two.”</p>\n          </div>"},{"id":"pf-mestri-7","n":"IV.7","start":true,"orig":["— Ben, vàit là, vàit là a chase, che lu chatarês viv — j’ rispuìnd il Signôr; — nome us visi che al sarà vieli nali come prime. E di cà indavànt no stàit a lasçassi mai plui vignî tal châv che nissùn altri artist nol puedi savê alc plui di vô.","Il fari al tornà filâd a chase, dulà che di fât al chatà so’ pari come ch’al veve dìt il Signôr. In che’ dì istesse al parà jù l’iscriziòn sore la puarte da’ farie, e al so’ puèst a’n tacà sù un’altre plui modeste ch’a’ diseve:","Ogni mês si fâs la lune,","Ogni dì s’impare une."],"it":["«Bene, andate, andate a casa, che lo troverete vivo,» gli risponde il Signore; «soltanto vi avverto che sarà vecchio come prima. E d’ora in avanti non lasciatevi mai più venire in testa che nessun altro artigiano possa sapere qualcosa più di voi.»","Il fabbro tornò a casa di filato, dove difatti trovò suo padre come gli aveva detto il Signore. Quello stesso giorno tolse l’iscrizione da sopra la porta della bottega, e al suo posto ne appese un’altra, più modesta, che diceva:","Ogni mese si fa la luna,","ogni giorno se ne impara una."],"en":["“Well, go, go home, and you’ll find him alive,” the Lord answers; “only I warn you that he will be just as old as before. And from now on never again let it into your head that no other craftsman can know something more than you.”","The smith went straight home, where he found his father just as the Lord had said. That very day he took down the sign over the smithy door, and in its place he hung up another, more modest one, which said:","Every month the moon comes new,","every day you learn a thing or two."],"note":"“Vieli nali come prime”: the sense is “as old as before”; nali is uncertain.","xml":"<div type=\"passage\" xml:id=\"pf-mestri-7\" n=\"IV.7\" rend=\"p-start\">\n            <p>— Ben, vàit là, vàit là a chase, che lu chatarês viv — j’ rispuìnd il Signôr; — nome us visi che al sarà vieli nali come prime. E di cà indavànt no stàit a lasçassi mai plui vignî tal châv che nissùn altri artist nol puedi savê alc plui di vô.</p>\n            <p>Il fari al tornà filâd a chase, dulà che di fât al chatà so’ pari come ch’al veve dìt il Signôr. In che’ dì istesse al parà jù l’iscriziòn sore la puarte da’ farie, e al so’ puèst a’n tacà sù un’altre plui modeste ch’a’ diseve:</p>\n            <p>Ogni mês si fâs la lune,</p>\n            <p>Ogni dì s’impare une.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-7\">\n            <p>«Bene, andate, andate a casa, che lo troverete vivo,» gli risponde il Signore; «soltanto vi avverto che sarà vecchio come prima. E d’ora in avanti non lasciatevi mai più venire in testa che nessun altro artigiano possa sapere qualcosa più di voi.»</p>\n            <p>Il fabbro tornò a casa di filato, dove difatti trovò suo padre come gli aveva detto il Signore. Quello stesso giorno tolse l’iscrizione da sopra la porta della bottega, e al suo posto ne appese un’altra, più modesta, che diceva:</p>\n            <p>Ogni mese si fa la luna,</p>\n            <p>ogni giorno se ne impara una.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-mestri-7\">\n            <p>“Well, go, go home, and you’ll find him alive,” the Lord answers; “only I warn you that he will be just as old as before. And from now on never again let it into your head that no other craftsman can know something more than you.”</p>\n            <p>The smith went straight home, where he found his father just as the Lord had said. That very day he took down the sign over the smithy door, and in its place he hung up another, more modest one, which said:</p>\n            <p>Every month the moon comes new,</p>\n            <p>every day you learn a thing or two.</p>\n            <note type=\"translation\">“Vieli nali come prime”: the sense is “as old as before”; nali is uncertain.</note>\n          </div>"}],"gap":null,"atu":{"code":"753","label":"Christ and the Smith"},"itResp":"ed2026","gulpease":64.2,"words":{"orig":955,"it":830,"en":942}},{"id":"pf-ustinad","kind":"tale","n":"V","heads":{"orig":"L’ustinàd","it":"L’ostinato","en":"The stubborn man"},"refs":["great","orgnano"],"record":["Pagine friulane, a. V (1892), p. 24, Internet Archive; ATU If God Wills (assigned 2026). “Chapade su a Orgnan”, collected at Orgnano."],"passages":[{"id":"pf-ustinad-1","n":"V.1","start":true,"orig":["Une dì il Signor e San Pieri a levin vie par une strade, cuand che a vioderin a vignissi incuintri un, chaminand imburìd, mescedand i brazz come ch’al vess vûd di lâ a chapâ il prin.","Cuand ch’al fo dongie:","— Dulà vaiso? — ’i disè San Pieri.","E chell, cun-t’une vosate:","— A Rome ài di lâ.","— Ben se Dio orà — rispuindè San Pieri.","— Orà o non orà, a Rome ài di lâ — dissal lui.","E San Pieri in che volte al Signor:","— Chastiinlu, Signor, par ch’al crôd di podè fâ ce ch’al ûl cence di vo.","E il Signor:","— Chastiilu, Pieri.","E San Pieri:","— Mùditi ’n crot.","E chel om al doventà sùbit un crot e viodùde un poche di aghe t’un fossâl, dongie de strade, al petà un salt dentri.","Il Signor e San Pieri a continüàrin a lâ vie chacarànd."],"it":["Un giorno il Signore e San Pietro andavano per una strada, quando videro venire loro incontro un uomo che camminava di gran fretta, agitando le braccia come se dovesse arrivare per primo.","Quando fu vicino:","«Dove andate?» gli disse San Pietro.","E quello, con un vocione:","«A Roma devo andare.»","«Bene, se Dio vorrà,» rispose San Pietro.","«Voglia o non voglia, a Roma devo andare,» disse lui.","E San Pietro allora al Signore:","«Castighiamolo, Signore, perché crede di poter fare quel che vuole senza di voi.»","E il Signore:","«Castigalo, Pietro.»","E San Pietro:","«Mutati in rospo.»","E quell’uomo diventò subito un rospo e, visto un po’ d’acqua in un fosso vicino alla strada, ci saltò dentro.","Il Signore e San Pietro continuarono per la loro strada chiacchierando."],"en":["One day the Lord and St Peter were going along a road, when they saw a man coming towards them, walking in a great hurry and swinging his arms as if he had to be first to get somewhere.","When he was close:","“Where are you going?” St Peter asked him.","And he, in a big voice:","“To Rome I have to go.”","“Very well, God willing,” answered St Peter.","“God willing or not, to Rome I have to go,” he said.","Then St Peter to the Lord:","“Let’s punish him, Lord, for he thinks he can do what he likes without you.”","And the Lord:","“Punish him, Peter.”","And St Peter:","“Turn into a toad.”","And the man at once became a toad and, seeing a little water in a ditch by the road, jumped into it.","The Lord and St Peter went on their way, chatting."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-ustinad-1\" n=\"V.1\" rend=\"p-start\">\n            <p>Une dì il Signor e San Pieri a levin vie par une strade, cuand che a vioderin a vignissi incuintri un, chaminand imburìd, mescedand i brazz come ch’al vess vûd di lâ a chapâ il prin.</p>\n            <p>Cuand ch’al fo dongie:</p>\n            <p>— Dulà vaiso? — ’i disè San Pieri.</p>\n            <p>E chell, cun-t’une vosate:</p>\n            <p>— A Rome ài di lâ.</p>\n            <p>— Ben se Dio orà — rispuindè San Pieri.</p>\n            <p>— Orà o non orà, a Rome ài di lâ — dissal lui.</p>\n            <p>E San Pieri in che volte al Signor:</p>\n            <p>— Chastiinlu, Signor, par ch’al crôd di podè fâ ce ch’al ûl cence di vo.</p>\n            <p>E il Signor:</p>\n            <p>— Chastiilu, Pieri.</p>\n            <p>E San Pieri:</p>\n            <p>— Mùditi ’n crot.</p>\n            <p>E chel om al doventà sùbit un crot e viodùde un poche di aghe t’un fossâl, dongie de strade, al petà un salt dentri.</p>\n            <p>Il Signor e San Pieri a continüàrin a lâ vie chacarànd.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-ustinad-1\">\n            <p>Un giorno il Signore e San Pietro andavano per una strada, quando videro venire loro incontro un uomo che camminava di gran fretta, agitando le braccia come se dovesse arrivare per primo.</p>\n            <p>Quando fu vicino:</p>\n            <p>«Dove andate?» gli disse San Pietro.</p>\n            <p>E quello, con un vocione:</p>\n            <p>«A Roma devo andare.»</p>\n            <p>«Bene, se Dio vorrà,» rispose San Pietro.</p>\n            <p>«Voglia o non voglia, a Roma devo andare,» disse lui.</p>\n            <p>E San Pietro allora al Signore:</p>\n            <p>«Castighiamolo, Signore, perché crede di poter fare quel che vuole senza di voi.»</p>\n            <p>E il Signore:</p>\n            <p>«Castigalo, Pietro.»</p>\n            <p>E San Pietro:</p>\n            <p>«Mutati in rospo.»</p>\n            <p>E quell’uomo diventò subito un rospo e, visto un po’ d’acqua in un fosso vicino alla strada, ci saltò dentro.</p>\n            <p>Il Signore e San Pietro continuarono per la loro strada chiacchierando.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-ustinad-1\">\n            <p>One day the Lord and St Peter were going along a road, when they saw a man coming towards them, walking in a great hurry and swinging his arms as if he had to be first to get somewhere.</p>\n            <p>When he was close:</p>\n            <p>“Where are you going?” St Peter asked him.</p>\n            <p>And he, in a big voice:</p>\n            <p>“To Rome I have to go.”</p>\n            <p>“Very well, God willing,” answered St Peter.</p>\n            <p>“God willing or not, to Rome I have to go,” he said.</p>\n            <p>Then St Peter to the Lord:</p>\n            <p>“Let’s punish him, Lord, for he thinks he can do what he likes without you.”</p>\n            <p>And the Lord:</p>\n            <p>“Punish him, Peter.”</p>\n            <p>And St Peter:</p>\n            <p>“Turn into a toad.”</p>\n            <p>And the man at once became a toad and, seeing a little water in a ditch by the road, jumped into it.</p>\n            <p>The Lord and St Peter went on their way, chatting.</p>\n          </div>"},{"id":"pf-ustinad-2","n":"V.2","start":true,"orig":["Vot agns dopo, mo, a tornàrin a passâ par lì; San Pieri a si visà dal om cambiàd in crot, e, voltàd al Signor:","— Vino di perdonai? — dissal.","— Perdonìn, — rispuindè il Signor.","E San Pieri, làd dongie l’aghe, al disè al crot:","— Torne om.","Al tornà subit om, al petà un salt sula strade, e vie plui imburìd di prime.","E San Pieri:","— Dulà vaiso po’? — dissal.","E l’om:","— A Rome ài di lâ.","E San Peri: — Ben se Dio orà.","E l’om:","— Orà o non orà, a Rome ài di lâ.","— Nòo! — dissal San Pieri.","E chell ch’al ere zà lontan, voltansi:","— Soi stàd vot angs crot e m’infoti a stâ anche vot; a Rome ài di lâ.","San Pieri al tornave a inrabiàsi, ma ’l Signor ridind a-i disè:","— Cuïètiti, Pieri; chell là ’l è un ustinàd e nissun plui lu voltarà."],"it":["Otto anni dopo tornarono a passare di lì; San Pietro si ricordò dell’uomo cambiato in rospo e, voltatosi al Signore:","«Dobbiamo perdonarlo?» disse.","«Perdoniamolo,» rispose il Signore.","E San Pietro, andato vicino all’acqua, disse al rospo:","«Torna uomo.»","Tornò subito uomo, fece un salto sulla strada, e via più in fretta di prima.","E San Pietro:","«Dove andate, dunque?» disse.","E l’uomo:","«A Roma devo andare.»","E San Pietro: «Bene, se Dio vorrà.»","E l’uomo:","«Voglia o non voglia, a Roma devo andare.»","«Nooo!» disse San Pietro.","E quello, che era già lontano, voltandosi:","«Sono stato otto anni rospo e me ne infischio di starci altri otto; a Roma devo andare.»","San Pietro tornava ad arrabbiarsi, ma il Signore ridendo gli disse:","«Calmati, Pietro; quello là è un ostinato e nessuno lo farà più cambiare.»"],"en":["Eight years later they passed that way again; St Peter remembered the man changed into a toad and, turning to the Lord:","“Shall we forgive him?” he said.","“Let’s forgive him,” answered the Lord.","And St Peter, going up to the water, said to the toad:","“Be a man again.”","At once he was a man again, leapt out onto the road, and off he went faster than before.","And St Peter:","“Where are you going, then?” he said.","And the man:","“To Rome I have to go.”","And St Peter: “Very well, God willing.”","And the man:","“God willing or not, to Rome I have to go.”","“Nooo!” said St Peter.","And the man, already far off, turning round:","“I’ve been a toad for eight years and I don’t care if I’m one for another eight; to Rome I have to go.”","St Peter was getting angry again, but the Lord said to him, laughing:","“Calm down, Peter; that man is a stubborn one, and no one will ever turn him round.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"pf-ustinad-2\" n=\"V.2\" rend=\"p-start\">\n            <p>Vot agns dopo, mo, a tornàrin a passâ par lì; San Pieri a si visà dal om cambiàd in crot, e, voltàd al Signor:</p>\n            <p>— Vino di perdonai? — dissal.</p>\n            <p>— Perdonìn, — rispuindè il Signor.</p>\n            <p>E San Pieri, làd dongie l’aghe, al disè al crot:</p>\n            <p>— Torne om.</p>\n            <p>Al tornà subit om, al petà un salt sula strade, e vie plui imburìd di prime.</p>\n            <p>E San Pieri:</p>\n            <p>— Dulà vaiso po’? — dissal.</p>\n            <p>E l’om:</p>\n            <p>— A Rome ài di lâ.</p>\n            <p>E San Peri: — Ben se Dio orà.</p>\n            <p>E l’om:</p>\n            <p>— Orà o non orà, a Rome ài di lâ.</p>\n            <p>— Nòo! — dissal San Pieri.</p>\n            <p>E chell ch’al ere zà lontan, voltansi:</p>\n            <p>— Soi stàd vot angs crot e m’infoti a stâ anche vot; a Rome ài di lâ.</p>\n            <p>San Pieri al tornave a inrabiàsi, ma ’l Signor ridind a-i disè:</p>\n            <p>— Cuïètiti, Pieri; chell là ’l è un ustinàd e nissun plui lu voltarà.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-ustinad-2\">\n            <p>Otto anni dopo tornarono a passare di lì; San Pietro si ricordò dell’uomo cambiato in rospo e, voltatosi al Signore:</p>\n            <p>«Dobbiamo perdonarlo?» disse.</p>\n            <p>«Perdoniamolo,» rispose il Signore.</p>\n            <p>E San Pietro, andato vicino all’acqua, disse al rospo:</p>\n            <p>«Torna uomo.»</p>\n            <p>Tornò subito uomo, fece un salto sulla strada, e via più in fretta di prima.</p>\n            <p>E San Pietro:</p>\n            <p>«Dove andate, dunque?» disse.</p>\n            <p>E l’uomo:</p>\n            <p>«A Roma devo andare.»</p>\n            <p>E San Pietro: «Bene, se Dio vorrà.»</p>\n            <p>E l’uomo:</p>\n            <p>«Voglia o non voglia, a Roma devo andare.»</p>\n            <p>«Nooo!» disse San Pietro.</p>\n            <p>E quello, che era già lontano, voltandosi:</p>\n            <p>«Sono stato otto anni rospo e me ne infischio di starci altri otto; a Roma devo andare.»</p>\n            <p>San Pietro tornava ad arrabbiarsi, ma il Signore ridendo gli disse:</p>\n            <p>«Calmati, Pietro; quello là è un ostinato e nessuno lo farà più cambiare.»</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pf-ustinad-2\">\n            <p>Eight years later they passed that way again; St Peter remembered the man changed into a toad and, turning to the Lord:</p>\n            <p>“Shall we forgive him?” he said.</p>\n            <p>“Let’s forgive him,” answered the Lord.</p>\n            <p>And St Peter, going up to the water, said to the toad:</p>\n            <p>“Be a man again.”</p>\n            <p>At once he was a man again, leapt out onto the road, and off he went faster than before.</p>\n            <p>And St Peter:</p>\n            <p>“Where are you going, then?” he said.</p>\n            <p>And the man:</p>\n            <p>“To Rome I have to go.”</p>\n            <p>And St Peter: “Very well, God willing.”</p>\n            <p>And the man:</p>\n            <p>“God willing or not, to Rome I have to go.”</p>\n            <p>“Nooo!” said St Peter.</p>\n            <p>And the man, already far off, turning round:</p>\n            <p>“I’ve been a toad for eight years and I don’t care if I’m one for another eight; to Rome I have to go.”</p>\n            <p>St Peter was getting angry again, but the Lord said to him, laughing:</p>\n            <p>“Calm down, Peter; that man is a stubborn one, and no one will ever turn him round.”</p>\n          </div>"}],"gap":null,"atu":{"code":"830C","label":"If God Wills"},"itResp":"ed2026","gulpease":72.8,"words":{"orig":309,"it":263,"en":321}}],"glossary":[{"forms":["chast"],"it":"granaio; qui magazzino, serbatoio, archivio","en":"granary; here storehouse, archive","src":"Pagine friulane, note to n. III"},{"forms":["rieste di ai"],"it":"treccia di gambi d’aglio intrecciati per lo stelo","en":"braid of garlic, plaited by the stalks","src":"Pagine friulane, note to n. III"},{"forms":["sarasìn"],"it":"grano saraceno","en":"buckwheat","src":null},{"forms":["forment"],"it":"frumento","en":"wheat","src":null},{"forms":["batài"],"it":"correggiati","en":"flails","src":null},{"forms":["bearz"],"it":"cortile","en":"yard","src":null},{"forms":["stizz"],"it":"tizzone","en":"burning brand","src":null},{"forms":["bule"],"it":"pula","en":"chaff","src":null},{"forms":["stran"],"it":"paglia","en":"straw","src":null},{"forms":["strie"],"it":"strega","en":"witch","src":null},{"forms":["jett","jèt"],"it":"letto","en":"bed","src":null},{"forms":["parone"],"it":"padrona","en":"mistress (of the house)","src":null},{"forms":["làd"],"it":"lago","en":"lake","src":null},{"forms":["aghe"],"it":"acqua","en":"water","src":null},{"forms":["vechute","vechùte"],"it":"vecchietta","en":"little old woman","src":null},{"forms":["àgnui"],"it":"angeli","en":"angels","src":null},{"forms":["glesiùte"],"it":"chiesetta","en":"little church","src":null},{"forms":["tangàrs"],"it":"tangheri","en":"louts","src":null},{"forms":["fari"],"it":"fabbro","en":"blacksmith","src":null},{"forms":["farie"],"it":"bottega del fabbro","en":"smithy","src":null},{"forms":["fusine"],"it":"fucina","en":"forge","src":null},{"forms":["incùin","incuin"],"it":"incudine","en":"anvil","src":null},{"forms":["tanàis"],"it":"tenaglie","en":"tongs","src":null},{"forms":["màj","maj"],"it":"martello","en":"hammer","src":null},{"forms":["làip"],"it":"vasca","en":"trough","src":null},{"forms":["fol"],"it":"mantice","en":"bellows","src":null},{"forms":["sfuèi"],"it":"mantice","en":"bellows","src":null},{"forms":["saldàn"],"it":"sabbia da saldatura","en":"welding sand","src":null},{"forms":["charvòn"],"it":"carbone","en":"charcoal","src":null},{"forms":["lusìgnis"],"it":"faville","en":"sparks","src":null},{"forms":["soferade","soferâlu"],"it":"bollitura, saldatura a fuoco","en":"forge-weld","src":null},{"forms":["crot"],"it":"rospo","en":"toad","src":null},{"forms":["fossâl"],"it":"fosso","en":"ditch","src":null},{"forms":["ustinàd"],"it":"ostinato","en":"stubborn","src":null},{"forms":["imburìd"],"it":"di fretta","en":"in a hurry","src":null},{"forms":["mâri"],"it":"madre","en":"mother","src":null},{"forms":["infièr"],"it":"inferno","en":"hell","src":null},{"forms":["cha-dal-diàul"],"it":"casa del diavolo, inferno","en":"the devil’s house, hell","src":null},{"forms":["teremòt"],"it":"terremoto","en":"earthquake","src":null},{"forms":["Pieri"],"it":"Pietro","en":"Peter","src":null},{"forms":["Signor","Signôr","Signòr"],"it":"Signore","en":"Lord","src":null}],"gulpease":62.2},"friuli":{"id":"friuli","file":"tei/friuli.xml","title":"Gesù e San Pietro in Friuli","lang":"fur","dialect":{"en":"Friulian","it":"friulano"},"places":[{"id":"cormons","name":"Cormòns","wikidata":["https://www.wikidata.org/wiki/Q53124"],"lat":45.95,"lon":13.4667},{"id":"enemonzo","name":"Enemonzo e Preone","wikidata":["https://www.wikidata.org/wiki/Q53255","https://www.wikidata.org/wiki/Q53319"],"lat":46.4055,"lon":12.8727}],"persons":[{"id":"braida","name":"Caterina Braida (Minèn)","role":"narrator, episode I","wikidata":null},{"id":"mines","name":"Giovanni Minèn","role":"narrator, episode II","wikidata":null},{"id":"taddio","name":"Iole Taddio (Iole di Mini)","role":"narrator, episode III","wikidata":null},{"id":"zorzut","name":"Dolfo Zorzùt","role":"collector","wikidata":"https://www.wikidata.org/wiki/Q11917551"}],"sources":[{"type":"source","text":"Dolfo Zorzùt, Sot la nape… (I racconti del popolo friulano), 3 voll., Udine, 1924–1927; episode I at 22–24.","links":["https://www.wikidata.org/wiki/Q11917551"]},{"type":"catalogue","text":"Catalogo di Racconti Popolari Friulani, Società Filologica Friulana, raccontipopolari.filologicafriulana.it.","links":["https://www.wikidata.org/wiki/Q659695","http://raccontipopolari.filologicafriulana.it/"]},{"type":"retelling","text":"Italo Calvino, Fiabe italiane, Torino, Einaudi, 1956: “Gesù e San Pietro in Friuli”.","links":["https://www.wikidata.org/wiki/Q154756","https://www.wikidata.org/wiki/Q3744324"]}],"heads":{},"editorial":{"lang":"it","blocks":[{"p":["Gesù e San Pietro in Friuli è un ciclo di quattro racconti nelle Fiabe italiane di Calvino.","Ogni racconto si basa su una variante friulana."]},{"list":["Come fu che San Pietro è andato col Signore","La coratella di lepre","L'ospitalità","Il grano saraceno"]},{"p":["Le traduzioni si basano sulle raccolte contenute nel Catalogo di Racconti Popolari Friulani della Società Filologica Friulana (https://raccontipopolari.filologicafriulana.it/)."]}]},"units":[{"id":"friuli-I","kind":"episode","n":"I","heads":{"orig":"Zimût che san Pieri al è lât cul Signôr","it":"Come fu che San Pietro è andato col Signore","en":"How St Peter came to go with the Lord"},"refs":["braida","cormons"],"record":["Informatore: Caterina Braida ved. Minèn","Racconto presente nella Raccolta “Sot la Nape”","pp. 22-24","Luogo di rilevamento: Cormòns (GO)","Classificazione ATU: 774 Cristo e San Pietro"],"passages":[{"id":"friuli-I-1","n":"I.1","start":true,"orig":["“Cio, Tine” - al dîs Pieri a la so fèmine - “z'e' vino di mangiâ usgnöt?”"],"it":["“Dimmi Tina...” - disse Pietro a sua moglie - “cosa mangiamo stasera?”"],"en":["“Listen, Tina,” says Peter to his wife, “what have we got to eat tonight?”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"friuli-I-1\" n=\"I.1\" rend=\"p-start\">\n            <p>“Cio, Tine” - al dîs Pieri a la so fèmine - “z'e' vino di mangiâ usgnöt?”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-1\">\n            <p>“Dimmi Tina...” - disse Pietro a sua moglie - “cosa mangiamo stasera?”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-1\">\n            <p>“Listen, Tina,” says Peter to his wife, “what have we got to eat tonight?”</p>\n          </div>"},{"id":"friuli-I-2","n":"I.2","start":false,"orig":["- “Po, Pieri, sôi stade dut el dl a zirî alc e no âi ciatât propi nuje. Ze ûstu fâi mo, zunìn.”"],"it":["- “Eh, Pietro...ho passato tutto il giorno a cercare qualcosa da mangiare ma non ho trovato nulla. Che vuoi fare...digiuneremo.”"],"en":["“Oh, Peter, I’ve spent the whole day looking for something and found nothing at all. What can you do… we’ll go hungry.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"friuli-I-2\" n=\"I.2\">\n            <p>- “Po, Pieri, sôi stade dut el dl a zirî alc e no âi ciatât propi nuje. Ze ûstu fâi mo, zunìn.”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-2\">\n            <p>- “Eh, Pietro...ho passato tutto il giorno a cercare qualcosa da mangiare ma non ho trovato nulla. Che vuoi fare...digiuneremo.”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-2\">\n            <p>“Oh, Peter, I’ve spent the whole day looking for something and found nothing at all. What can you do… we’ll go hungry.”</p>\n          </div>"},{"id":"friuli-I-3","n":"I.3","start":false,"orig":["- “A ! sacre da vanzete, dopo jessi stât dut el dü a sbordonâ pès, dopo di vê strussiât como un danât 'ta chÊ sflamiadis di soreli, lâ a durmî senze.... Anìn, sìt. svelte, tire fur alc di mangiâ !” -"],"it":["- “Ah! Diamine! Dopo aver passato tutta la giornata ad infilzare pesci... dopo aver lavorato così faticosamente sotto il sole cocente... dovrei andare a dormire senza cena? Andiamo, veloce, tira furoi qualcosa da mangiare!”"],"en":["“Ah! Blast it! After a whole day spearing fish, after toiling like one of the damned in that blazing sun, I’m to go to bed without supper? Come on, quick, bring out something to eat!”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"friuli-I-3\" n=\"I.3\">\n            <p>- “A ! sacre da vanzete, dopo jessi stât dut el dü a sbordonâ pès, dopo di vê strussiât como un danât 'ta chÊ sflamiadis di soreli, lâ a durmî senze.... Anìn, sìt. svelte, tire fur alc di mangiâ !” -</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-3\">\n            <p>- “Ah! Diamine! Dopo aver passato tutta la giornata ad infilzare pesci... dopo aver lavorato così faticosamente sotto il sole cocente... dovrei andare a dormire senza cena? Andiamo, veloce, tira furoi qualcosa da mangiare!”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-3\">\n            <p>“Ah! Blast it! After a whole day spearing fish, after toiling like one of the damned in that blazing sun, I’m to go to bed without supper? Come on, quick, bring out something to eat!”</p>\n          </div>"},{"id":"friuli-I-4","n":"I.4","start":false,"orig":["“ Mâ, Pieri, jo no âi propi nance tant di nreti in t'un voli. Sâstu ze, anin tál ciamp di chel sior.... là sôn' cussì biei tors di vetze, a sôn.” - “A ! jo no vuei jessi un lari.”- “Ze, lari, ti prei, tal ciamp dal Signòr..'. .- “E se nus ciatin mo?.... Cussì duc'i doi insieme?” - “Po, sâstu ze: par no dâ tal voli, larìn un di 'ne bancle e chel altri di chê altre.” - “Va ben, va ben. Zà, pitòst cussi che stâ cu la panze sclàgne.”"],"it":["“Ma Pietro... io non ho proprio niente di niente. Sai cosa? Andiamo nel campo di quel signore...là ci sono dei cavoli così belli.” - “Ah! Io non voglio essere un ladro!” - “Ma che ladro! Ma che dici! Sarebbe solo nel campo del signore...” - “E se ci scoprono? Così, tutti e due insieme?” - “Allora, sai cosa possiamo fare? Andiamo uno da una parte e uno dall'altra.” - “Va bene, va bene... meglio così che stare a stomaco vuoto!”."],"en":["“But Peter, I haven’t got so much as a crumb. You know what? Let’s go to that gentleman’s field… there are such fine cabbages there.” “Ah! I don’t want to be a thief!” “Thief, go on! It’s only the gentleman’s field…” “And what if they catch us, the two of us together?” “Well then, you know what: so as not to be seen, we’ll go in one from one side and one from the other.” “All right, all right. Better that than an empty belly.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"friuli-I-4\" n=\"I.4\">\n            <p>“ Mâ, Pieri, jo no âi propi nance tant di nreti in t'un voli. Sâstu ze, anin tál ciamp di chel sior.... là sôn' cussì biei tors di vetze, a sôn.” - “A ! jo no vuei jessi un lari.”- “Ze, lari, ti prei, tal ciamp dal Signòr..'. .- “E se nus ciatin mo?.... Cussì duc'i doi insieme?” - “Po, sâstu ze: par no dâ tal voli, larìn un di 'ne bancle e chel altri di chê altre.” - “Va ben, va ben. Zà, pitòst cussi che stâ cu la panze sclàgne.”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-4\">\n            <p>“Ma Pietro... io non ho proprio niente di niente. Sai cosa? Andiamo nel campo di quel signore...là ci sono dei cavoli così belli.” - “Ah! Io non voglio essere un ladro!” - “Ma che ladro! Ma che dici! Sarebbe solo nel campo del signore...” - “E se ci scoprono? Così, tutti e due insieme?” - “Allora, sai cosa possiamo fare? Andiamo uno da una parte e uno dall'altra.” - “Va bene, va bene... meglio così che stare a stomaco vuoto!”.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-4\">\n            <p>“But Peter, I haven’t got so much as a crumb. You know what? Let’s go to that gentleman’s field… there are such fine cabbages there.” “Ah! I don’t want to be a thief!” “Thief, go on! It’s only the gentleman’s field…” “And what if they catch us, the two of us together?” “Well then, you know what: so as not to be seen, we’ll go in one from one side and one from the other.” “All right, all right. Better that than an empty belly.”</p>\n          </div>"},{"id":"friuli-I-5","n":"I.5","start":true,"orig":["E un di 'ne bande e chel altri di chê altre ti van lor tal ciamp. Ciaminànt di lunc da strade Pieri al incuintre un on biont cutt doi biei voi gris, che 'l pâr un agnul in ciar e vues, sintât sun t'un paraciàr."],"it":["E così, uno da una parte e uno dall'altra, vanno nel campo. Camminando lungo la strada Pietro incontra un uomo biondo con due begli occhi grigi, così tanto che gli pareva un angelo in carne ed ossa, seduto su un paracarro."],"en":["And so, one from one side and one from the other, off they go to the field. Walking along the road, Peter meets a fair-haired man with two lovely grey eyes, like an angel in flesh and blood, sitting on a kerbstone."],"note":null,"xml":"<div type=\"passage\" xml:id=\"friuli-I-5\" n=\"I.5\" rend=\"p-start\">\n            <p>E un di 'ne bande e chel altri di chê altre ti van lor tal ciamp. Ciaminànt di lunc da strade Pieri al incuintre un on biont cutt doi biei voi gris, che 'l pâr un agnul in ciar e vues, sintât sun t'un paraciàr.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-5\">\n            <p>E così, uno da una parte e uno dall'altra, vanno nel campo. Camminando lungo la strada Pietro incontra un uomo biondo con due begli occhi grigi, così tanto che gli pareva un angelo in carne ed ossa, seduto su un paracarro.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-5\">\n            <p>And so, one from one side and one from the other, off they go to the field. Walking along the road, Peter meets a fair-haired man with two lovely grey eyes, like an angel in flesh and blood, sitting on a kerbstone.</p>\n          </div>"},{"id":"friuli-I-6","n":"I.6","start":false,"orig":["\" Spiète, a vuei provâ di ze savòr che 'l sa chìst furistîr - âl pense e al dîs fra di sè Pieri. “Giò galantòn!” - gi dîs lant donge - “ze fasêso culi di biel ?” - “Sôi culi par insegnâi ai umins a no fâ dal mal.... “- “.. Chiste jè par me dal sigùr \" - al pense Pieri. - “....e se ân zà lat dal mal, fâgi fâ pinitinze” - al rispuint chel forèst. - “Si. .. sì.... scusait, savêso, la me curiositât.. . A scugni lâ indenànt par un aiàr....” E Pieri mastïànt ches peraulis al rive tal ciamp. - “Diu, ze ise laju che si mof ?.... Ai ! jè la parone; s'ciampìn, s'ciampitr mai vie!”"],"it":["“Aspetta...voglio capire di che pasta è fatto questo forestiero...” pensò e disse Pietro tra sé e sé.","“Galantuomo!” - gli disse andandogli vicino - “che fate di bello qui?” - “Sono qui per insegnare agli uomini a non fare del male...” - “Questo è venuto per me di sicuro!” pensò Pietro. - “...e se hanno già fatto del male, far fare loro penitenza.” rispose il forestiero.","“Sì...sì...scusate la mia curiosità...non volevo fare ipotesi campate per aria...”","E Pietro, masticando quelle parole, arriva al campo. - “Oddio! Cos'è che si muove là?...Ai! É la padrona! Scappiamo, scappiamo via!”"],"en":["“Wait, I want to see what this stranger is made of,” Peter thinks, and says to himself.","“Good sir!” he says, coming close, “what brings you here?” “I am here to teach men not to do wrong…” “This one has come for me, for sure!” thinks Peter. “…and if they have already done wrong, to make them do penance,” the stranger answers.","“Yes… yes… excuse my curiosity, you know… I must be getting on, I have some business…”","And Peter, chewing over those words, reaches the field. “Lord, what’s that moving over there?… Ah! It’s the mistress! Run, run for it!”"],"note":"The Friulian reads “A scugni lâ indenànt par un aiàr”, most likely “I have to go on about some business” (aiàr, afâr); the 2023 Italian translation has “I didn’t mean to speculate”.","xml":"<div type=\"passage\" xml:id=\"friuli-I-6\" n=\"I.6\">\n            <p>\" Spiète, a vuei provâ di ze savòr che 'l sa chìst furistîr  - âl pense e al dîs fra di sè Pieri. “Giò galantòn!” - gi dîs lant donge - “ze fasêso culi di biel ?” - “Sôi culi par insegnâi ai umins a no fâ dal mal.... “- “.. Chiste jè par me dal sigùr \" - al pense Pieri. - “....e se ân zà lat dal mal, fâgi fâ pinitinze” - al rispuint chel forèst. - “Si. .. sì.... scusait, savêso, la me curiositât.. . A scugni lâ indenànt par un aiàr....” E Pieri mastïànt ches peraulis al rive tal ciamp. - “Diu, ze ise laju che si mof ?.... Ai ! jè la parone; s'ciampìn, s'ciampitr mai vie!”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-6\">\n            <p>“Aspetta...voglio capire di che pasta è fatto questo forestiero...” pensò e disse Pietro tra sé e sé.</p>\n            <p>“Galantuomo!” - gli disse andandogli vicino - “che fate di bello qui?” - “Sono qui per insegnare agli uomini a non fare del male...” - “Questo è venuto per me di sicuro!” pensò Pietro. - “...e se hanno già fatto del male, far fare loro penitenza.” rispose il forestiero.</p>\n            <p>“Sì...sì...scusate la mia curiosità...non volevo fare ipotesi campate per aria...”</p>\n            <p>E Pietro, masticando quelle parole, arriva al campo. - “Oddio! Cos'è che si muove là?...Ai! É la padrona! Scappiamo, scappiamo via!”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-6\">\n            <p>“Wait, I want to see what this stranger is made of,” Peter thinks, and says to himself.</p>\n            <p>“Good sir!” he says, coming close, “what brings you here?” “I am here to teach men not to do wrong…” “This one has come for me, for sure!” thinks Peter. “…and if they have already done wrong, to make them do penance,” the stranger answers.</p>\n            <p>“Yes… yes… excuse my curiosity, you know… I must be getting on, I have some business…”</p>\n            <p>And Peter, chewing over those words, reaches the field. “Lord, what’s that moving over there?… Ah! It’s the mistress! Run, run for it!”</p>\n            <note type=\"translation\">The Friulian reads “A scugni lâ indenànt par un aiàr”, most likely “I have to go on about some business” (aiàr, afâr); the 2023 Italian translation has “I didn’t mean to speculate”.</note>\n          </div>"},{"id":"friuli-I-7","n":"I.7","start":true,"orig":["E cor che ti cor, vie pa plagnis, pai agàrs traviàrs da fuessis e ciarandis e po vie pa strade. E là al ti lu cuche Pieri indaûr chel on di prime, fer sul paraciàr. Ti lu olme e vie lui dret senze voltâsi. Ma ta vuarelis gi sbusinin ches peraulis. “E se àn lat dal mal, fâgi fâ pinitinze.... \"."],"it":["E corri e corri lungo la pianura, per i solchi dei fossi e i cespugli, e poi lungo la strada. E là lo rivede Pietro, l’uomo di prima. Lo guarda e poi va dritto senza voltarsi. Nelle orecchie, però, gli risuonano le parole di prima: “...e se hanno già fatto del male, fargli fare penitenza...”"],"en":["And run and run, over the flat land, across the ditches and hedgerows, and then off down the road. And there Peter spots the man from before, still sitting on the kerbstone. He looks at him and goes straight on without turning round. But those words are buzzing in his ears: “And if they have already done wrong, make them do penance…”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"friuli-I-7\" n=\"I.7\" rend=\"p-start\">\n            <p>E cor che ti cor, vie pa plagnis, pai agàrs traviàrs da fuessis e ciarandis e po vie pa strade. E là al ti lu cuche Pieri indaûr chel on di prime, fer sul paraciàr. Ti lu olme e vie lui dret senze voltâsi. Ma ta vuarelis gi sbusinin ches peraulis. “E se àn lat dal mal, fâgi fâ pinitinze.... \".</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-7\">\n            <p>E corri e corri lungo la pianura, per i solchi dei fossi e i cespugli, e poi lungo la strada. E là lo rivede Pietro, l’uomo di prima. Lo guarda e poi va dritto senza voltarsi. Nelle orecchie, però, gli risuonano le parole di prima: “...e se hanno già fatto del male, fargli fare penitenza...”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-7\">\n            <p>And run and run, over the flat land, across the ditches and hedgerows, and then off down the road. And there Peter spots the man from before, still sitting on the kerbstone. He looks at him and goes straight on without turning round. But those words are buzzing in his ears: “And if they have already done wrong, make them do penance…”</p>\n          </div>"},{"id":"friuli-I-8","n":"I.8","start":false,"orig":["Al ti càpite a ciase, e senze dî nè tre nè quatri al dà di man al mani da scove e.... ju par denànt e par daûr cuais di vueli sant a la so fèmine. - “A ! brute sporce, lari tu vuarevis che doventi! Ah, cìzze dal bambÌrc !” - E jir cuais e pessis come a un bacalå. - “A Diu ! A Diu ! Perdònimi, Pieri; no âi podût cioli nuje; al è vignût fur el paròn e âi scugnût sciampâ vie !.... .” - “E me mi à lat cori la parone !.... A t cizze, canae, no vuei vivi plui cun te. Vuarê che jo doventi un lari !.... Ma par chist peciàt vuei fâ pinitinze, e fâle ance tu che tu 'nd'âs di purgâ.”"],"it":["Arrivato a casa, senza dire ne tre nè quattro prende in mano il manico di scopa e, per dritto e per rovescio, castiga la moglie. - “Ah! Brutta sporca! Ladro volevi che io diventassi! Razza di deficiente!” E continuò a colpirla come con un baccalà. “Oddio! Oddio! Perdonami Pietro; non ho potuto prendere niente; è venuto il padrone e sono dovuta scappare via!...”","-“E a me ha rincorso la padrona! Ah! Canaglia! Non voglio più vivere con te…Volevi diventassi un ladro! Ma di questo peccato ne farò penitenza…e fallo anche tu che ne hai da purgare.”"],"en":["He gets home and, without a word, grabs the broom handle and… front and back, he gives his wife a dose of “holy oil”. “Ah! You filthy wretch, you wanted me to become a thief!” And blows and beatings, as if she were a stockfish. “Oh God! Oh God! Forgive me, Peter; I couldn’t take anything; the master came out and I had to run away!…”","“And the mistress chased me! Ah, you rascal, I don’t want to live with you any more. You wanted me to become a thief!… But for this sin I will do penance, and you do it too, for you have plenty to purge.”"],"note":"“Cuais di vueli sant”, blows of holy oil, is a joking name for a beating.","xml":"<div type=\"passage\" xml:id=\"friuli-I-8\" n=\"I.8\">\n            <p>Al ti càpite a ciase, e senze dî nè tre nè quatri al dà di man al mani da scove e.... ju par denànt e par daûr cuais di vueli sant a la so fèmine. - “A ! brute sporce, lari tu vuarevis che doventi! Ah, cìzze dal bambÌrc !” - E jir cuais e pessis come a un bacalå. - “A Diu ! A Diu ! Perdònimi, Pieri; no âi podût cioli nuje; al è vignût fur el paròn e âi scugnût sciampâ vie !.... .” - “E me mi à lat cori la parone !.... A t cizze, canae, no vuei vivi plui cun te. Vuarê che jo doventi un lari !.... Ma par chist peciàt vuei fâ pinitinze, e fâle ance tu che tu 'nd'âs di purgâ.”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-8\">\n            <p>Arrivato a casa, senza dire ne tre nè quattro prende in mano il manico di scopa e, per dritto e per rovescio, castiga la moglie. - “Ah! Brutta sporca! Ladro volevi che io diventassi! Razza di deficiente!” E continuò a colpirla come con un baccalà. “Oddio! Oddio! Perdonami Pietro; non ho potuto prendere niente; è venuto il padrone e sono dovuta scappare via!...”</p>\n            <p>-“E a me ha rincorso la padrona! Ah! Canaglia! Non voglio più vivere con te…Volevi diventassi un ladro! Ma di questo peccato ne farò penitenza…e fallo anche tu che ne hai da purgare.”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-8\">\n            <p>He gets home and, without a word, grabs the broom handle and… front and back, he gives his wife a dose of “holy oil”. “Ah! You filthy wretch, you wanted me to become a thief!” And blows and beatings, as if she were a stockfish. “Oh God! Oh God! Forgive me, Peter; I couldn’t take anything; the master came out and I had to run away!…”</p>\n            <p>“And the mistress chased me! Ah, you rascal, I don’t want to live with you any more. You wanted me to become a thief!… But for this sin I will do penance, and you do it too, for you have plenty to purge.”</p>\n            <note type=\"translation\">“Cuais di vueli sant”, blows of holy oil, is a joking name for a beating.</note>\n          </div>"},{"id":"friuli-I-9","n":"I.9","start":true,"orig":["E vie lui Pieri di chê bande che'l ja viudût chel galantòn 'sintat e lu ciate in pîs cui voi viars el zîl como che 'l preàs e lu viôt che 'l ti binidîs i ciamps di formènt, che ti fâs cros sui àrbuii e su li plantis e sui uzzilÌtz. Quant che chel on al ti viôt a capitâ 'l puer Pieri gi slarge i braz e Pieri gi conte dut quant. - “ Si, Pieri, tu âs fat ben a vignî cà - gi dls chel on. El Signòr al ja vuartt cussì; tu no tu âs viudtt la parone e nance la to fèmine 'l paròn. Ches dos personis jeris vualtris doi, ma la male cussienze us ja ingianât. Pal to ben ven cun me; tu tu saràs el miö prin amì; el miò bostön, ven cun me; jo sôi el Signör!.... “"],"it":["Se ne va Pietro dalla parte in cui aveva visto il galantuomo seduto e lo trova in piedi, con gli occhi aperti al cielo come se stesse pregando e lo vede benedire i campi di frumento e fare il segno della croce sugli alberi, sulle piante e sugli uccelli. Quando quello vede arrivare il povero Pietro gli allarga le braccia e Pietro gli racconta tutto quanto. - “Sì, Pietro…hai fatto bene a venire qua”.” gli disse. Il Signore ha voluto così. Tu non hai visto la padrona del campo e neanche tua moglie il padrone. Quelle due persone eravate voi due, ma la malafede vi ha ingannati. Per il tuo bene, vieni con me, sarai il mio primo amico, il mio braccio destro, vieni con me, Io sono il Signore…."],"en":["And off goes Peter the way he had seen that gentleman sitting, and he finds him standing, his eyes open to the sky as if he were praying, and sees him bless the fields of wheat and make the sign of the cross over the trees, the plants and the little birds. When the man sees poor Peter coming he opens his arms, and Peter tells him everything. “Yes, Peter, you did well to come here,” the man says. “The Lord willed it so: you did not see the mistress, nor your wife the master. Those two people were the two of you, but a bad conscience deceived you. For your own good, come with me; you will be my first friend, my staff; come with me: I am the Lord!…”"],"note":"“El miò bostön”, my staff; the 2023 Italian translation has “braccio destro”, right hand.","xml":"<div type=\"passage\" xml:id=\"friuli-I-9\" n=\"I.9\" rend=\"p-start\">\n            <p>E vie lui Pieri di chê bande che'l ja viudût chel galantòn 'sintat e lu ciate in pîs cui voi viars el zîl como che 'l preàs e lu viôt che 'l ti binidîs i ciamps di formènt, che  ti fâs cros sui àrbuii e su li plantis e sui uzzilÌtz. Quant che chel on al ti viôt a capitâ 'l puer Pieri gi slarge i braz e Pieri gi conte dut quant. - “ Si, Pieri, tu âs fat ben a vignî cà - gi dls chel on. El Signòr al ja vuartt cussì; tu no tu âs viudtt la parone e nance la to fèmine 'l paròn. Ches dos personis jeris vualtris doi, ma la male cussienze us ja ingianât. Pal to ben ven cun me; tu tu saràs el miö prin amì; el miò bostön, ven cun me; jo sôi el Signör!.... “</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-9\">\n            <p>Se ne va Pietro dalla parte in cui aveva visto il galantuomo seduto e lo trova in piedi, con gli occhi aperti al cielo come se stesse pregando e lo vede benedire i campi di frumento e fare il segno della croce sugli alberi, sulle piante e sugli uccelli. Quando quello vede arrivare il povero Pietro gli allarga le braccia e Pietro gli racconta tutto quanto. - “Sì, Pietro…hai fatto bene a venire qua”.” gli disse. Il Signore ha voluto così. Tu non hai visto la padrona del campo e neanche tua moglie il padrone. Quelle due persone eravate voi due, ma la malafede vi ha ingannati. Per il tuo bene, vieni con me, sarai il mio primo amico, il mio braccio destro, vieni con me, Io sono il Signore….</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#friuli-I-9\">\n            <p>And off goes Peter the way he had seen that gentleman sitting, and he finds him standing, his eyes open to the sky as if he were praying, and sees him bless the fields of wheat and make the sign of the cross over the trees, the plants and the little birds. When the man sees poor Peter coming he opens his arms, and Peter tells him everything. “Yes, Peter, you did well to come here,” the man says. “The Lord willed it so: you did not see the mistress, nor your wife the master. Those two people were the two of you, but a bad conscience deceived you. For your own good, come with me; you will be my first friend, my staff; come with me: I am the Lord!…”</p>\n            <note type=\"translation\">“El miò bostön”, my staff; the 2023 Italian translation has “braccio destro”, right hand.</note>\n          </div>"}],"gap":null,"itResp":"team2023","gulpease":83.0,"words":{"orig":675,"it":565,"en":601}},{"id":"friuli-II","kind":"episode","n":"II","heads":{"orig":"La corodele tradîs San Pieri","it":"La coratella di lepre","en":"The hare’s pluck"},"refs":["mines","cormons"],"record":["Informatore: Giovanni Minèn","Presente nella Raccolta Sot la Nape","pp. 105-110","Luogo di rilevamento: Cormòns","Classificazione ATU: 785 Il cuore dell'agnello"],"passages":[],"gap":{"reason":"copyright","desc":"Dolfo Zorzùt died in 1960: his collection Sot la nape… stays in copyright in Italy until 2031. The record is given; the text is not."},"gulpease":null,"words":{"orig":0,"it":0,"en":0}},{"id":"friuli-III","kind":"episode","n":"III","heads":{"it":"L’ospitalità","en":"Hospitality"},"refs":["taddio","enemonzo"],"record":[],"passages":[],"gap":{"reason":"notTranscribed","desc":"Catalogued from the Società Filologica Friulana record; not transcribed in the edition."},"gulpease":null,"words":{"orig":0,"it":0,"en":0}}],"glossary":[{"forms":["fèmine"],"it":"moglie","en":"wife","src":null},{"forms":["usgnöt"],"it":"stasera, stanotte","en":"tonight","src":null},{"forms":["zirî"],"it":"cercare","en":"to look for","src":null},{"forms":["nuje"],"it":"niente","en":"nothing","src":null},{"forms":["zunìn"],"it":"digiuniamo","en":"we’ll go hungry","src":null},{"forms":["sbordonâ"],"it":"infilzare","en":"to spear","src":null},{"forms":["strussiât"],"it":"faticato, sgobbato","en":"toiled","src":null},{"forms":["sflamiadis"],"it":"vampate","en":"blazing heat","src":null},{"forms":["ciamp"],"it":"campo","en":"field","src":null},{"forms":["lari"],"it":"ladro","en":"thief","src":null},{"forms":["panze"],"it":"pancia","en":"belly","src":null},{"forms":["ciaminànt"],"it":"camminando","en":"walking","src":null},{"forms":["incuintre"],"it":"incontra","en":"meets","src":null},{"forms":["biont"],"it":"biondo","en":"fair-haired","src":null},{"forms":["gris"],"it":"grigi","en":"grey","src":null},{"forms":["agnul"],"it":"angelo","en":"angel","src":null},{"forms":["ciar e vues"],"it":"carne e ossa","en":"flesh and bone","src":null},{"forms":["paraciàr"],"it":"paracarro","en":"kerbstone","src":null},{"forms":["furistîr","forèst"],"it":"forestiero","en":"stranger","src":null},{"forms":["umins"],"it":"uomini","en":"men","src":null},{"forms":["pinitinze"],"it":"penitenza","en":"penance","src":null},{"forms":["parone"],"it":"padrona","en":"mistress (of the land)","src":null},{"forms":["paròn"],"it":"padrone","en":"master (of the land)","src":null},{"forms":["s'ciampìn"],"it":"scappiamo","en":"let’s run","src":null},{"forms":["plagnis"],"it":"pianure","en":"flat land","src":null},{"forms":["fuessis"],"it":"fossi","en":"ditches","src":null},{"forms":["ciase"],"it":"casa","en":"home","src":null},{"forms":["scove"],"it":"scopa","en":"broom","src":null},{"forms":["vueli sant"],"it":"olio santo (qui: botte)","en":"holy oil (here: a beating)","src":null},{"forms":["bacalå"],"it":"baccalà","en":"stockfish","src":null},{"forms":["peciàt"],"it":"peccato","en":"sin","src":null},{"forms":["zîl"],"it":"cielo","en":"sky","src":null},{"forms":["formènt"],"it":"frumento","en":"wheat","src":null},{"forms":["braz"],"it":"braccia","en":"arms","src":null},{"forms":["amì"],"it":"amico","en":"friend","src":null},{"forms":["bostön"],"it":"bastone","en":"staff","src":null},{"forms":["Signôr","Signòr","Signör"],"it":"Signore","en":"Lord","src":null},{"forms":["Pieri"],"it":"Pietro","en":"Peter","src":null}],"gulpease":83.0},"pitre-iii":{"id":"pitre-iii","file":"tei/pitre-iii.xml","title":"San Pietro in Pitrè, vol. III: altre tre fiabe","lang":"scn","dialect":{"en":"Sicilian","it":"siciliano"},"places":[{"id":"borgetto","name":"Borgetto (PA)","wikidata":["https://www.wikidata.org/wiki/Q496869"],"lat":38.05,"lon":13.15},{"id":"palermo","name":"Palermo","wikidata":["https://www.wikidata.org/wiki/Q2656"],"lat":38.1157,"lon":13.3613},{"id":"bagheria","name":"Bagheria (PA)","wikidata":["https://www.wikidata.org/wiki/Q27000"],"lat":38.0833,"lon":13.5}],"persons":[{"id":"salomone","name":"Salvatore Salomone-Marino","role":"collector of n. CXXI","wikidata":"https://www.wikidata.org/wiki/Q21484594"},{"id":"deodato","name":"Francesca Deodato","role":"narrator of n. CXXII (Pitrè’s housekeeper)","wikidata":null},{"id":"messia","name":"Agatuzza Messia","role":"narrator of n. CXXVI","wikidata":null},{"id":"pitre","name":"Giuseppe Pitrè","role":"collector and editor","wikidata":"https://www.wikidata.org/wiki/Q978237"}],"sources":[{"type":"source","text":"Giuseppe Pitrè, Fiabe, novelle e racconti popolari siciliani, vol. III, Palermo, 1875 (Biblioteca delle tradizioni popolari siciliane, vol. VI), nn. CXXI, CXXII and CXXVI, with Pitrè’s notes. Transcribed in 2026 from the page images of the copy digitised by Google (Oxford), Internet Archive.","links":["https://www.wikidata.org/wiki/Q978237","https://archive.org/details/fiabenovelleera01pitrgoog"]}],"heads":{},"editorial":null,"units":[{"id":"pitre-latri","kind":"tale","n":"CXXI","heads":{"orig":"San Petru e li latri","it":"San Pietro e i ladri","en":"St Peter and the thieves"},"refs":["salomone","borgetto"],"record":["Pitrè, vol. III, n. CXXI, pp. 48–49; ATU Jests about Christ and Peter (group) (assigned 2026)."],"passages":[{"id":"pitre-latri-1","n":"CXXI.1","start":true,"orig":["Una vota si cunta e s’arricunta ca a tempi chi lu Maistru caminava cu l’Apostuli, si cci fici notti pri via ’ntra ’na campagna. — « Petru, e comu facemu stasira? » dissi lu Maistru. — « Nenti Maistru; ddà jùsu viju un pagghiaru, e cci sàcciu ’na mànnira; caminati cu mia. »"],"it":["Si racconta e si riracconta che ai tempi in cui il Maestro camminava con gli Apostoli, si fece loro notte per via, in campagna. «Pietro, e come facciamo stasera?» disse il Maestro. «Niente, Maestro; laggiù vedo un pagliaio, e lì conosco una mandria; camminate con me.»"],"en":["They tell and tell again that in the days when the Master walked with the Apostles, night fell on them on their way through the countryside. “Peter, and what shall we do tonight?” said the Master. “Never mind, Master; down there I can see a straw hut, and I know a sheepfold there; walk with me.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"pitre-latri-1\" n=\"CXXI.1\" rend=\"p-start\">\n            <p>Una vota si cunta e s’arricunta ca a tempi chi lu Maistru caminava cu l’Apostuli, si cci fici notti pri via ’ntra ’na campagna. — « Petru, e comu facemu stasira? » dissi lu Maistru. — « Nenti Maistru; ddà jùsu viju un pagghiaru, e cci sàcciu ’na mànnira; caminati cu mia. »</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-latri-1\">\n            <p>Si racconta e si riracconta che ai tempi in cui il Maestro camminava con gli Apostoli, si fece loro notte per via, in campagna. «Pietro, e come facciamo stasera?» disse il Maestro. «Niente, Maestro; laggiù vedo un pagliaio, e lì conosco una mandria; camminate con me.»</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-latri-1\">\n            <p>They tell and tell again that in the days when the Master walked with the Apostles, night fell on them on their way through the countryside. “Peter, and what shall we do tonight?” said the Master. “Never mind, Master; down there I can see a straw hut, and I know a sheepfold there; walk with me.”</p>\n          </div>"},{"id":"pitre-latri-2","n":"CXXI.2","start":false,"orig":["Tirri tirri, unu appressu di l’àutru su’ arrivati a la mànnira: — « Doràzia e Viva Maria; nni putiti dari risettu stanotti, ca semu poviri pillirini stanchi e morti di fami? » — « Doràzia e Viva Maria! » dissiru lu curàtulu e li picurara: e senza mancu smòvisi, cci ’nsignaru lu pagghiaru pri jirisi a curcari; pirchì avìanu la pasta ’ntra lu scanaturi, e dari a manciari a tridici, nun si la sintìanu, pri arristari dijuni iddi. Lu poviru Maistru e l’Apostuli si ficiru torti torti, e si jeru a risittari zittu tu e zittu eu."],"it":["A passi brevi e svelti, uno dietro l’altro arrivarono alla mandria: «Deo gratias e viva Maria; ci potete dare riparo stanotte, che siamo poveri pellegrini stanchi e morti di fame?» «Deo gratias e viva Maria!» dissero il curatolo e i pecorai, e senza nemmeno muoversi indicarono loro il pagliaio per andarsi a coricare: perché avevano la pasta sulla spianatoia, e dar da mangiare a tredici non se la sentivano, per poi restare digiuni loro. Il povero Maestro e gli Apostoli si fecero piccoli piccoli, e andarono a sistemarsi zitto tu e zitto io."],"en":["Pattering along one behind the other, they reached the sheepfold. “Deo gratias and hail Mary; can you give us shelter tonight, for we are poor pilgrims, tired and dying of hunger?” “Deo gratias and hail Mary!” said the head shepherd and the shepherds, and without so much as stirring they pointed them to the straw hut to go to bed; for they had the pasta on the kneading board, and they had no mind to feed thirteen and go hungry themselves. The poor Master and the Apostles made themselves small and went off to settle down, not a word from anyone."],"note":"“Doràzia” is Deo gratias, the greeting of pilgrims at a door.","xml":"<div type=\"passage\" xml:id=\"pitre-latri-2\" n=\"CXXI.2\">\n            <p>Tirri tirri, unu appressu di l’àutru su’ arrivati a la mànnira: — « Doràzia e Viva Maria; nni putiti dari risettu stanotti, ca semu poviri pillirini stanchi e morti di fami? » — « Doràzia e Viva Maria! » dissiru lu curàtulu e li picurara: e senza mancu smòvisi, cci ’nsignaru lu pagghiaru pri jirisi a curcari; pirchì avìanu la pasta ’ntra lu scanaturi, e dari a manciari a tridici, nun si la sintìanu, pri arristari dijuni iddi. Lu poviru Maistru e l’Apostuli si ficiru torti torti, e si jeru a risittari zittu tu e zittu eu.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-latri-2\">\n            <p>A passi brevi e svelti, uno dietro l’altro arrivarono alla mandria: «Deo gratias e viva Maria; ci potete dare riparo stanotte, che siamo poveri pellegrini stanchi e morti di fame?» «Deo gratias e viva Maria!» dissero il curatolo e i pecorai, e senza nemmeno muoversi indicarono loro il pagliaio per andarsi a coricare: perché avevano la pasta sulla spianatoia, e dar da mangiare a tredici non se la sentivano, per poi restare digiuni loro. Il povero Maestro e gli Apostoli si fecero piccoli piccoli, e andarono a sistemarsi zitto tu e zitto io.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-latri-2\">\n            <p>Pattering along one behind the other, they reached the sheepfold. “Deo gratias and hail Mary; can you give us shelter tonight, for we are poor pilgrims, tired and dying of hunger?” “Deo gratias and hail Mary!” said the head shepherd and the shepherds, and without so much as stirring they pointed them to the straw hut to go to bed; for they had the pasta on the kneading board, and they had no mind to feed thirteen and go hungry themselves. The poor Master and the Apostles made themselves small and went off to settle down, not a word from anyone.</p>\n            <note type=\"translation\">“Doràzia” is Deo gratias, the greeting of pilgrims at a door.</note>\n          </div>"},{"id":"pitre-latri-3","n":"CXXI.3","start":false,"orig":["’Ntra stu mentri ’na chidda di latri: — « Atterra atterra, Giorgi! Ca santu di ccà e santu di ddà!... » e timpi-tampi supra li spaddi di lu curàtulu e di li picurara. Chi vulìstivu vidiri! Chiddi, santi pedi, ajutatimi! e si la cugghieru ìllichi-ìllichi. Li latri, dèttiru ’na bona pulizziata a la mànnira, e dipò’ di chistu jeru a lu pagghiaru. — « Altu tutti! cu’ è ddocu? » — « Nui semu, dici San Petru, tridici poviri pillirini stanchi e dijuni, ca chiddi di la mànnira nni trattaru peju di cani, senza mancu diri « Ccà cc’è sèggia. » » — « E mentri è chissu, viniti: la pasta è ancora sana sana, saziàtivi a la facci d’iddi, ca nui ni nni jemu pri nostra via. »"],"it":["In quel mentre, una gran quantità di ladri: «A terra, a terra, Giorgio! Santo di qua e santo di là!...» e botte sulle spalle del curatolo e dei pecorai. Aveste visto! Quelli, piedi santi aiutatemi!, se la diedero a gambe all’istante. I ladri fecero una bella ripulita della mandria, e dopo andarono al pagliaio. «Alto tutti! Chi c’è là?» «Siamo noi, dice San Pietro, tredici poveri pellegrini stanchi e digiuni, che quelli della mandria ci hanno trattato peggio dei cani, senza nemmeno dire “Qui c’è una sedia”.» «E se è così, venite: la pasta è ancora intatta, saziatevi alla faccia loro, che noi ce ne andiamo per la nostra strada.»"],"en":["Just then, a whole band of thieves: “Down, down, Giorgio! Saints of here and saints of there!…” and thump, thump on the backs of the head shepherd and the shepherds. You should have seen it! Those fellows, holy feet, help me!, were off in a flash. The thieves made a clean sweep of the sheepfold, and after that they went to the straw hut. “Everybody up! Who’s in there?” “It’s us,” says St Peter, “thirteen poor pilgrims, tired and hungry, whom the people at the sheepfold treated worse than dogs, without so much as saying ‘Here’s a chair.’” “Well, if that’s how it is, come along: the pasta is still untouched; fill yourselves up to spite them, for we’re going on our way.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"pitre-latri-3\" n=\"CXXI.3\">\n            <p>’Ntra stu mentri ’na chidda di latri: — « Atterra atterra, Giorgi! Ca santu di ccà e santu di ddà!... » e timpi-tampi supra li spaddi di lu curàtulu e di li picurara. Chi vulìstivu vidiri! Chiddi, santi pedi, ajutatimi! e si la cugghieru ìllichi-ìllichi. Li latri, dèttiru ’na bona pulizziata a la mànnira, e dipò’ di chistu jeru a lu pagghiaru. — « Altu tutti! cu’ è ddocu? » — « Nui semu, dici San Petru, tridici poviri pillirini stanchi e dijuni, ca chiddi di la mànnira nni trattaru peju di cani, senza mancu diri « Ccà cc’è sèggia. » » — « E mentri è chissu, viniti: la pasta è ancora sana sana, saziàtivi a la facci d’iddi, ca nui ni nni jemu pri nostra via. »</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-latri-3\">\n            <p>In quel mentre, una gran quantità di ladri: «A terra, a terra, Giorgio! Santo di qua e santo di là!...» e botte sulle spalle del curatolo e dei pecorai. Aveste visto! Quelli, piedi santi aiutatemi!, se la diedero a gambe all’istante. I ladri fecero una bella ripulita della mandria, e dopo andarono al pagliaio. «Alto tutti! Chi c’è là?» «Siamo noi, dice San Pietro, tredici poveri pellegrini stanchi e digiuni, che quelli della mandria ci hanno trattato peggio dei cani, senza nemmeno dire “Qui c’è una sedia”.» «E se è così, venite: la pasta è ancora intatta, saziatevi alla faccia loro, che noi ce ne andiamo per la nostra strada.»</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-latri-3\">\n            <p>Just then, a whole band of thieves: “Down, down, Giorgio! Saints of here and saints of there!…” and thump, thump on the backs of the head shepherd and the shepherds. You should have seen it! Those fellows, holy feet, help me!, were off in a flash. The thieves made a clean sweep of the sheepfold, and after that they went to the straw hut. “Everybody up! Who’s in there?” “It’s us,” says St Peter, “thirteen poor pilgrims, tired and hungry, whom the people at the sheepfold treated worse than dogs, without so much as saying ‘Here’s a chair.’” “Well, if that’s how it is, come along: the pasta is still untouched; fill yourselves up to spite them, for we’re going on our way.”</p>\n          </div>"},{"id":"pitre-latri-4","n":"CXXI.4","start":false,"orig":["Mischini! allupatizzi com’eranu, nun lu vòsiru dittu du’ voti, e si làssanu jiri pri lu scanaturi. — « Biniditti li latri! dici San Petru, ca penzanu a li poviri affamati megghiu di li ricchi. » — « Biniditti li latri! » dissiru l’Apostuli; e accussì s’attiparu li panzi boni boni."],"it":["Poveretti! Affamati come lupi com’erano, non se lo fecero dire due volte, e si buttarono sulla spianatoia. «Benedetti i ladri! dice San Pietro, che pensano ai poveri affamati meglio dei ricchi.» «Benedetti i ladri!» dissero gli Apostoli; e così si riempirono la pancia ben bene."],"en":["Poor things! Ravenous as wolves as they were, they did not need telling twice, and they fell on the kneading board. “Blessed be the thieves!” says St Peter, “who think of the poor and hungry better than the rich do.” “Blessed be the thieves!” said the Apostles; and so they filled their bellies good and full."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pitre-latri-4\" n=\"CXXI.4\">\n            <p>Mischini! allupatizzi com’eranu, nun lu vòsiru dittu du’ voti, e si làssanu jiri pri lu scanaturi. — « Biniditti li latri! dici San Petru, ca penzanu a li poviri affamati megghiu di li ricchi. » — « Biniditti li latri! » dissiru l’Apostuli; e accussì s’attiparu li panzi boni boni.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-latri-4\">\n            <p>Poveretti! Affamati come lupi com’erano, non se lo fecero dire due volte, e si buttarono sulla spianatoia. «Benedetti i ladri! dice San Pietro, che pensano ai poveri affamati meglio dei ricchi.» «Benedetti i ladri!» dissero gli Apostoli; e così si riempirono la pancia ben bene.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-latri-4\">\n            <p>Poor things! Ravenous as wolves as they were, they did not need telling twice, and they fell on the kneading board. “Blessed be the thieves!” says St Peter, “who think of the poor and hungry better than the rich do.” “Blessed be the thieves!” said the Apostles; and so they filled their bellies good and full.</p>\n          </div>"},{"id":"pitre-latri-5","n":"CXXI.5","start":true,"orig":["E ristaru filici e cuntenti, / E nui ccà senza nenti."],"it":["E restarono felici e contenti, / e noi qui senza niente."],"en":["And they lived happy and content, / and here are we with nothing."],"note":"The closing rhyme is the teller’s formula.","xml":"<div type=\"passage\" xml:id=\"pitre-latri-5\" n=\"CXXI.5\" rend=\"p-start\">\n            <p>E ristaru filici e cuntenti, / E nui ccà senza nenti.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-latri-5\">\n            <p>E restarono felici e contenti, / e noi qui senza niente.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-latri-5\">\n            <p>And they lived happy and content, / and here are we with nothing.</p>\n            <note type=\"translation\">The closing rhyme is the teller’s formula.</note>\n          </div>"}],"gap":null,"atu":{"code":"774","label":"Jests about Christ and Peter (group)"},"itResp":"ed2026","gulpease":68.0,"words":{"orig":340,"it":305,"en":349}},{"id":"pitre-tavirnaru","kind":"tale","n":"CXXII","heads":{"orig":"S. Petru e lu tavirnaru","it":"San Pietro e l’oste","en":"St Peter and the innkeeper"},"refs":["deodato","palermo"],"record":["Pitrè, vol. III, n. CXXII, pp. 52–53; ATU Jests about Christ and Peter (group) (assigned 2026)."],"passages":[{"id":"pitre-tavirnaru-1","n":"CXXII.1","start":true,"orig":["’Na vota s’arriccunta ca Gesu Cristu java caminannu cu l’Apostuli soi pi cummèrtiri li genti, e jennu ’nta li citati si firmava e poi sicutava lu sò caminu. A ddi tempi lu vinu si vinnía a varrili, e a l’Apostuli tanticchiedda di sciroppu di Viola cci piacía. Adunca Gesu Cristu urdinau a San Petru di jiri a vinu: e chiddu senza farisillu diri du’ voti cci iju."],"it":["Si racconta che una volta Gesù Cristo andava camminando con i suoi Apostoli per convertire la gente, e passando per le città si fermava e poi proseguiva il suo cammino. A quei tempi il vino si vendeva a barili, e agli Apostoli un pochino di sciroppo di Viola piaceva. Dunque Gesù Cristo ordinò a San Pietro di andare a prendere il vino: e quello, senza farselo dire due volte, ci andò."],"en":["Once, so they tell, Jesus Christ was walking with his Apostles to convert the people, and passing through the towns he would stop and then go on his way. In those days wine was sold by the barrel, and the Apostles were fond of a drop of Viola’s syrup. So Jesus Christ told St Peter to go and fetch wine, and Peter, without needing to be told twice, went."],"note":"“Sciroppu di Viola”: wine, after Viola, a wine merchant in Palermo (Pitrè’s note).","xml":"<div type=\"passage\" xml:id=\"pitre-tavirnaru-1\" n=\"CXXII.1\" rend=\"p-start\">\n            <p>’Na vota s’arriccunta ca Gesu Cristu java caminannu cu l’Apostuli soi pi cummèrtiri li genti, e jennu ’nta li citati si firmava e poi sicutava lu sò caminu. A ddi tempi lu vinu si vinnía a varrili, e a l’Apostuli tanticchiedda di sciroppu di Viola cci piacía. Adunca Gesu Cristu urdinau a San Petru di jiri a vinu: e chiddu senza farisillu diri du’ voti cci iju.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-tavirnaru-1\">\n            <p>Si racconta che una volta Gesù Cristo andava camminando con i suoi Apostoli per convertire la gente, e passando per le città si fermava e poi proseguiva il suo cammino. A quei tempi il vino si vendeva a barili, e agli Apostoli un pochino di sciroppo di Viola piaceva. Dunque Gesù Cristo ordinò a San Pietro di andare a prendere il vino: e quello, senza farselo dire due volte, ci andò.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-tavirnaru-1\">\n            <p>Once, so they tell, Jesus Christ was walking with his Apostles to convert the people, and passing through the towns he would stop and then go on his way. In those days wine was sold by the barrel, and the Apostles were fond of a drop of Viola’s syrup. So Jesus Christ told St Peter to go and fetch wine, and Peter, without needing to be told twice, went.</p>\n            <note type=\"translation\">“Sciroppu di Viola”: wine, after Viola, a wine merchant in Palermo (Pitrè’s note).</note>\n          </div>"},{"id":"pitre-tavirnaru-2","n":"CXXII.2","start":false,"orig":["Li tavirnara sunnu fàusi tutti: e comu l’Apostulu trasíu pi lu vinu, lu tavirnaru si lu misi a’mmusciunari dicènnucci: — « Cumpari Petru, tastati di chistu; viditi com’è; manciativi stu pizzuddu di finocchiu, e accussì vi piaci megghiu. » Pigghiau S. Petru e si manciau lu finocchiu, e poi tastau lu vinu. — « Eh!! di chistu m’aviti a dari, cumpari, ca mi piaci. » Lu tavirnaru, ca nun vulía àutru, spinòccia e cci jinchi lu varrili di ddu vinu."],"it":["Gli osti sono tutti falsi: appena l’Apostolo entrò per il vino, l’oste si mise a raggirarlo dicendogli: «Compare Pietro, assaggiate questo; vedete com’è; mangiatevi questo pezzetto di finocchio, e così vi piace di più.» San Pietro prese e si mangiò il finocchio, e poi assaggiò il vino. «Eh! Di questo mi dovete dare, compare, che mi piace.» L’oste, che non voleva altro, spilla la botte e gli riempie il barile di quel vino."],"en":["Innkeepers are all cheats: as soon as the Apostle came in for the wine, the innkeeper set about taking him in, saying: “Friend Peter, taste this; see what it’s like; eat this little piece of fennel, and you’ll like it better.” St Peter took the fennel and ate it, and then tasted the wine. “Eh! That’s the one you must give me, friend, I like it.” The innkeeper, who wanted nothing better, taps the cask and fills his barrel with that wine."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pitre-tavirnaru-2\" n=\"CXXII.2\">\n            <p>Li tavirnara sunnu fàusi tutti: e comu l’Apostulu trasíu pi lu vinu, lu tavirnaru si lu misi a’mmusciunari dicènnucci: — « Cumpari Petru, tastati di chistu; viditi com’è; manciativi stu pizzuddu di finocchiu, e accussì vi piaci megghiu. » Pigghiau S. Petru e si manciau lu finocchiu, e poi tastau lu vinu. — « Eh!! di chistu m’aviti a dari, cumpari, ca mi piaci. » Lu tavirnaru, ca nun vulía àutru, spinòccia e cci jinchi lu varrili di ddu vinu.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-tavirnaru-2\">\n            <p>Gli osti sono tutti falsi: appena l’Apostolo entrò per il vino, l’oste si mise a raggirarlo dicendogli: «Compare Pietro, assaggiate questo; vedete com’è; mangiatevi questo pezzetto di finocchio, e così vi piace di più.» San Pietro prese e si mangiò il finocchio, e poi assaggiò il vino. «Eh! Di questo mi dovete dare, compare, che mi piace.» L’oste, che non voleva altro, spilla la botte e gli riempie il barile di quel vino.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-tavirnaru-2\">\n            <p>Innkeepers are all cheats: as soon as the Apostle came in for the wine, the innkeeper set about taking him in, saying: “Friend Peter, taste this; see what it’s like; eat this little piece of fennel, and you’ll like it better.” St Peter took the fennel and ate it, and then tasted the wine. “Eh! That’s the one you must give me, friend, I like it.” The innkeeper, who wanted nothing better, taps the cask and fills his barrel with that wine.</p>\n          </div>"},{"id":"pitre-tavirnaru-3","n":"CXXII.3","start":false,"orig":["San Petru si lu carricò ’n coddu, e si nni iju nni lu sò Maistru. Camina camina: — « Chi vinu, Maistru! ’un n’avemu vivutu mai, cu prisunzioni. » Scàrrica, e lu Maistru lu tasta: — « Eh! Petru, Petru! ti facisti ’nfinucchiari. » — « Chi diciti veru, Maistru? vegna ccà quantu lu tastu arreri. » Iju pi tastari, e vitti ca era vinu spuntu ’un avennu cchiù la vucca cu lu finocchiu."],"it":["San Pietro se lo caricò in spalla, e se ne andò dal suo Maestro. Cammina cammina: «Che vino, Maestro! Non ne abbiamo mai bevuto uno così, senza presunzione.» Scarica, e il Maestro lo assaggia: «Eh! Pietro, Pietro! Ti sei fatto infinocchiare.» «Dite davvero, Maestro? Date qua, che lo riassaggio.» Andò ad assaggiarlo, e vide che era vino spunto, non avendo più la bocca col finocchio."],"en":["St Peter hoisted it onto his shoulder and went off to his Master. On and on he walked: “What wine, Master! We’ve never drunk the like, if I may say so.” He sets it down, and the Master tastes it: “Eh! Peter, Peter! You’ve been fennelled.” “Is that true, Master? Let me have another taste.” He went to taste it, and found it was wine turned sour, now that his mouth no longer had the fennel in it."],"note":"’Nfinucchiari (Italian infinocchiare, to take someone in) is literally “to fennel”; the tale explains how the word came about.","xml":"<div type=\"passage\" xml:id=\"pitre-tavirnaru-3\" n=\"CXXII.3\">\n            <p>San Petru si lu carricò ’n coddu, e si nni iju nni lu sò Maistru. Camina camina: — « Chi vinu, Maistru! ’un n’avemu vivutu mai, cu prisunzioni. » Scàrrica, e lu Maistru lu tasta: — « Eh! Petru, Petru! ti facisti ’nfinucchiari. » — « Chi diciti veru, Maistru? vegna ccà quantu lu tastu arreri. » Iju pi tastari, e vitti ca era vinu spuntu ’un avennu cchiù la vucca cu lu finocchiu.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-tavirnaru-3\">\n            <p>San Pietro se lo caricò in spalla, e se ne andò dal suo Maestro. Cammina cammina: «Che vino, Maestro! Non ne abbiamo mai bevuto uno così, senza presunzione.» Scarica, e il Maestro lo assaggia: «Eh! Pietro, Pietro! Ti sei fatto infinocchiare.» «Dite davvero, Maestro? Date qua, che lo riassaggio.» Andò ad assaggiarlo, e vide che era vino spunto, non avendo più la bocca col finocchio.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-tavirnaru-3\">\n            <p>St Peter hoisted it onto his shoulder and went off to his Master. On and on he walked: “What wine, Master! We’ve never drunk the like, if I may say so.” He sets it down, and the Master tastes it: “Eh! Peter, Peter! You’ve been fennelled.” “Is that true, Master? Let me have another taste.” He went to taste it, and found it was wine turned sour, now that his mouth no longer had the fennel in it.</p>\n            <note type=\"translation\">’Nfinucchiari (Italian infinocchiare, to take someone in) is literally “to fennel”; the tale explains how the word came about.</note>\n          </div>"},{"id":"pitre-tavirnaru-4","n":"CXXII.4","start":true,"orig":["E lu Maistru cci mannau a n’àutru Apostulu, pi accussì aviri vinu bonu. E di ddocu nni veni ca quannu s’havi a tastari lu vinu pi vìdiri s’è bonu, nun s’havi a manciari finocchiu."],"it":["E il Maestro ci mandò un altro Apostolo, per avere così vino buono. E da qui viene che quando si deve assaggiare il vino per vedere se è buono, non si deve mangiare finocchio."],"en":["And the Master sent another Apostle, so as to have good wine. And that is why, when you have to taste wine to see whether it is good, you must not eat fennel."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pitre-tavirnaru-4\" n=\"CXXII.4\" rend=\"p-start\">\n            <p>E lu Maistru cci mannau a n’àutru Apostulu, pi accussì aviri vinu bonu. E di ddocu nni veni ca quannu s’havi a tastari lu vinu pi vìdiri s’è bonu, nun s’havi a manciari finocchiu.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-tavirnaru-4\">\n            <p>E il Maestro ci mandò un altro Apostolo, per avere così vino buono. E da qui viene che quando si deve assaggiare il vino per vedere se è buono, non si deve mangiare finocchio.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-tavirnaru-4\">\n            <p>And the Master sent another Apostle, so as to have good wine. And that is why, when you have to taste wine to see whether it is good, you must not eat fennel.</p>\n          </div>"}],"gap":null,"atu":{"code":"774","label":"Jests about Christ and Peter (group)"},"itResp":"ed2026","gulpease":68.5,"words":{"orig":255,"it":243,"en":262}},{"id":"pitre-porru","kind":"tale","n":"CXXVI","heads":{"orig":"Lu porru di S. Petru","it":"Il porro di San Pietro","en":"St Peter’s leek"},"refs":["messia","palermo"],"record":["Pitrè, vol. III, n. CXXVI, pp. 65–66; ATU Peter’s Mother Falls from Heaven (assigned 2026)."],"passages":[{"id":"pitre-porru-1","n":"CXXVI.1","start":true,"orig":["S’arriccunta ca la Mamma di S. Petru era avara abbramata, ’un facía limosina mai, ’un dava mai un granu. Ora ’na jurnata stava munnannu li porri; ’ncugna ’na puviredda: — « Mi la fa la caritati, divuledda! » — « Tutti ccà hannu a vèniri!... — Pigghiàti ccà! » e cci detti ’na sfogghia di porru."],"it":["Si racconta che la mamma di San Pietro era avara e avida, non faceva mai l’elemosina, non dava mai un soldo. Ora un giorno stava mondando i porri; si avvicina una poveretta: «Mi fate la carità, devota!» «Tutte qua devono venire!... Pigliate qua!» e le diede una foglia di porro."],"en":["They tell that St Peter’s mother was a greedy miser: she never gave alms, never gave away a penny. Now one day she was trimming leeks; a poor woman comes up: “Give me charity, good soul!” “They all have to come here!… Here, take this!” and she gave her a leek leaf."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pitre-porru-1\" n=\"CXXVI.1\" rend=\"p-start\">\n            <p>S’arriccunta ca la Mamma di S. Petru era avara abbramata, ’un facía limosina mai, ’un dava mai un granu. Ora ’na jurnata stava munnannu li porri; ’ncugna ’na puviredda: — « Mi la fa la caritati, divuledda! » — « Tutti ccà hannu a vèniri!... — Pigghiàti ccà! » e cci detti ’na sfogghia di porru.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-porru-1\">\n            <p>Si racconta che la mamma di San Pietro era avara e avida, non faceva mai l’elemosina, non dava mai un soldo. Ora un giorno stava mondando i porri; si avvicina una poveretta: «Mi fate la carità, devota!» «Tutte qua devono venire!... Pigliate qua!» e le diede una foglia di porro.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-porru-1\">\n            <p>They tell that St Peter’s mother was a greedy miser: she never gave alms, never gave away a penny. Now one day she was trimming leeks; a poor woman comes up: “Give me charity, good soul!” “They all have to come here!… Here, take this!” and she gave her a leek leaf.</p>\n          </div>"},{"id":"pitre-porru-2","n":"CXXVI.2","start":true,"orig":["Lu Signuri si la chiamò all’âtra vita, e la mannò a lu ’Nfernu. San Petru era capu di lu Paraddisu; ’na jurnata era davanti la porta; quantu senti ’na vuci: — « Ah! Petru figghiu mio! e vidi comu m’arrustu! E va nni lu Maistru, e pàrracci pi fàrimi nèsciri di sti guai! » San Petru va nni lu Signuri e cci dici: — « Maistru, haju a mè matri ca è ’nta lu ’Nfernu e voli grazia pi nèsciri. » Si vôta lu Signuri: — « Te’! tò matri ’un fici mai un ugnu di beni; tuttu lu sò piattu di forti è ’na sfogghia di porru chi detti a ’na puviredda. — La fai affirrari ccà a sta sfogghia (e cci pruìju ’na sfogghia di porru), e ti la porti ’n Paraddisu. »"],"it":["Il Signore la chiamò all’altra vita, e la mandò all’Inferno. San Pietro era a capo del Paradiso; un giorno stava davanti alla porta, quand’ecco sente una voce: «Ah! Pietro, figlio mio! Vedi come brucio! Va’ dal Maestro, e parlagli per farmi uscire da questi guai!» San Pietro va dal Signore e gli dice: «Maestro, mia madre è all’Inferno e chiede la grazia di uscirne.» Si volta il Signore: «Ecco: tua madre non ha mai fatto un briciolo di bene; tutto il bene che ha fatto è una foglia di porro che diede a una poveretta. Falla aggrappare qui, a questa foglia (e gli porse una foglia di porro), e portatela in Paradiso.»"],"en":["The Lord called her to the other life and sent her to Hell. St Peter was the head of Paradise; one day he was at the gate when he hears a voice: “Ah! Peter, my son! See how I’m roasting! Go to the Master and speak to him, to get me out of this misery!” St Peter goes to the Lord and says to him: “Master, my mother is in Hell and asks for grace to get out.” The Lord turns: “Look: your mother never did a scrap of good; all the good she ever did is a leek leaf she gave to a poor woman. Have her hold on to this leaf (and he held out a leek leaf), and take her to Paradise.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"pitre-porru-2\" n=\"CXXVI.2\" rend=\"p-start\">\n            <p>Lu Signuri si la chiamò all’âtra vita, e la mannò a lu ’Nfernu. San Petru era capu di lu Paraddisu; ’na jurnata era davanti la porta; quantu senti ’na vuci: — « Ah! Petru figghiu mio! e vidi comu m’arrustu! E va nni lu Maistru, e pàrracci pi fàrimi nèsciri di sti guai! » San Petru va nni lu Signuri e cci dici: — « Maistru, haju a mè matri ca è ’nta lu ’Nfernu e voli grazia pi nèsciri. » Si vôta lu Signuri: — « Te’! tò matri ’un fici mai un ugnu di beni; tuttu lu sò piattu di forti è ’na sfogghia di porru chi detti a ’na puviredda. — La fai affirrari ccà a sta sfogghia (e cci pruìju ’na sfogghia di porru), e ti la porti ’n Paraddisu. »</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-porru-2\">\n            <p>Il Signore la chiamò all’altra vita, e la mandò all’Inferno. San Pietro era a capo del Paradiso; un giorno stava davanti alla porta, quand’ecco sente una voce: «Ah! Pietro, figlio mio! Vedi come brucio! Va’ dal Maestro, e parlagli per farmi uscire da questi guai!» San Pietro va dal Signore e gli dice: «Maestro, mia madre è all’Inferno e chiede la grazia di uscirne.» Si volta il Signore: «Ecco: tua madre non ha mai fatto un briciolo di bene; tutto il bene che ha fatto è una foglia di porro che diede a una poveretta. Falla aggrappare qui, a questa foglia (e gli porse una foglia di porro), e portatela in Paradiso.»</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-porru-2\">\n            <p>The Lord called her to the other life and sent her to Hell. St Peter was the head of Paradise; one day he was at the gate when he hears a voice: “Ah! Peter, my son! See how I’m roasting! Go to the Master and speak to him, to get me out of this misery!” St Peter goes to the Lord and says to him: “Master, my mother is in Hell and asks for grace to get out.” The Lord turns: “Look: your mother never did a scrap of good; all the good she ever did is a leek leaf she gave to a poor woman. Have her hold on to this leaf (and he held out a leek leaf), and take her to Paradise.”</p>\n          </div>"},{"id":"pitre-porru-3","n":"CXXVI.3","start":true,"orig":["Calò un Ancilu cu dda sfogghia: — « Affirràtivi ccà! » La Matri di S. Petru si cci affirrò. A lu nèsciri di lu ’Nfernu tutti l’armuzzi ch’eranu cu idda si cci affirraru a la pudía di la vesta. Chi nn’avía a fari idda? tantu pirtantu l’Ancilu si li tirava a tutti. Mai! l’abbramata e chi era cci metti a dari caùci, e a scutulàrisi la vesta pi falli càdiri. Comu fa accussì, si rumpi la sfogghia di lu porru e iju cchiù a lu funnu di lu ’Nfernu."],"it":["Scese un Angelo con quella foglia: «Aggrappatevi qui!» La madre di San Pietro vi si aggrappò. Mentre usciva dall’Inferno, tutte le animucce che erano con lei si aggrapparono all’orlo della sua veste. Che ci poteva fare lei? Nonostante tutto, l’Angelo le tirava su tutte. Macché! L’avara, quella che era, si mette a dare calci e a scuotersi la veste per farle cadere. Come fa così, si rompe la foglia di porro, e lei andò più in fondo all’Inferno."],"en":["An Angel came down with that leaf: “Hold on here!” St Peter’s mother held on to it. As she came out of Hell, all the little souls who were with her caught hold of the hem of her dress. What could she do about it? Even so, the Angel was pulling them all up. Not a bit of it! The miser, being what she was, starts kicking out and shaking her dress to make them fall. As she does so, the leek leaf breaks, and down she went to the very bottom of Hell."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pitre-porru-3\" n=\"CXXVI.3\" rend=\"p-start\">\n            <p>Calò un Ancilu cu dda sfogghia: — « Affirràtivi ccà! » La Matri di S. Petru si cci affirrò. A lu nèsciri di lu ’Nfernu tutti l’armuzzi ch’eranu cu idda si cci affirraru a la pudía di la vesta. Chi nn’avía a fari idda? tantu pirtantu l’Ancilu si li tirava a tutti. Mai! l’abbramata e chi era cci metti a dari caùci, e a scutulàrisi la vesta pi falli càdiri. Comu fa accussì, si rumpi la sfogghia di lu porru e iju cchiù a lu funnu di lu ’Nfernu.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-porru-3\">\n            <p>Scese un Angelo con quella foglia: «Aggrappatevi qui!» La madre di San Pietro vi si aggrappò. Mentre usciva dall’Inferno, tutte le animucce che erano con lei si aggrapparono all’orlo della sua veste. Che ci poteva fare lei? Nonostante tutto, l’Angelo le tirava su tutte. Macché! L’avara, quella che era, si mette a dare calci e a scuotersi la veste per farle cadere. Come fa così, si rompe la foglia di porro, e lei andò più in fondo all’Inferno.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-porru-3\">\n            <p>An Angel came down with that leaf: “Hold on here!” St Peter’s mother held on to it. As she came out of Hell, all the little souls who were with her caught hold of the hem of her dress. What could she do about it? Even so, the Angel was pulling them all up. Not a bit of it! The miser, being what she was, starts kicking out and shaking her dress to make them fall. As she does so, the leek leaf breaks, and down she went to the very bottom of Hell.</p>\n          </div>"},{"id":"pitre-porru-4","n":"CXXVI.4","start":true,"orig":["E chistu è lu cuntu di la Mamma di S. Petru."],"it":["E questo è il racconto della mamma di San Pietro."],"en":["And this is the tale of St Peter’s mother."],"note":null,"xml":"<div type=\"passage\" xml:id=\"pitre-porru-4\" n=\"CXXVI.4\" rend=\"p-start\">\n            <p>E chistu è lu cuntu di la Mamma di S. Petru.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-porru-4\">\n            <p>E questo è il racconto della mamma di San Pietro.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#pitre-porru-4\">\n            <p>And this is the tale of St Peter’s mother.</p>\n          </div>"}],"gap":null,"atu":{"code":"804","label":"Peter’s Mother Falls from Heaven"},"itResp":"ed2026","gulpease":72.6,"words":{"orig":291,"it":250,"en":280}},{"id":"pitre-porru-v","kind":"variant","n":null,"heads":{"orig":"La Mamma di S. Petru","it":"La mamma di San Pietro","en":"St Peter’s mother"},"refs":["bagheria"],"record":[],"passages":[{"id":"pitre-porru-v-1","n":"CXXVI var..1","start":true,"orig":["Quannu la Mamma di S. Petru era ’nta lu Prïatoriu, cu li prijeri di sò figghiu nisciu pi jiri nna lu Paradisu. L’armi santi di lu Prïatoriu si cci affirravanu a li pudii di la vesta pi jirisìnni, a sènziu sò, cu idda. Idda misi a dari càuci e a trantuliàrisi tutta pi scutularisilli: — « Sciù! vativìnni! avissivu’ fattu figghi santi comu mia! » Lu Signuri vitti chistu e la fici jiri cchiù a funnu. E la Mamma di San Petru arristau pi muttu, e si dici: Comu la Mamma di San Petru."],"it":["Quando la mamma di San Pietro era in Purgatorio, per le preghiere di suo figlio ne uscì per andare in Paradiso. Le anime sante del Purgatorio le si aggrappavano all’orlo della veste per andarsene anche loro con lei. Lei si mise a dare calci e a scuotersi tutta per scrollarsele di dosso: «Sciò! Andatevene! Aveste fatto figli santi come me!» Il Signore vide questo e la fece andare più in fondo. E la mamma di San Pietro è rimasta in proverbio, e si dice: Come la mamma di San Pietro."],"en":["When St Peter’s mother was in Purgatory, through her son’s prayers she came out to go to Paradise. The holy souls of Purgatory caught hold of the hem of her dress to go along with her. She began kicking and shaking herself all over to shake them off: “Shoo! Get away! You should have had saintly sons like me!” The Lord saw this and sent her further down. And St Peter’s mother has stayed in a saying: “Like St Peter’s mother.”"],"note":"“A sènziu sò” is left out of both translations: its sense here is uncertain.","xml":"<div type=\"passage\" xml:id=\"pitre-porru-v-1\" n=\"CXXVI var..1\" rend=\"p-start\">\n              <p>Quannu la Mamma di S. Petru era ’nta lu Prïatoriu, cu li prijeri di sò figghiu nisciu pi jiri nna lu Paradisu. L’armi santi di lu Prïatoriu si cci affirravanu a li pudii di la vesta pi jirisìnni, a sènziu sò, cu idda. Idda misi a dari càuci e a trantuliàrisi tutta pi scutularisilli: — « Sciù! vativìnni! avissivu’ fattu figghi santi comu mia! » Lu Signuri vitti chistu e la fici jiri cchiù a funnu. E la Mamma di San Petru arristau pi muttu, e si dici: Comu la Mamma di San Petru.</p>\n            </div>\n\n<div type=\"passage\" corresp=\"#pitre-porru-v-1\">\n              <p>Quando la mamma di San Pietro era in Purgatorio, per le preghiere di suo figlio ne uscì per andare in Paradiso. Le anime sante del Purgatorio le si aggrappavano all’orlo della veste per andarsene anche loro con lei. Lei si mise a dare calci e a scuotersi tutta per scrollarsele di dosso: «Sciò! Andatevene! Aveste fatto figli santi come me!» Il Signore vide questo e la fece andare più in fondo. E la mamma di San Pietro è rimasta in proverbio, e si dice: Come la mamma di San Pietro.</p>\n            </div>\n\n<div type=\"passage\" corresp=\"#pitre-porru-v-1\">\n              <p>When St Peter’s mother was in Purgatory, through her son’s prayers she came out to go to Paradise. The holy souls of Purgatory caught hold of the hem of her dress to go along with her. She began kicking and shaking herself all over to shake them off: “Shoo! Get away! You should have had saintly sons like me!” The Lord saw this and sent her further down. And St Peter’s mother has stayed in a saying: “Like St Peter’s mother.”</p>\n              <note type=\"translation\">“A sènziu sò” is left out of both translations: its sense here is uncertain.</note>\n            </div>"}],"gap":null,"itResp":"ed2026","parent":"pitre-porru","gulpease":70.0,"words":{"orig":94,"it":90,"en":81}}],"glossary":[{"forms":["tirri tirri"],"it":"camminare frettoloso e a passi brevi","en":"hurrying along with short steps","src":"Pitrè, n. CXXI"},{"forms":["curàtulu"],"it":"il capo della mandra, che ha cura di far i caci e le ricotte","en":"the head shepherd, who makes the cheese and ricotta","src":"Pitrè, n. CXXI"},{"forms":["scanaturi"],"it":"tavola da spianare la pasta","en":"kneading board","src":"Pitrè, n. CXXI"},{"forms":["'na chidda"],"it":"una gran quantità","en":"a great many","src":"Pitrè, n. CXXI"},{"forms":["Atterra atterra, Giorgi"],"it":"il grido abituale di chi ruba; i ladri si chiamano scambievolmente Giorgio","en":"the thieves’ usual cry; thieves call each other, and their victims, Giorgio","src":"Pitrè, n. CXXI"},{"forms":["santu di ccà e santu di ddà"],"it":"la più fiera bestemmia de’ Siciliani","en":"the fiercest Sicilian oath","src":"Pitrè, n. CXXI"},{"forms":["timpi-tampi"],"it":"suono imitativo delle busse","en":"the sound of blows","src":"Pitrè, n. CXXI"},{"forms":["ìllichi-ìllichi"],"it":"subitamente (l’illico de’ Latini)","en":"at once (Latin illico)","src":"Pitrè, n. CXXI"},{"forms":["si la cugghieru"],"it":"fuggirono","en":"they ran off","src":"Pitrè, n. CXXI"},{"forms":["pulizziata"],"it":"una bella ripulita: rubarono di netto tutto quello che c’era","en":"a clean sweep: they took everything there was","src":"Pitrè, n. CXXI"},{"forms":["allupatizzi"],"it":"affamati come lupi","en":"ravenous as wolves","src":"Pitrè, n. CXXI"},{"forms":["s'attiparu li panzi"],"it":"si riempirono zeppe le pance","en":"they stuffed their bellies","src":"Pitrè, n. CXXI"},{"forms":["Viola"],"it":"nome di un negoziante di vino, presso S. Niccolò Tolentino in Palermo","en":"a wine merchant near San Nicolò da Tolentino in Palermo","src":"Pitrè, n. CXXII"},{"forms":["a'mmusciunari","ammusciunari"],"it":"corbellare, cogliere in inganno negoziando","en":"to take someone in while striking a bargain","src":"Pitrè, n. CXXII"},{"forms":["spinòccia"],"it":"spillare (le botti, i barili)","en":"to tap (a cask)","src":"Pitrè, n. CXXII"},{"forms":["'nfinucchiari"],"it":"infinocchiare, ingannare","en":"to fennel, to fool","src":"Pitrè, n. CXXII"},{"forms":["spuntu"],"it":"spunto, infortito","en":"turned sour","src":"Pitrè, n. CXXII"},{"forms":["abbramata"],"it":"avara avida, quasi famelica","en":"greedy, almost ravenous","src":"Pitrè, n. CXXVI"},{"forms":["piattu di forti"],"it":"tutto quanto di buono avesse ella fatto","en":"all the good she had ever done","src":"Pitrè, n. CXXVI"},{"forms":["pudía","pudii"],"it":"la pedana, l’orlo della veste","en":"the hem of the dress","src":"Pitrè, n. CXXVI"},{"forms":["porru","porri"],"it":"porro","en":"leek","src":null},{"forms":["sfogghia"],"it":"foglia","en":"leaf","src":null},{"forms":["'Nfernu"],"it":"Inferno","en":"Hell","src":null},{"forms":["Paraddisu","Paradisu"],"it":"Paradiso","en":"Paradise","src":null},{"forms":["Ancilu"],"it":"Angelo","en":"Angel","src":null},{"forms":["armuzzi"],"it":"animucce, anime","en":"little souls","src":null},{"forms":["tavirnaru"],"it":"oste","en":"innkeeper","src":null},{"forms":["varrili"],"it":"barile","en":"barrel","src":null},{"forms":["finocchiu"],"it":"finocchio","en":"fennel","src":null},{"forms":["mànnira"],"it":"mandria, ovile","en":"sheepfold","src":null},{"forms":["pagghiaru"],"it":"pagliaio","en":"straw hut","src":null},{"forms":["picurara"],"it":"pecorai","en":"shepherds","src":null},{"forms":["latri"],"it":"ladri","en":"thieves","src":null},{"forms":["pillirini"],"it":"pellegrini","en":"pilgrims","src":null},{"forms":["dijuni"],"it":"digiuni","en":"hungry, fasting","src":null},{"forms":["Prïatoriu"],"it":"Purgatorio","en":"Purgatory","src":null},{"forms":["Maistru"],"it":"Maestro","en":"Master","src":null},{"forms":["tridici"],"it":"tredici","en":"thirteen","src":null},{"forms":["paisi"],"it":"paese","en":"village","src":null},{"forms":["pani"],"it":"pane","en":"bread","src":null},{"forms":["petra","petri"],"it":"pietra, pietre","en":"stone(s)","src":null},{"forms":["nica"],"it":"piccola","en":"small","src":null},{"forms":["lèggiu"],"it":"leggero","en":"light","src":null},{"forms":["accattamu"],"it":"compriamo","en":"we buy","src":null},{"forms":["binidizioni"],"it":"benedizione","en":"blessing","src":null},{"forms":["pitrudda"],"it":"sassolino","en":"pebble","src":null},{"forms":["manciu"],"it":"mangio","en":"I eat","src":null},{"forms":["gravusi"],"it":"carichi","en":"heavy-laden","src":null},{"forms":["mariuolu"],"it":"furbo, birbante","en":"rascal","src":null},{"forms":["picciotti"],"it":"ragazzi","en":"lads","src":null},{"forms":["tanticchia"],"it":"un pochino","en":"a little","src":null},{"forms":["balatuni"],"it":"lastrone","en":"great slab","src":null},{"forms":["currivatu"],"it":"indispettito","en":"vexed","src":null},{"forms":["vicchiaja"],"it":"vecchiaia","en":"old age","src":null},{"forms":["furnu"],"it":"forno","en":"oven","src":null},{"forms":["picciriddu"],"it":"bambino","en":"little child","src":null},{"forms":["matri"],"it":"madre","en":"mother","src":null},{"forms":["carvuni"],"it":"carbone","en":"charcoal","src":null},{"forms":["tignusu"],"it":"tignoso, pelato","en":"scabby-head","src":null},{"forms":["vicchiaredda"],"it":"vecchietta","en":"little old woman","src":null},{"forms":["giuvina"],"it":"giovane","en":"young woman","src":null},{"forms":["chiovu"],"it":"chiodo","en":"nail","src":null}],"gulpease":69.7},"sicily":{"id":"sicily","file":"tei/sicily.xml","title":"Gesù e San Pietro in Sicilia","lang":"scn","dialect":{"en":"Sicilian","it":"siciliano"},"places":[{"id":"bagheria","name":"Bagheria (PA)","wikidata":["https://www.wikidata.org/wiki/Q27000"],"lat":38.0833,"lon":13.5}],"persons":[{"id":"gargano","name":"Gargano","role":"narrator (“un certo Gargano”, Pitrè)","wikidata":null},{"id":"pitre","name":"Giuseppe Pitrè","role":"collector","wikidata":"https://www.wikidata.org/wiki/Q978237"}],"sources":[{"type":"source","text":"Giuseppe Pitrè, Fiabe, novelle e racconti popolari siciliani, 4 voll., Palermo, 1875 (Biblioteca delle tradizioni popolari siciliane, voll. IV–VII), vol. III, n. CXXIII, from 54.","links":["https://www.wikidata.org/wiki/Q978237"]},{"type":"retelling","text":"Italo Calvino, Fiabe italiane, Torino, Einaudi, 1956: “Gesù e San Pietro in Sicilia”.","links":["https://www.wikidata.org/wiki/Q154756","https://www.wikidata.org/wiki/Q3744324"]}],"heads":{"orig":"Lu Signuri, S. Petru e li Apostuli.","it":"Il Signore, S. Pietro e gli Apostoli.","en":"The Lord, St Peter and the Apostles"},"editorial":null,"units":[{"id":"sicily-I","kind":"episode","n":"I","heads":{"it":"Storia I","en":"Story I: the stones and the bread"},"refs":["gargano","bagheria"],"record":[],"passages":[{"id":"sicily-I-1","n":"I.1","start":true,"orig":["Quannau lu Maistru java caminannu cu li tridici Apostuli, junceru tutti ’nt’ôn paisi, e pani 'un cci nn’era. Cci dissi lu Maistru: — « Petru, carricàtivi 'na petra l’unu. » Si carricàru 'na petra l'unu, e S. Petru si nni carricau una nica nica. Tutti javanu carricati, e S. Petru java beddu lèggiu. Dici lu Maistru: — «Ora jamu 'nta n'âtru paisi; si ddà pani cci nn'è, l'accattamu; s’un cci nn'è vi fazzu la binidizioni, e li petri v'addiventanu pani. »"],"it":["Mentre il Maestro camminava con i tredici Apostoli, giunsero tutti in un paese, e pane non ce n’era. Disse loro il Maestro – “Pietro, caricatevi una pietra l’uno.” Si caricarono una pietra l’uno, e S. Pietro se ne caricò una piccola piccola. Tutti proseguivano carichi, e S. Pietro andava leggero. Dice il Maestro – “Andiamo ora in un altro paese; se lì c’è del pane, lo compriamo; se non c’è, vi faccio la benedizione, e le pietre si tramutano in pane.”"],"en":["While the Master was walking with the thirteen Apostles, they all came to a village, and there was no bread. The Master said to them: “Peter, each of you pick up a stone.” Each of them picked up a stone, and St Peter picked up a tiny little one. They all walked on laden, and St Peter walked along nice and light. The Master says: “Now let’s go to another village; if there’s bread there, we’ll buy it; if there isn’t, I’ll give you the blessing, and the stones will turn into bread.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"sicily-I-1\" n=\"I.1\" rend=\"p-start\">\n            <p>Quannau lu Maistru java caminannu cu li tridici Apostuli, junceru tutti ’nt’ôn paisi, e pani 'un cci nn’era. Cci dissi lu Maistru: — « Petru, carricàtivi 'na petra l’unu. » Si carricàru 'na petra l'unu, e S. Petru si nni carricau una nica nica. Tutti javanu carricati, e S. Petru java beddu lèggiu. Dici lu Maistru: — «Ora jamu 'nta n'âtru paisi; si ddà pani cci nn'è, l'accattamu; s’un cci nn'è vi fazzu la binidizioni, e li petri v'addiventanu pani. »</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-I-1\">\n            <p>Mentre il Maestro camminava con i tredici Apostoli, giunsero tutti in un paese, e pane non ce n’era. Disse loro il Maestro – “Pietro, caricatevi una pietra l’uno.” Si caricarono una pietra l’uno, e S. Pietro se ne caricò una piccola piccola. Tutti proseguivano carichi, e S. Pietro andava leggero. Dice il Maestro – “Andiamo ora in un altro paese; se lì c’è del pane, lo compriamo; se non c’è, vi faccio la benedizione, e le pietre si tramutano in pane.”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-I-1\">\n            <p>While the Master was walking with the thirteen Apostles, they all came to a village, and there was no bread. The Master said to them: “Peter, each of you pick up a stone.” Each of them picked up a stone, and St Peter picked up a tiny little one. They all walked on laden, and St Peter walked along nice and light. The Master says: “Now let’s go to another village; if there’s bread there, we’ll buy it; if there isn’t, I’ll give you the blessing, and the stones will turn into bread.”</p>\n          </div>"},{"id":"sicily-I-2","n":"I.2","start":false,"orig":["Jeru ‘nta n'âutru paisi; pusaru tutti li petri ’nt ôn chianiolu, e s'arripusaru. Lu Maistru cci fìci a tutti la binidizioni, e li petri addivintaru pani. San Petru, ca s'avia purtatu ’na pitrudda, cci scunchiu l’arma !— «Maistru, dici, e io comu manciu? » — « Eh ! frati mio ! Tu pirchì ti purtasti ’na pitrudda ? L'àutrì ca jeru gravusi, àppiru pani assai. >"],"it":["Andarono in un altro paese; posarono tutte le pietre in un pianoro, e si riposarono. Il Maestro fece a tutti la benedizione, e le pietre divennero pani. San Pietro, che si era portato un sassolino, si sentì venir meno! – “Maestro, dice, e io come mangio?” – “Eh! Fratello mio! Tu perché ti sei portato un sassolino? Gli altri che si spostavano con un peso, hanno ricevuto molto pane.”"],"en":["They went to another village; they set all the stones down on a patch of flat ground and rested. The Master gave them all the blessing, and the stones became loaves. St Peter, who had brought a pebble, felt his heart sink. “Master,” he says, “and what am I to eat?” “Eh! My brother! Why did you bring a pebble? The others, who went heavy-laden, got plenty of bread.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"sicily-I-2\" n=\"I.2\">\n            <p>Jeru ‘nta n'âutru paisi; pusaru tutti li petri ’nt ôn chianiolu, e s'arripusaru. Lu Maistru cci fìci a tutti la binidizioni, e li petri addivintaru pani. San Petru, ca s'avia purtatu ’na pitrudda, cci scunchiu l’arma !—  «Maistru, dici, e io comu manciu? » — « Eh ! frati mio ! Tu pirchì ti purtasti ’na pitrudda ? L'àutrì ca jeru gravusi, àppiru pani assai. &gt;</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-I-2\">\n            <p>Andarono in un altro paese; posarono tutte le pietre in un pianoro, e si riposarono. Il Maestro fece a tutti la benedizione, e le pietre divennero pani. San Pietro, che si era portato un sassolino, si sentì venir meno! – “Maestro, dice, e io come mangio?” – “Eh! Fratello mio! Tu perché ti sei portato un sassolino? Gli altri che si spostavano con un peso, hanno ricevuto molto pane.”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-I-2\">\n            <p>They went to another village; they set all the stones down on a patch of flat ground and rested. The Master gave them all the blessing, and the stones became loaves. St Peter, who had brought a pebble, felt his heart sink. “Master,” he says, “and what am I to eat?” “Eh! My brother! Why did you bring a pebble? The others, who went heavy-laden, got plenty of bread.”</p>\n          </div>"},{"id":"sicily-I-3","n":"I.3","start":false,"orig":["Jeru cchiù a jiri ddà: e lu Maistru cci fici carricari 'n'àutra petra l’unu. Pigghiò S. Petru, mariuolu, e si nni carricò una grossa assai; e tutti l’àutri si nni pigghiaru una nica. Lu Signuri si vutò cu l’Apostuli: — « Picciotti, ora ridemu tanticchia cu Petru.»"],"it":["Si spostarono ancora: e il Maestro fece caricare loro un’altra pietra ciascuno. San Pietro, furfante, allora se ne caricò una molto grande; e tutti gli altri ne presero una piccola. Il Signore disse agli Apostoli – “Ragazzi, ora ridiamo un po’ con Pietro.”"],"en":["They moved on again, and the Master had them each pick up another stone. St Peter, the rascal, took a very big one this time, and all the others took small ones. The Lord turned to the Apostles: “Lads, now let’s have a little laugh with Peter.”"],"note":null,"xml":"<div type=\"passage\" xml:id=\"sicily-I-3\" n=\"I.3\">\n            <p>Jeru cchiù a jiri ddà: e lu Maistru cci fici carricari 'n'àutra petra l’unu. Pigghiò S. Petru, mariuolu, e si nni carricò una grossa assai; e tutti l’àutri si nni pigghiaru una nica. Lu Signuri si vutò cu l’Apostuli: — « Picciotti, ora ridemu tanticchia cu Petru.»</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-I-3\">\n            <p>Si spostarono ancora: e il Maestro fece caricare loro un’altra pietra ciascuno. San Pietro, furfante, allora se ne caricò una molto grande; e tutti gli altri ne presero una piccola. Il Signore disse agli Apostoli – “Ragazzi, ora ridiamo un po’ con Pietro.”</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-I-3\">\n            <p>They moved on again, and the Master had them each pick up another stone. St Peter, the rascal, took a very big one this time, and all the others took small ones. The Lord turned to the Apostles: “Lads, now let’s have a little laugh with Peter.”</p>\n          </div>"},{"id":"sicily-I-4","n":"I.4","start":false,"orig":["Junceru ’nt'ôn paisi, e tutti l’Apostuli jittaru la petra pirchì cc'era lu pani; e S. Petru arristò currivatu ca avía purtatu un balatuni senza nuddu piaciri."],"it":["Giunsero ad un paese, e tutti gli apostoli gettarono via la pietra perché c’era il pane; e San Pietro rimase curvo per aver portato un pietrone senza alcun piacere/risultato."],"en":["They came to a village, and all the Apostles threw down their stones, because there was bread; and St Peter was left fuming, having carried a great slab for no reward at all."],"note":"“Arristò currivatu”: currivatu is “vexed, sulking” (curriva, spite); the 2023 Italian translation has “rimase curvo”, bent.","xml":"<div type=\"passage\" xml:id=\"sicily-I-4\" n=\"I.4\">\n            <p>Junceru ’nt'ôn paisi, e tutti l’Apostuli jittaru la petra pirchì cc'era lu pani; e S. Petru arristò currivatu ca avía purtatu un balatuni senza nuddu piaciri.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-I-4\">\n            <p>Giunsero ad un paese, e tutti gli apostoli gettarono via la pietra perché c’era il pane; e San Pietro rimase curvo per aver portato un pietrone senza alcun piacere/risultato.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-I-4\">\n            <p>They came to a village, and all the Apostles threw down their stones, because there was bread; and St Peter was left fuming, having carried a great slab for no reward at all.</p>\n            <note type=\"translation\">“Arristò currivatu”: currivatu is “vexed, sulking” (curriva, spite); the 2023 Italian translation has “rimase curvo”, bent.</note>\n          </div>"}],"gap":null,"itResp":"team2023","gulpease":70.1,"words":{"orig":220,"it":222,"en":242}},{"id":"sicily-II","kind":"episode","n":"II","heads":{"it":"Storia II","en":"Story II: the oven"},"refs":["gargano","bagheria"],"record":[],"passages":[{"id":"sicily-II-1","n":"II.1","start":true,"orig":["Camminannu camminannu, scuntraru a udu. Comu S. Petru java avanti; cci dissi: — «Viditi ca ccà appressu cc'è lu Signuri; addumannàticci la grazia di l’arma. » 'Ncugna chiddu, e cci dici :— «Signuri, haju a mè patri malatu di vicchiaja! Lu facissi stari bonu , Maistru. » Si vôta lu Signuri: — «E chi sugnu medicu io! Lu sapiti ch'aviti a fari ? 'Nfilatilu ’nt'ôn furnu, ca vostru patri addiventa un picciriddu. » Accussì fici chiddu, e sò patri addivintò un picciriddu."],"it":["Camminano, camminano, incontrarono un tale. San Pietro che andava avanti gli disse – “Guardate che qua con noi c’è il Signore; chiedetegli la grazia dell’anima.” Quello si avvicina e gli dice: – “Signore, ho mio padre malato di vecchiaia! Fatelo stare bene, Maestro.” Il Signore allora: “E che sono un medico io! Sapete cosa dovete fare? Infilatelo in un forno, così vostro padre diventa un bambino.” Quello seguì le indicazioni, e suo padre diventò un bambino."],"en":["Walking and walking, they met a man. As St Peter was going ahead, he said to him: “Look, the Lord is here just behind; ask him for the grace of your soul.” The man comes up and says: “Lord, my father is sick with old age! Make him well, Master.” The Lord turns: “And am I a doctor? Do you know what you must do? Put him in an oven, and your father will become a little child.” So the man did, and his father became a little child."],"note":null,"xml":"<div type=\"passage\" xml:id=\"sicily-II-1\" n=\"II.1\" rend=\"p-start\">\n            <p>Camminannu camminannu, scuntraru a udu. Comu S. Petru java avanti; cci dissi: — «Viditi ca ccà appressu cc'è lu Signuri; addumannàticci la grazia di l’arma. » 'Ncugna chiddu, e cci dici :— «Signuri, haju a mè patri malatu di vicchiaja! Lu facissi stari bonu , Maistru. » Si vôta lu Signuri: — «E chi sugnu medicu io! Lu sapiti ch'aviti a fari ? 'Nfilatilu ’nt'ôn furnu, ca vostru patri addiventa un picciriddu. » Accussì fici chiddu, e sò patri addivintò un picciriddu.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-II-1\">\n            <p>Camminano, camminano, incontrarono un tale. San Pietro che andava avanti gli disse – “Guardate che qua con noi c’è il Signore; chiedetegli la grazia dell’anima.” Quello si avvicina e gli dice: – “Signore, ho mio padre malato di vecchiaia! Fatelo stare bene, Maestro.” Il Signore allora: “E che sono un medico io! Sapete cosa dovete fare? Infilatelo in un forno, così vostro padre diventa un bambino.” Quello seguì le indicazioni, e suo padre diventò un bambino.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-II-1\">\n            <p>Walking and walking, they met a man. As St Peter was going ahead, he said to him: “Look, the Lord is here just behind; ask him for the grace of your soul.” The man comes up and says: “Lord, my father is sick with old age! Make him well, Master.” The Lord turns: “And am I a doctor? Do you know what you must do? Put him in an oven, and your father will become a little child.” So the man did, and his father became a little child.</p>\n          </div>"},{"id":"sicily-II-2","n":"II.2","start":false,"orig":["La spècia a S. Petru cci piaciu. Quannu si truvò sulu, java circannu di fari addivintari picciriddu quarchi vecchiu. Giustu giustu cci capita unu chi java a lu scontru di lu Maistru, pirchì avìa la matri ’n fini di morti, e la vulia fatta stari bona. San Petru dici: — «Chi cerchi ? » — « Cercu lu Maistru, ca haju a me matri, donna granni, ca è malata 'nfirma, e lu Maistru sulu pò essiri di dàricci la saluti. » — « E bonu ccà cc'è Petru; sai ch'ha' a fari ? camia un furnu, e ’nfilala ’nta un furnu e idda gualisci.» Ddu puvireddu cci critti, pirchì ca sapìa ca S. Petru era vulutu beni di lu Signuri; e va a la casa, e cuntanti cuntanti va a ’nfila a so matri ’nta la furnu camiatu. Nni vulistivu cchiù ? La vicchiaredda addivìntò un pezzu di carvuni. — « Ah ! santu di ccà e di ddà ! grida lu figghiu; la matri mi fici appizzari stu tignusu!... » Vota e va nni S. Petru. Cc'era lu Maistru, e comu senti la cosa, si misi a rìdiri ca nun si putia tèniri; dici: — « Ah ! Petru ! e chi facisti ?.... > S. Petra circava di scusàrisi, ma lu poviru figghiu jiccava paventi dicennu ca vulia la matri pirchì vulía la matri. La Maistru chi appi a fari? appi a jiri a la casa di la morta, e, cu ’na binidizioni chi cci fici, fici arrivisciri la vicchiaredda: 'na bella giuvina, e livò sta gran chiovu di supra a S. Petru."],"it":["Il trucco a San Pietro piacque. Quando si trovò da solo, cercò di fare diventare bambino qualche vecchio. Il caso volle che incontrò uno che andava dal Maestro perché aveva la madre in fin di vita, e la voleva guarita. San Pietro dice – “Chi cerchi?” – “Cerco il Maestro, che ho mia madre, una donna anziana, che è gravemente malata, e solo il Maestro può darle la salute” – “E bene! qua c’è Pietro; sai che devi fare? accendi un forno, infilala nel forno e vedi che lei guarisce.” Quel poveretto gli credette, perché sapeva che San Pietro era amato dal Signore; va a casa sua e senza pensarci infila sua madre dentro il forno acceso. Ne volete sapere di più? La vecchietta diventò un pezzo di carbone. – “Ah! Santo di qua e di là! grida il figlio, la madre mi ha fatto perdere ‘sto pelato!...” Prende e va da San Pietro. C’era il Maestro, e non appena sentì la storia, si mise a ridere senza riuscire a smettere; dice – “Ah Pietro! Ma che hai fatto?...” San Pietro cercava di scusarsi, ma il povero figlio imprecava dicendo che voleva la madre perché voleva sua madre. Il maestro che fece? Andò alla casa della morta, e, con una benedizione che le fece, la vecchietta tornò in vita: una bella giovane, e tolse a San Pietro di questo pensiero."],"en":["The trick pleased St Peter. When he found himself alone, he went about trying to turn some old person into a child. As luck would have it, he met a man on his way to the Master, because his mother was dying and he wanted her made well. St Peter says: “Who are you looking for?” “I’m looking for the Master, because my mother, an old woman, is gravely ill, and only the Master can give her back her health.” “Well then! Peter is here; do you know what to do? Heat an oven, put her in, and she’ll get better.” The poor man believed him, because he knew that St Peter was dear to the Lord; he goes home and, happy as can be, puts his mother into the heated oven. What more do you want to hear? The little old woman turned into a lump of charcoal. “Ah! Saints of here and there!” cries the son, “this scabby-head has made me lose my mother!…” Off he goes to St Peter. The Master was there, and as soon as he heard the story he began to laugh fit to burst; he says: “Ah! Peter! What have you done?…” St Peter tried to excuse himself, but the poor son was cursing, saying he wanted his mother because he wanted his mother. What was the Master to do? He had to go to the dead woman’s house, and with a blessing he brought the little old woman back to life: a beautiful young woman; and he pulled that great nail out of St Peter’s side."],"note":"“Livò stu gran chiovu di supra a S. Petru”, took this great nail off St Peter: freed him from his trouble.","xml":"<div type=\"passage\" xml:id=\"sicily-II-2\" n=\"II.2\">\n            <p>La spècia a S. Petru cci piaciu. Quannu si truvò sulu, java circannu di fari addivintari picciriddu quarchi vecchiu. Giustu giustu cci capita unu chi java a lu scontru di lu Maistru, pirchì avìa la matri ’n fini di morti, e la vulia fatta stari bona. San Petru dici: — «Chi cerchi ? » — « Cercu lu Maistru, ca haju a me matri, donna granni, ca è malata 'nfirma, e lu Maistru sulu pò essiri di dàricci la saluti. » — « E bonu ccà cc'è Petru; sai ch'ha' a fari ? camia un furnu, e ’nfilala ’nta un furnu e idda gualisci.» Ddu puvireddu cci critti, pirchì ca sapìa ca S. Petru era vulutu beni di lu Signuri; e va a la casa, e cuntanti cuntanti va a ’nfila a so matri ’nta la furnu camiatu. Nni vulistivu cchiù ? La vicchiaredda addivìntò un pezzu di carvuni. — « Ah ! santu di ccà e di ddà ! grida lu figghiu; la matri mi fici appizzari stu tignusu!... » Vota e va nni S. Petru. Cc'era lu Maistru, e comu senti la cosa, si misi a rìdiri ca nun si putia tèniri; dici: — « Ah ! Petru ! e chi facisti ?.... &gt; S. Petra circava di scusàrisi, ma lu poviru figghiu jiccava paventi dicennu ca vulia la matri pirchì vulía la matri. La Maistru chi appi a fari? appi a jiri a la casa di la morta, e, cu ’na binidizioni chi cci fici, fici arrivisciri la vicchiaredda: 'na bella giuvina, e livò sta gran chiovu di supra a S. Petru.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-II-2\">\n            <p>Il trucco a San Pietro piacque. Quando si trovò da solo, cercò di fare diventare bambino qualche vecchio. Il caso volle che incontrò uno che andava dal Maestro perché aveva la madre in fin di vita, e la voleva guarita. San Pietro dice – “Chi cerchi?” – “Cerco il Maestro, che ho mia madre, una donna anziana, che è gravemente malata, e solo il Maestro può darle la salute” – “E bene! qua c’è Pietro; sai che devi fare? accendi un forno, infilala nel forno e vedi che lei guarisce.” Quel poveretto gli credette, perché sapeva che San Pietro era amato dal Signore; va a casa sua e senza pensarci infila sua madre dentro il forno acceso. Ne volete sapere di più? La vecchietta diventò un pezzo di carbone. – “Ah! Santo di qua e di là! grida il figlio, la madre mi ha fatto perdere ‘sto pelato!...” Prende e va da San Pietro. C’era il Maestro, e non appena sentì la storia, si mise a ridere senza riuscire a smettere; dice – “Ah Pietro! Ma che hai fatto?...” San Pietro cercava di scusarsi, ma il povero figlio imprecava dicendo che voleva la madre perché voleva sua madre. Il maestro che fece? Andò alla casa della morta, e, con una benedizione che le fece, la vecchietta tornò in vita: una bella giovane, e tolse a San Pietro di questo pensiero.</p>\n          </div>\n\n<div type=\"passage\" corresp=\"#sicily-II-2\">\n            <p>The trick pleased St Peter. When he found himself alone, he went about trying to turn some old person into a child. As luck would have it, he met a man on his way to the Master, because his mother was dying and he wanted her made well. St Peter says: “Who are you looking for?” “I’m looking for the Master, because my mother, an old woman, is gravely ill, and only the Master can give her back her health.” “Well then! Peter is here; do you know what to do? Heat an oven, put her in, and she’ll get better.” The poor man believed him, because he knew that St Peter was dear to the Lord; he goes home and, happy as can be, puts his mother into the heated oven. What more do you want to hear? The little old woman turned into a lump of charcoal. “Ah! Saints of here and there!” cries the son, “this scabby-head has made me lose my mother!…” Off he goes to St Peter. The Master was there, and as soon as he heard the story he began to laugh fit to burst; he says: “Ah! Peter! What have you done?…” St Peter tried to excuse himself, but the poor son was cursing, saying he wanted his mother because he wanted his mother. What was the Master to do? He had to go to the dead woman’s house, and with a blessing he brought the little old woman back to life: a beautiful young woman; and he pulled that great nail out of St Peter’s side.</p>\n            <note type=\"translation\">“Livò stu gran chiovu di supra a S. Petru”, took this great nail off St Peter: freed him from his trouble.</note>\n          </div>"}],"gap":null,"itResp":"team2023","gulpease":72.3,"words":{"orig":347,"it":306,"en":353}}],"glossary":[{"forms":["Maistru"],"it":"Maestro","en":"Master","src":null},{"forms":["tridici"],"it":"tredici","en":"thirteen","src":null},{"forms":["paisi"],"it":"paese","en":"village","src":null},{"forms":["pani"],"it":"pane","en":"bread","src":null},{"forms":["petra","petri"],"it":"pietra, pietre","en":"stone(s)","src":null},{"forms":["nica"],"it":"piccola","en":"small","src":null},{"forms":["lèggiu"],"it":"leggero","en":"light","src":null},{"forms":["accattamu"],"it":"compriamo","en":"we buy","src":null},{"forms":["binidizioni"],"it":"benedizione","en":"blessing","src":null},{"forms":["pitrudda"],"it":"sassolino","en":"pebble","src":null},{"forms":["manciu"],"it":"mangio","en":"I eat","src":null},{"forms":["gravusi"],"it":"carichi","en":"heavy-laden","src":null},{"forms":["mariuolu"],"it":"furbo, birbante","en":"rascal","src":null},{"forms":["picciotti"],"it":"ragazzi","en":"lads","src":null},{"forms":["tanticchia"],"it":"un pochino","en":"a little","src":null},{"forms":["balatuni"],"it":"lastrone","en":"great slab","src":null},{"forms":["currivatu"],"it":"indispettito","en":"vexed","src":null},{"forms":["vicchiaja"],"it":"vecchiaia","en":"old age","src":null},{"forms":["furnu"],"it":"forno","en":"oven","src":null},{"forms":["picciriddu"],"it":"bambino","en":"little child","src":null},{"forms":["matri"],"it":"madre","en":"mother","src":null},{"forms":["carvuni"],"it":"carbone","en":"charcoal","src":null},{"forms":["tignusu"],"it":"tignoso, pelato","en":"scabby-head","src":null},{"forms":["vicchiaredda"],"it":"vecchietta","en":"little old woman","src":null},{"forms":["giuvina"],"it":"giovane","en":"young woman","src":null},{"forms":["chiovu"],"it":"chiodo","en":"nail","src":null}],"gulpease":71.4}};
